/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240826-9","meetingId":"r06-cm08","date":"2024年8月26日","dateIso":"2024-08-26","committee":"文教委員会","time":"午後 １時００分～午後 ４時２５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"令和７年度品川区立学校使用教科用図書の採択","agenda":"令和７年度品川区立学校使用教科用図書の採択","exchanges":[{"speaker":"高橋（し）委員","kind":"質問・要望","question":"関連して、まずは８月８日の教育委員会の審議の内容を調べようと思ったのですけれども、議事録、会議録は後日掲載予定となっていて、６月１１日分が載っているだけで、それより後の会議録が載っていないのです。どれぐらいのめどで通常載せようとしているのか、どれぐらいの期間で載せようとしているのかということを教えてください。影響してくると思うので、すみません、その２点をお願いします。","respondent":"舩木庶務課長","answer":"なるべく早く議事の内容を公開できるように今後努めていきたいと、このように考えております。","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２、３か月ということなのですが、もちろん正確性を求められますし、大切なチェックだと思うのですけれども、本当に１か月でも２か月でも早く公開できるようにしていただかないと、委員会での審議、そのほかのところにつながってくると思うので、これはお願いしますということです。その中に、ある教育委員の方は、他業務との関係で審議に参加することができないと。","respondent":"丸谷教育総合支援センター長","answer":"委員の１名に関しまして、他業務に関連して教科書採択に差し障りがある業務に従事している、ということで、採択事務には関わらないということで退席をしていただいております。","id":"exchange-002"},{"speaker":"高橋（し）委員","kind":"質問","question":"その関わる業務というものは、もう少し詳しく教えてはいただけないのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"委員それぞれのお立場に関わることですので、この場でのご回答を控えさせていただければと思います。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"回答は控えするということで、そこは納得しました。ただ、この委員の方は、教育委員会の委員の方の中でも大変に教育的な見識が高く、教育的、専門的な判断というか、そのようなお考えをお持ちの方だと私は思っています。ですから、その方が参加できない状況で、このように教科書選定が進んでいくという動きに関して、どのようにお考えでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"とはいえ、教育委員会の委員それぞれが、事前に教科書の検討委員会で作成した資料を読み込んでいただいて、教科書も手に取って触れていただきながら採択事務に関わっていただいておりますので、その辺りは。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"議会で教育委員を選任同意させていただいたわけですけれども、この委員の方が非常に高い見識をお持ちで、教育行政に委員として相当なお力を発揮できるという認識があって、選定をしたところなわけです。ですから、このような場で力を発揮していただくことがとても大事だと私は思っています。私としては、何らかの形で審議に参加していただくことを望みたいと思うのですけれども、そこはいかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"他業務の関係で今回は事務に関わることができなかったわけですけれども、次回は令和９年度に小学校の教科用図書の採択事務を予定しております。","id":"exchange-005"},{"speaker":"高橋（し）委員","kind":"意見","question":"次回ということで、どうなるかはまたそのときにということなので、そこは承知しました。大きく。そして令和７年度もそれでいこうというような話だったのですけれども、その点について、算数の今までのその教科書会社での成果と、変わったということについて、残念ながらそこの点についての、会議録にはそのようなことについて出てきていないので、もし分かれば、その辺の話をお尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"教科書が学力向上に資するということで、子どもたちが自学自習に教科書用いたり、また、教員が指導する際に教科書を用いたり、非常に大きな意味があるかと思いますが、今回採択された小学校の教科書、令和５年度に採択した教科書につきましては。","id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"教科書を教えるのですが、教科書で教えると言われていますし、先生方のいろいろな授業のご努力でそういった学力があったと思うので、ただ、これは何年かたってみないと、教科書が変わったことの数字的なところの判断ができないと思うのですけれども、それはまた学力テスト等の結果や、あとは使われている先生方の授業の展開に関してその教科書がどうかということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"私は教育委員会の議事録のほうではなくて、区役所のホームページのほう、今回、令和７年度から新たな教科書がということで、前回でいうと令和３年から令和６年の中学校での使用教科書の採択理由や、まずはどのような教科書が採択されたか、そしてそれがなぜ選ばれたのかということがホームページに載っていたので、同様の視点から今回はどうなのかということで確認をしようと思ったところ、こちらも。","respondent":"丸谷教育総合支援センター長","answer":"８月いっぱいで採択事務を終了させるということで国のほうでスケジュールが決まっておりますので、９月に入った時点、９月の上旬から中旬までには、ホームページへの掲載を考えてあります。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"今まとめている段階で、これも来月にというお話でありました。今の段階における評価をちょっとお伺いしたいのですが、先ほど高橋委員は数学、算数の教科を取り上げていらっしゃいましたけれども、私は社会の中の歴史的分野の教科書についてちょっと確認をさせていただきたいです。変わった理由を採択理由のところに当然書かれるのだろうと思いますが、そこをまずお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"４年に一度教科書採択を実施するわけですけれども、前回使っていた教科書の出版社との比較ではなくて、その採択を行う年度の前年度に文科省で検定を行っておりますが、その検定教科書、検定を通った教科書を比較して。","id":"exchange-009"},{"speaker":"田中委員","kind":"意見","question":"そうすると今日の質疑はあまりできないということですね。来月、９月にホームページに掲載されましたら、その内容を踏まえて、ぜひ委員長のお計らいで、このテーマについての質疑の時間を、その他にするのかどうかは別として、ぜひお願いをしたいなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"は選定理由を伺ってみないと、その後の深く掘れるのかどうなのかが判断できませんけれども、深掘りも含めて、次回か、今後の委員会に、まずは報告していただくということと、それに併せて今回の教科書採択についての質疑は改めて行っていただきたいということです。","respondent":"こんの委員長","answer":"今この場では、どうする、こうするという、お答えはできませんので、一旦このことはお預かりをさせていただいて、正副で検討する、あるいは理事者の方ともご検討するということでよろしいでしょうか。では、お預かりします。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"そうしましたら、併せて、もし分かればなのですが、他区の比較をする必要があるかどうかは別としても、この客観的な教科書選定においての評価をしていく上で、他の、特に２２区、ほかの区が、特に社会の歴史的分野において具体的にどのような教科書を採択されているのか、ちょうど品川区も含めて、これから公表されるタイミングなので、まだオープンになっていないところもあるのかもしれませんが。","respondent":"丸谷教育総合支援センター長","answer":"昨年度の例でいいますと、令和５年１１月１６日付で、東京都の教育委員会のホームページに各地区の採択結果が掲載されておりますので、今年度につきましても大体同じぐらい、同様の時期に公表されるものという認識でおります。","id":"exchange-012"},{"speaker":"田中委員","kind":"意見","question":"採択理由、また地区についてはどのような状況だったのかということも含めて、ぜひ正副委員長のご協議の上で、しっかりと質疑をしていきたいという希望がありますので、お取り計らいをよろしくお願いして、今日のところは私の質疑は終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"確認","question":"ただ、文部科学省のほうにその出版社が取消しをしに行ったのが８月８日であるということで、先ほどの高橋委員との質疑の中で、８月８日に選定をしたというようなお話がありましたけれども、そのときは知る由もないというか、そういったことが、ちょうどその日が重なっているということなのですが、このことに対して、出版社から何らかの説明が教育委員会にあったのかどうか、確認したいと思います。","respondent":"丸谷教育総合支援センター長","answer":"その８月８日の時点で、文部科学省に削除依頼をしているということでの回答をいただきました。その旨を教育委員にも事前にお伝えをして、採択のほうさせていただいたという流れです。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問","question":"分かりました。教育委員会としては、それを除いて、ほかの内容については問題がない、もしくは適しているという判断をされたということでよろしかったでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"委員おっしゃるとおりで、その他の部分には問題ございませんので、そういった形での採択をしています。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"確認","question":"分かりました。その掲載された方が不祥事を起こすかどうかということは、教育委員会は知る由もないことなので、これはある意味突発的なことだと思うのですけれども、今回はアンテナ高く、すぐに問合せをしていただいて、その上での検討の結果だということを確認させていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"せらく委員","kind":"質問","question":"私からは、教科書の展示会についてお聞きしたいと思います。教育総合支援センターで７月２０日まで行われていた教科書展示に初めて伺いました。そこでいらっしゃった方の名簿というか、お名前を書くところがあったと思うのですけれども、例えば近年や前回と比べてなど、どのくらいの方がいらっしゃっているかということがもしお分かりであれば、お聞きしてみたいです。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示会についてのご質問です。教育総合支援センターと品川図書館の２か所で実施をしているところですけれども、お名前を書いていただいた方が延べ９０名いらっしゃいました。","id":"exchange-017"},{"speaker":"せらく委員","kind":"質問","question":"私も初めて伺ってみて、すごくたくさんの種類の教科書があって、どれがいいなどとということがどのように感じるのかなと思っていたのですけれども、見始めたら本当にそれぞれ違って、全て見てしまって、結果、感想やアンケートを書く用紙があったと思うのですが、それも書かせていただいたのですけれども、そういった皆様のお声、見学者のお声など、そういった部分は。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示会の来場者数や、その意見をいただいておりますので、そちらも今取りまとめている最中でございまして、取りまとめが終わったところで、教育委員会会議でも報告を差し上げているところです。","id":"exchange-018"},{"speaker":"せらく委員","kind":"質問","question":"そうしましたら、その教科書採択の会議では、まだ皆様のお声が届かない状態で採択をする会議というようになっているということでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示会のほうの期間と、教科書採択で５回に分けて仮採択と本採択と行っているのですけれども、並行して行っておりますので、当日お越しいただいた方のご意見というものは、教育委員には共有されていない中での仮採択、本採択という形になってあります。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問","question":"そうしましたら、いただいたアンケートのお声などは、今後の教科書採択に反映していくというような形で、教育委員会での共有がされるというように認識させていただいてよろしいでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味で、最終的にこのような意見がありましたということで報告は差し上げるのですが、その後、何か採択に影響するということがないようにはなっております。","id":"exchange-020"}]},{"id":"topic-02","title":"育児休業にかかる保育認定期間の見直し","agenda":"育児休業にかかる保育認定期間の見直し","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"２点お伺いさせていただきたいと思うのですけれども、親御さんたちにとって、年齢制限の撤廃は大変ありがたいことだと思うのですが、そうすることになった経緯といいますか、いろいろと区民の方から声があって、今のこのタイミングでそうするようになったのかと思うのですけれども、その辺りの状況をお聞かせいただきたいです。こちらの１のところに、認可保育所等というように書いておられました。","respondent":"芝野保育入園調整課長","answer":"品川区でも検討しまして、また、他区の状況も確認したところ、６区では制限を撤廃しているというような状況でありますので、品川区も負担軽減という考え方の下、今回見直しをすることになりました。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"１０月以降、区民の方に保育園のご案内やホームページ等々で周知をされるということなのですけれども、要はその際の表現なのですが、ここに書いてあるような、変更前は育児休業に係る子どもが１歳に達する日の属する年度の末日までの期間など、いわゆる条例の文言のような表現にここはなっておりますけれども、より具体的に分かりやすく、ご理解いただけるような表現での周知をぜひお願いしたいと思いますが。","respondent":"芝野保育入園調整課長","answer":"実際に周知するときの表現ですが、これから規則改正もするところではありますけれども、規則改正の文言とはまたちょっと変えて、利用者の方に分かりやすい表現で周知、案内をしていきたいと思いますので、ちょっとこれから検討させていただきたいと思います。","id":"exchange-022"}]},{"id":"topic-03","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"先ほどの一時保護所との関係なのですけれども、やはり品川区の児童相談所ということで、保護されているというところで、やはり保護者の方が取り返しに来る、もしくは、何かクレーム等で押しかけてくるということも重々あり得る話であって、そういったときに、たしかご説明の中では、区の職員ではなくて外部委託をするというようなことで先ほど伺ったのですが。","respondent":"長谷川児童相談課長","answer":"品川区としては公表しております。２点目としまして、保護者が取り返しに来ることも想定されるけれども、１階の警備の方はどのように対応するのかという趣旨というように受け取りました。当然取り返しに来ることも、想定としてはあり得ると考えています。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ご説明分かりました。これからつくり上げていく部分もあるということで、確認をさせていただきました。委託業者のコールセンターのところだけ、もう１回確認なのですけれども、判断シートをこれから作成されていくということ、他の自治体の事例も見ながらということでした。ここについて、もし予算がついてくるのであれば、議会は喜んで賛成をすると思いますので、それについては要望として伝えします。","respondent":"長谷川児童相談課長","answer":"夜間休日のコールセンター方式による受電の際に、疑わしい通報があった場合、どうするかという趣旨の質問だったかと思います。委員ご指摘のとおり、疑わしい場合は全て区の児童相談所のスーパーバイザーのほうに連絡が来るようになっております。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問","question":"私も何点かまとめてお伺いをしたいと思います。その体制として、特に一時保護部門になろうかと思いますけれども、この１４４名体制で、今後の子どもがどのような状況になるのかにももちろんよるのですけれども、２４時間対応、電話の受付もそうですが、今後の運営の中で十分賄える人員配置になっているのかということを、まずお伺いしたいと思います。","respondent":"長谷川児童相談課長","answer":"ただ、今後に関しては、当面は区のプロパー職員での運営を行っていくことを基本に考えておりますので、受入れを行う予定は現時点ではありません。最後、３点目としまして、１４４名という人数規模が適切なのかどうかということでのご質問かと思います。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"皆さん極めて重要な役目の方々です。今一緒に聞けばよかったのですが、特にスーパーバイザーの方の確保が極めて重要で、なかなか人材がそろわないということを、品川区以外のところから伺ってはいるのですけれども、このスーパーバイザー、児童福祉司の方が５人と児童心理司の方が２人ということですが、この数はどうなのでしょうか。もう少し必要なのか、十分なのかということについて、いかがでしょうか。","respondent":"長谷川児童相談課長","answer":"スーパーバイザーの確保に関しまして、これも非常に重要かつかなり困難な部分であると認識しておりまして、とりわけ児童福祉司のスーパーバイザーは、児童福祉司として５年以上、もっと厳しいのが児童心理司スーパーバイザーは心理分野で１０年以上ということで。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"しっかりとその人員体制、引き続き整えていただけるように、ご尽力をお願いしたいと思います。今後、組織として分けていくことを、今まで同様に継続していくことのほうがいいのか、もう子ども家庭支援センターの業務も、今後の児童相談所の中に組み込む中で対応することのほうがより対応できるようになってくるのか、その辺の今お考えはいかがでしょうか。","respondent":"長谷川児童相談課長","answer":"品川区としましては併存型という形を選択いたしましたけれども、施設の機能の、役割の違いがあるというところで、児童相談所としては、あくまでも法的対応というところになってくるので、例えば虐待が発生する前に、事前に各家庭を回ったり。","id":"exchange-027"},{"speaker":"田中委員","kind":"意見","question":"今後、どのような体制が一番子どもにとって最善の対応なのかという視点に立って考えていただいて、今まで分かれていたからそのまま分かれるなど、そのようなことではなくて、それこそ子どもの立場に寄り添った組織づくりを、対応をお願いしたいと思います。特に品川独自のものについて。","respondent":"長谷川児童相談課長","answer":"他自治体の一時保護所、当然視察していますけれども、同様に公開していないというところがありますので、個別の比較についての回答は差し控えさせていただきたいと思いますが、品川区としては、子どもたち一人ひとりの権利に寄り添った支援ができるように。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"特に練馬区長にはぜひ見てもらいたいなという強い思いはあったのですが、それは、では公表されていないということなので、ちょっと残念ではありますけれども、ただ、いい形で、要は都から区に移管されてよかったと。そのことによってこれだけよくなったということが、何でしょうか、じんわりと公表されるというか、伝わるようなことを願いながら、質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"西村委員","kind":"質問・要望","question":"視察もありがとうございました。定員について伺いたいなと。一時保護の定員についてなのですけれども、都の実績ベースとおしゃっていたと思います。今現在、品川区で１４名と伺っておりまして、需要が高まっているというお話もありましたので、この１４名というところを超える可能性はあるのか、今の一時保護の都のほうの実績もあると思いますので、伺えればと思います。以上２点、お願いいたします。","respondent":"長谷川児童相談課長","answer":"品川区の施設としましても、定員は１４名なのですけれども、居室レイアウトは少し広めに設定しているということもありますし、また、必要な保護はちゅうちょなく実施する必要があるという考え方もありますので。","id":"exchange-030"},{"speaker":"西村委員","kind":"質問","question":"システムのほうはよく分かりました。一時保護の定員のところなのですけれども、今の東京都児童相談所、北品川のところが、一時保護所がなくて、他区にそれぞれ行っているというように理解しておりまして、新しくできる、今日視察に行かせていただいたところも、品川区以外のお子さんを受け入れるようなことというのは可能性としてあるのかということだけ、最後に伺わせてください。","respondent":"長谷川児童相談課長","answer":"これは様々なケースが考えられますけれども、例えば加害被害の関係や、同じ施設で保護することが適当でないケースに関しては、品川区のお子さんであっても、他区の児童相談所、あるいは他自治体の児童相談所にお願いをするケースもあろうかと思いますので。","id":"exchange-031"},{"speaker":"せらく委員","kind":"質問","question":"視察と説明をいただきまして、ありがとうございました。私からは２点お伺いしたいと考えています。区立児童相談所は一時保護など法的対応というように書いてあり、子ども家庭支援センターは寄り添い支援ということなのですけれども、これ実際に区民の方が、お問合せ、対応、お願いや相談をするときの、まず第１の窓口というものは、今後、１０月以降は児童相談所になるということなのでしょうか。","respondent":"長谷川児童相談課長","answer":"新聞報道等でもあるリスク判定、いわゆるリスク判定に関しましては、現状品川区としては導入の予定は、現時点ではありません。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ご説明ありがとうございました。それが１つ。これに関して今区の所管で検討していることは、条例改正、あるいは規則や要綱の変更や、加筆というのですか、そのようなものがあるのでしょうか。それが２つ目です。今までそういった扱いをなかなか、した経験があるというか、そのような方がいないと大変な事務ではないかと聞いているのですが、その辺の対応はいかがでしょうか。","respondent":"染谷子ども家庭支援センター長、長谷川児童相談課長","answer":"現状、東京都の児童相談所との業務につきましては、東京ルールという基準に基づいて実施しているものではありますけれども、今回改めて共通のリスクアセスメントシートを用いて。この療育手帳の判定事務に関しましても、当然やったことがないとできないわけですけれども、これまで児童相談所開設に向けて様々な区に派遣研修をお願いしておりましたので、その中で、療育手帳の判定事務に関しましては。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうございました。子ども家庭支援センターについては、今お話にあったようにプラスの面、よりよくなると伺ったので、ぜひ緊密に区立児童相談所と連携して進めていっていただければと思います。療育手帳については、非常に、なかなか難しい側面もあるところが今後出てくると思いますが、経験をされた方もいらっしゃるということですので、円滑に進めていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"山本副委員長","kind":"質問","question":"人員体制や定員の考え方、ＡＩ電話の概要や子ども家庭支援センターとの連携などのご質問についてはほかの委員からの質問がありまして、理解しました。私からは１点、相談受付後の対応についてご質問をいたします。ですから、一時保護を施設ではなくて、中には短期預かり里親に預けるというほうがその子のためによいという場合も、考えもあると思います。","respondent":"長谷川児童相談課長","answer":"短期入所里親、ご紹介いただきましたけれども、それを含めて、施設のグループホーム含めて、なるべく小規模の体制のところで見ていただいたほうがいいお子さんもいらっしゃれば、またその逆もいらっしゃるということで、個別のケースワークの中で。","id":"exchange-035"},{"speaker":"山本副委員長","kind":"意見","question":"実際に短期預かり里親を進めるに当たっては、その預かり里親の支援だったり、サポートだったりなども必要になってくるので、実際進めていくにはいろいろと詰めるべきところもあると思うのですけれども、先ほど言っていただいたようなケースワークの中でのお子さんに寄り添って、そのお子さんに合った対応をできるだけ進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-04","title":"の５のその他","agenda":"の５のその他","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"私からもありがとうあります。それともう１件は、それはご主人が電子申請で申し込んだ。１点だけ、要望というか、当然初めてのことでもありますし、たくさんの仕事を児童センターの職員の方も抱えながらの作業だと思いますので、ある意味仕方のないことではあると思うのですが、これからもそういった受付については、速やかにスムーズにいくようにお願いをしたいと思いますけれども、いかがでしょうか。","respondent":"藤村子ども育成課長","answer":"児童センターのお米の配付の件につきましては、館長はじめ職員のほうには周知しているところなのですが、多少行き渡っていないというところがあったのかなと思いますので、そちらについては今後も第２弾もありますので。","id":"exchange-037"},{"speaker":"山本副委員長","kind":"意見","question":"私からも１点だけ。今まさに進めていらっしゃるところだと思うのですけれども、この狙いの１つに、取りに来たお子さんとコミュニケーションを取って次の支援につなげるというような目的もあるということだったと思うのですが、それが現状、児童センターに取りに来た子どもたちとのコミュニケーションなどが取れているのかどうかということをお聞かせいただければと思います。","respondent":"藤村子ども育成課長","answer":"今直接何かにつながったというところまでは報告は入ってきていないのですけれども、そういった形で何かアウトリーチ支援というところでつながるようにやっているところです。","id":"exchange-038"},{"speaker":"山本副委員長","kind":"質問・要望","question":"今お声かけをいただいているということで、続けていただきたいと思いますし、また何かそこの中で気づいて次の支援につなげられることがあればぜひつなげていただきたいと思うので、そういった仕組みが児童センターで対応されている皆様にも、きちんとそのようなものに気づいたときにはつなげるようにということでご周知いただいて、そういった場合にはつなげていただけるように進めていただければと思います。","respondent":"藤村子ども育成課長","answer":"児童センターの職員のほうは日頃からそういったところを気配りしてやっておるところですので、さらに周知して、徹底するように伝えてまいりたいと思います。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/799105?Template=document&Id=6789#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":28911,"voices":119}},{"id":"r06-20240826-5","meetingId":"r06-cm08","date":"2024年8月26日","dateIso":"2024-08-26","committee":"総務委員会","time":"午後 １時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"令和６年度都区財政調整交付金当初算定結果","agenda":"令和６年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"松本委員","kind":"質問","question":"これは相変わらず、なかなか複雑な制度だといつも思うのですけれども、以前の総務委員会でトイレトレーラーの話があって、いろいろと債券が使えるかどうかという話のやり取りを課長とさせていただいたかと思うのですけれども、そのときに、起債はせずに一般財源でやりますというお話があって、それに加えて、基準財政需要額に入れてもらえるように調整中ですというお話があったかと思います。お願いします。","respondent":"加島財政課長","answer":"トイレトレーラーについては各区普遍のものではございませんので、幾つか算定率が掛かってまいりますが、そちらで手当てされるように申請を行っているところで、結果についてはまだ出てきておりません。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"割合５５.１％というのはいろいろと調整を図ってやられるのだと思うのですが、毎回、交渉するときに、これは少ないのではないか、もう少し上げるべきなのではないか。そういう中で、５５.１％というのは今後どうなるのかと。それと、トイレトレーラーの話もありましたけれども、普通交付金になるのですか。その決め方というのが何かお分かりになったら教えてください。","respondent":"加島財政課長","answer":"配分割合の件ですけれども、令和５年度、財政調整協議が中断いたしまして、配分割合の変更というのがその時点ではかないませんでしたが、今現在のところ、委員からもございましたとおり、５５.１％対４４.９％となっているところです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"結局、割合については、なかなか中身に入っていけない部分があり、また中身のほうは東京都の要望と要求度というか考え方と、各区の自治体の考え方は多分ずれているのがあって、なかなか進んでいない。どれぐらい都区間の協議が必要な項目があって、ざっとでいいのですけれども、それの進捗具合はどうなのだろうと思うのです。これからの流れ、これからの進み具合などを少し教えてほしいと思います。","respondent":"加島財政課長","answer":"ただ、それぞれお隣の区とはいいましても、品川区には品川区のニーズ、それから別の区には別の区のニーズもありますので、状況を見て、必要があるといった場合には、財政調整算定の結果いかんにかかわらず、区として取り組んでいくこともあると考えております。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"こういうふうに、東京都でこれだけのお金が入っていて、別にグループ云々ではなくて、固定資産税の一定の売買額に応じて、資産の額に応じて増税される。本当に品川区全体を見たら、自治体としたらいいことですけれども、その先の使い方ということも考えていく必要があるのではないかと私は思うのですが、これは議論するつもりはないのですが、その辺のご見解だけお聞かせくださいますか。","respondent":"加島財政課長","answer":"今年度来ます財政調整交付金につきましては、令和６年度の歳入として様々、当初予算等でご提案申し上げて、事業に充当するものですが、今後また国の交付金などの動き等を捉え、低所得者層、それからそういった様々な層に行くようにというところで。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"区として様々なところに目を向けて支援をしたり補助金を出したりしているのは、我々も見て分かります。そういう層に対して、今回はたまたまということなのかもしれないですけれども、こうやって収入が増えているようなときに、やはり品川区としても、そういう層に目を向けて、もっと支援をするように何か対応していただきたいと私は思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"立会川児童遊園（その３）・旗の台北公園改修工事請負契約","agenda":"立会川児童遊園（その３）・旗の台北公園改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"今説明されていて聞き漏らしたかもしれないのですが、改修工事ということで、もう前回、一部、公園の中で改修しているところもあったように見えたのですが、どれぐらい年数がたっていて今回やるのか。それで、この改修工事というのは、もう定期的に、十何年したら一律に、仮にあまり傷んでいなくても改修するのだという方向性にあるのか。その辺について少しお聞かせください。","respondent":"佐藤経理課長","answer":"２点、ご質問いただいたかと思います。今回改修する公園部分ですけれども、２か所ありますが、立会川児童遊園については、昭和４９年に開園ということで、５０年ほど経過しております。旗の台北公園も昭和６０年ということなので、開園から３５年以上経過しているという状況です。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"植栽、それからインターロッキングブロック舗装工などというのがあるのですが、インターロッキングブロック舗装というのは、人がはめ込んで造っていく道路なので見栄えはきれいでしょうけれども、結構、手間、予算もかかるし、現実論、問題点として、つなぎ目から草が生えてきたり、あとブロックをどんどん差し込んでいるだけですから、段差が生まれたりして。","respondent":"佐藤経理課長","answer":"後段のところですけれども、公園のしつらえのところかと思いますが、それは所管の公園課で考えるところかと考えます。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"日頃、皆さんが生活道路としても使われているところなので、メンテナンスもあまり時間がかからないような舗装にしたほうがいいのではないかと思いますが、その辺、歩きにくいというような方向性に行かないようになることを望みます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"今回、立会川児童遊園と旗の台北公園というのが隣接しているから、この２か所の入札という形との理解でいいでしょうか。これは、大体あそこだろうと思うのですけれども、かなり隣接しているという、続いているような感覚です。場所が似たようなところだから一緒に予算を立てたというか、今回、入札に至ったということでよろしいですか。","respondent":"佐藤経理課長","answer":"所管で予算要求して出しているところですけれども、おっしゃるとおり、こちらは立会川緑道の公園ということで連続して整備されているというところですので、一定の部分に沿って、年々工事していると把握しております。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"当然ながら、たくさんあれば、老朽化というのは当然あるわけで、そうすると、区内に３００か所近くあったのではないですか。防災広場もあったと思うのですけれども、そちらを整備するに当たっての計画みたいなものはある程度なされていて、予算化もそういう中で進めていくという認識でよろしいですか。その準備を進められているという認識でよろしいでしょうか。","respondent":"佐藤経理課長","answer":"所管で進めるところかとは思いますけれども、公園がある中で、老朽度合いを比較してといいますか、並べて、必要性の高いところから順々に計画的に進めていると聞いております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"所管の計画と全体の計画というのはどういう整合性が取れていますかというのは、要は所管はやりたいと思っても、全体的に見るとそれは早いなどという、待ったがかかったりする場合もあると思うので、そこは長寿命化というのができているわけだから、当然ながら、それは所管と経理課で話し合いながら進められているという認識でよろしいでしょうか。それをお聞きしたのですけれども。","respondent":"佐藤経理課長","answer":"今回、契約案件のご報告ということなので、経理課としましては、契約に係る事務を所管しておりますので、繰り返しになりますけれども、長寿命化の計画を所管で持っていて、その上で、予算編成の中で、企画経営部で査定ということになりますので。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ計画を立てていく中で、それなりに交渉しながら、決めながらということでやっているということであるならば、それはもう安心しているわけでありますけれども、当然、こういう建物や公園などは、いずれにしても改修しなければいけない時期は分かっているわけだから、その計画はなされているはずだろうという中に、要望もあれば。","respondent":"佐藤経理課長","answer":"今回は契約案件のご報告ですので、その範囲ということになってしまいますけれども、予算編成の中では、そういった委員ご指摘のところも踏まえて予算化されていると考えております。","id":"exchange-012"}]},{"id":"topic-03","title":"契約事務の変更","agenda":"契約事務の変更","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"１の電子契約の導入のところで、対象が１,０００万円以上の一般競争入札の契約ということで、これは数はどのくらいあるのですかというところと、全体としてはどのぐらいの割合、ボリューム感かを教えていただければと思います。","respondent":"佐藤経理課長","answer":"続いて印紙税の負担が減るというところでご説明したところですけれども、印紙税につきましては契約金額に応じて金額が変わるというところでして、例えば工事請負でいきますと、契約金額１,０００万円であると５,０００円というところで、あとは１億円だと３万円。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"分かりました。これはちなみに印紙税、１,０００万円で５,０００円というところで、１,０００万円以上というところの線引きは、今回こういう形で報告が出てきているのですけれども、１,０００万円未満の方たちにかかるというところでは、今後、引下げというところの考え方もあったりするかと思う中で１,０００万円以上にしたというところと、今後の考え方がもしあれば教えていただきたいと思います。","respondent":"佐藤経理課長","answer":"令和６年度にも、品川区を含めて８区、予定があると聞いております。正直、始めたばかりというところもありまして、１,０００万円以上ですと、いわゆる一般競争入札の金額に当たります。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"ところが、こういうことで、１億円でも２億円でも前払金を増やす。民間企業では、始める前に３分の１、中間で３分の１、終わったら残り３分の１というような支払い制度にのっとって皆さんやっている。ただ、どうも公共工事というのは違うようなので不思議だと思うのですが、運転資金が厳しい会社と今後も契約し続けていっていいのだろうかと心配してしまうのですが、その辺について、どうなのでしょうか。","respondent":"佐藤経理課長","answer":"運転資金がないところというお話でしたけれども、まずは契約の相手方というところですけれども、こちらについては、工事の規模によって制限付き一般競争入札と言っておりますけれども、これは条件をつけておりまして、一定程度の規模以上の会社。","id":"exchange-015"},{"speaker":"須貝委員","kind":"質問","question":"事業者の利便性がやはり出てくると思うので、これはいいと思うのですが、別の問題で契約事務ということで申し上げると、千代田区で最近、入札あっ旋、収賄等の問題がありましたけれども、こういうことが品川区で起きないような外部調査機関や、品川区の庁舎の中で調査する部署というのはあるのですか。それともそういうものは、品川区においては何もないのですか。教えてください。","respondent":"佐藤経理課長","answer":"ご質問のほうからお答えしますと、そういったものを調査する組織というのは、常設でないかとは思いますけれども、例えば何かあれば総務課でコンプライアンス推進担当が設置されておりますが、そちらに相談しながら、あるいは今回、千代田区でもこの件を受けて第三者委員会を。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区は今のところ、ありがたいことに新聞に載るような話は聞こえてきませんけれども、やはり同じような２３区の自治体で官製談合があったということは、ゆゆしき問題なので、あくまで契約というのは、人と人が対峙して、対話して結ぶものですから、どうしても間違う方向に進むこともあると思います。ぜひ、そちらも区として、コンプライアンス推進担当はまだできたばかりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"ご説明ありがとうございました。私から電子契約の件をお伺いしたいのですけれども、印紙代は印紙税の負担軽減というところはあると思うのですけれども、行政側としては電子契約導入でコストはどういうふうに考えればいいのか、費用面のところをお願いいたします。","respondent":"佐藤経理課長","answer":"電子契約にかかるコストですけれども、今回、導入に当たっては予算を計上させていただいておりまして、１１０万円余を今年度予算として計上しております。ただ、このうち８０万円余は初期導入経費ということで、年々の経費でいきますと３０万円弱というような形になっております。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"これは、初期費用が多分、電子証明の会社と契約してかかる部分もあるかと思います。それに加えて、１件当たり幾らみたいな感じで費用がかかってくるのか。その辺りはいかがでしょうか。","respondent":"佐藤経理課長","answer":"以降のかかる経費については、いわゆるインターネット上のサーバーというか、サービスを利用するということなので、そのサービスの利用料というところで３０万円弱となっておりまして、１件幾らということにはなっておりませんので、そこについてはかからないです。","id":"exchange-019"},{"speaker":"大倉委員","kind":"質問","question":"２の限度額拡大のところで言うと、５０億円を超える公共工事と。今後また大きな工事があるときには、１割で何十億などと出せるようにしておくというのは、企業側としては非常にありがたいのかと思うのですが、その辺は、どういうお話や、どういうヒアリングをかけて、どういう話合いが向こうから出てきているなど、そういう状況を教えていただけるとありがたいです。","respondent":"佐藤経理課長","answer":"ただ、一定の５億円というところ自体はありがたいのだというお話もありましたので、それを超える部分について、ずっと５億円というわけにもいかないだろうというところもありまして、他区や東京都の規定ぶりも見まして、一定のところで拡大するという判断をしたものです。","id":"exchange-020"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。東京都などというお話があったというと、もう少し高かったりするのかと。でも、そのぐらいなのか。分かりました。工事の立ち上がりに、やはり結構な費用がかかるところの部分は、少し、区でもという、早めにというところでは理解しましたので、分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"５０億円を超える公共事業で１割。なるべく前払いをしてあげることによって、もっとスムーズにいくのだろうと思うし、企業はそんなに、事業者の皆さんも頼るものは頼っていると思うし、資材高騰などもあるし、人件費もかなりかかっているということを考えると、この限度額というのは、もっとあってもいい現状ではなかろうかと思うのですが、今回、１割と決めた理由というのは何かありますでしょうか。","respondent":"佐藤経理課長","answer":"１割というところは東京都を参考に設定したというところであります。個人事業者との意見交換というところもしておりましたけれども、１割というところは出しませんけれども、ただ、お話しする中では、これで一定程度のところは大丈夫かとは考えております。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"現場が、働いている方々も含めて、こうであったらという要望があると思うのです。でも、今、大丈夫だという話を聞いたということなので、これに決めたということは私も分かりましたけれども、今後、ある程度、融通を利かせるという部分もあっていいのかと思うので、ぜひ、いろいろな方と、工事事業者の方と話を進めて、変えられるところは変えていただきたいと思いますので、要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"昨年は視察先で夕食はばらばらだったのですが、今回は、またばらばらですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"私は毎回聞かせていただきます。「秀」の件です。契約案件がどうなっているかだけ、さらっとでいいので教えてください。細かくなくていいです。","respondent":"勝亦総務課長","answer":"今、国際友好協会で貸主の方と協議を詰めている状況でございまして、今後、契約をするという、今、契約の協議をしているという状況です。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"今、契約をする段取りをつけている段階だということなのですが、その内容については、この委員会で報告していただくことは可能でしょうか。どういうふうに決まって、どういうスケジュールでやっていこうとしているのか。遺贈をどういう話合いの中で、どういう方向でやっているのかということも、この委員会に報告していただきますようお願いさせていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/131056?Template=document&Id=6797#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":19628,"voices":69}},{"id":"r06-20240827-14","meetingId":"r06-cm08","date":"2024年8月27日","dateIso":"2024-08-27","committee":"行財政改革特別委員会","time":"午前１１時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ確認します。ここの１の最後のところです。質疑とその回答については区のホームページに掲載予定とありますが、いつぐらいの時期なのか、またこれは全て掲載をいただけるのかというところだけ確認をさせていただきたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"質疑とその回答についてのホームページの掲載ですが、今、東京都と調整を図っているところですので、近々のうちに報告できるような形で掲載する予定です。","id":"exchange-001"},{"speaker":"新妻委員","kind":"質問","question":"主な質疑、この４点ということなのですが、ここに集約されているということでの４点なのでしょうか。もうちょっと質疑があったのであれば、そこも載せていただけるといいかなとは思うんですけれども、いかがでしょうか。","respondent":"小林新庁舎建設担当課長","answer":"主な質疑というふうに書かせていただきましたのは、質問としての内容はしっかりとこの４つの中で集約されているですので、それを分かりやすく、見た方にも理解しやすいようにまとめさせていただいたところで、この４点ということで考えているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、今後の予定のところで都市計画案の説明会が９月１９日に行われるということですけれども、この周知についてなんですが、区ホームページ、広報しながわ、ＳＮＳ等で実施するということですけれども、この周辺の住民へのポスティングというのをぜひやっていただきたいんですが、予定しているのかどうかも含めて伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"ポスティングにつきましても、東京都からは、建物から２ヘクタールの範囲でのポスティングについて、検討を進めていると聞いてありますので、引き続きそういった検討を進めていただいて。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"都で検討されているということですので、ぜひ、それを実施していただきたいと思いますし、区のほうからも求めていただければと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/869098?Template=document&Id=6799#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":3449,"voices":23}},{"id":"r06-20240828-19","meetingId":"r06-cm08","date":"2024年8月28日","dateIso":"2024-08-28","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時３８分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったところで、訓練の在り方を区としてはどのように考えられているのかなと思うのですけれども、防災訓練というと、先ほどもちょっとご説明の中にありましたが、やはり参加者が同じような顔になっているとか、訓練の中身も含めてどういうふうに作られているのかなというところでは、地域にもこうした防災区民組織があるとはいえ、やっぱり区がイニシアチブを取って。","respondent":"伊藤災害対策担当課長","answer":"そういった訓練の中に組み込むことを想定しながら訓練の立てつけを作ってまいりまして、訓練を実施し、地域との関係を深めつつ訓練を実施してまいりたいと考えています。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういったところでは、区全体として、こうした総合防災訓練大綱をもうちょっと中身を広げていく、そういった必要性があるのではないかなと思いますし、年ごとに訓練を実施する上での重点的なテーマを明確にして、毎年定期的な訓練の実施に努めるということが書かれているのですけれども、何のためにやられている訓練で、自分たちがそこから何を得るのかというのが分かるような訓練にしていかないと。","respondent":"伊藤災害対策担当課長","answer":"そういったことはしっかりと訓練の場、また様々な場面を通じて地域の皆様、また訓練を通じて、認識をさせていただけるような機会を設けてまいりたいと考えています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その上では、各地区で工夫をしていく、その工夫をしていくためにも区が支援をしていただきたいなということを言いたいわけです。それで、この防災フェアのアンケートのところは、３０代、４０代が６０％の声を寄せていただいたということで、これは大変大事なことだなと思うのですけれども、これはどれぐらいの方のアンケート、人数の声が返ってきたのか伺いたい。","respondent":"伊藤災害対策担当課長","answer":"ただ、いろいろな取組があろうかと思いますけれども、今回の訓練につきましては積極的に私たちも手話通訳者を配置したりだとか、キーボードを持って文字で会話ができるような形で準備しまして、万全とは行かないまでも対応できるような態勢を取りまして。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、そうした訓練も、ぜひ障害者を入れた形でやってもらいたいという要望も多数寄せられているので、今回障害者とミーティングされて、声がかかっているというところでは、ちょっとずつ進んでいるのかなと思うのですけれども、防災のところで要配慮者の訓練だったり避難等を聞くと、福祉のほうで、所管のほうでと言われたり、それで所管のほうに聞くと。","respondent":"伊藤災害対策担当課長","answer":"もちろん通常の訓練の安全管理を行いますけれども、要配慮者の方、障害者の方が来たときにもしっかりと配慮いたしますので、事故のないように訓練を進めてまいりたいと考えております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"障害を持たれた方や高齢で要配慮という方々が、どこに相談していいのか、何というか、たらい回しにならないように、防災訓練や避難についてはここというふうに明確になるといいなという思いから質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"まつざわ委員","kind":"確認","question":"何度か、質問と確認をさせてください。確認で、令和６年度地区防災訓練が１０地区で開催されます。それで先ほど米印のほうは、訓練をしないと。例年だと、訓練をしない町会は時期をずらして何かやるとかというお話も聞いたことがあるので、この訓練をしない理由と、この地区はどうするのかなという確認が１点と、青いマークのところ、荏原第５、うちの地区もそうですけれども、新しい訓練と書いてあります。","respondent":"伊藤災害対策担当課長","answer":"一方で、町会単位で訓練をやっているから、ここでは行わないというような意見もありますが、今回新しい訓練を行うに当たりまして、各町会長、連合町会長等とお話をさせていただいたときに、できればやりたいのだよねというようなお話を伺ったことがありますので。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"確認","question":"だから、この地区防災協議会というのも結局機能していかないのではないかなと私は考えていて、結局この２つの機能していないことが、例えば品川区の行政の中でしっかりとある程度認識があって確認できるのであれば、そこは、私は町会だけではできないので、ここにどう、要は行政としてやるべきではないというのは分かっているのですけれども、やっぱり弱いところを、何というのですか、助けていかないと。","respondent":"平原防災課長","answer":"ただ一方で、活動する中での限界というようなところも私どもはお声として聞いてありますので、区として何ができるかといったところについては、できるもの、できないものはやっぱりあるかなと思うのですけれども、例えばご助言であるとか資機材等々の貸出しとか。","id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"最後に、ペット同行避難、また先ほど石田ちひろ委員からもありましたが、要配慮者支援のマニュアル化というのは大変評価していて、ようやくこうやって標準マニュアル化が進んだのかなというのは大変うれしく思っているのですが、この要配慮者支援というのは本当に難しくて、例えば私も町会で避難所運営のほうに携わっていて、いろいろ声かけをするのですけれども、実際、自分の町会に障害の方が。","respondent":"平原防災課長","answer":"今年度はちょっと一旦別なものを考えてありますので行ってございませんけれども、地域の方々に要配慮者支援を考えていただくワークショップを実施しておりました。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。今のまつざわ委員からの質問で、総合防災訓練のことで、またちょっとすみません、お尋ねをします。今年は開催地区が１０地区あって、３地区が未実施ですというご説明がありました。防災訓練については、この先、来年以降、第４地区に関しての総合訓練に関しては、どのように取り組んでいくのかを聞かせていただきたいと思います。","respondent":"伊藤災害対策担当課長","answer":"できれば、近隣の小学校でできればと思うのですけれども、そこは地域と学校とのつながりもあろうかと思いますので、こちらのほうでも今の状況を把握しつつ、地区担当また町会の方々とご相談をさせていただきながら、今後の方針について決めていければと考えています。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、来年以降について、まだ地域の方と検討はされていないという考え方でいいのですか。","respondent":"伊藤災害対策担当課長","answer":"申し訳ありません、今ちょっと私のほうで把握していなかったので、そこは確認させていただければと存じます。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"確認","question":"それとあともう一点なのですけれども、防災に関することの一番下の職員向けの訓練なのですけれども、これは各部訓練と待機寮生訓練が通年あるということなのですけれども、この災害対策待機寮生の実施要項を見ますと、優先の入居者は、優先入居の資格があって、日本赤十字社救急法救急員である者、それとあともう一つ、災害対策上必要な技術関係者と記載をされているのですけれども、防災課は。","respondent":"伊藤災害対策担当課長","answer":"待機寮生のご質問かと存じます。待機寮生につきましては、入居後、まず応急手当講習というものを受講し、その後、上級救命講習というものを受講しますので、一定の救命応急手当については能力がある職員だと認識しています。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、今把握していないということなので、例えば各防災訓練の避難運営を行うときに、そういう方たちが、各地域の防災組織、地域ごとの職員が出向くわけですけれども、特殊な技能を持っている方というのは、やっぱり特殊技能はあるのだけれども、区としては、そういう特殊な技術を持っている、例えばいらっしゃったとしたら、それは何か優先順位として。","respondent":"伊藤災害対策担当課長","answer":"現時点ではそういった認識はございませんが、さっきも申し上げましたとおり、待機寮生につきましては、応急救護研修であるとか、一定の応急手当の資格を持っている人間が配属されてあります。","id":"exchange-012"},{"speaker":"えのした委員","kind":"質問","question":"今、まつざわ委員、高橋伸明委員からもご質問がありましたが、３－１の地区総合防災訓練は新しい取組ということで、私も興味があって、とても期待しているところなのですけれども、この開催地区、まず５地区、色つきのところがありますけれども、私も地元が荏原第１なので楽しみにしていたので、どういう経緯でこの５地区に決まったのか。","respondent":"伊藤災害対策担当課長","answer":"５地区から今後の地区の増加ですが、担当レベルとしましては、全て１３地区で実施をする、やっていない３地区を含めましても、やっていきたいと考えています。","id":"exchange-013"},{"speaker":"えのした委員","kind":"質問","question":"新しいことですから、場所、学校ですとか室内、野外、活用の検証は大事だと思いますし、私は防災訓練で行動を伴う訓練というのが、やはり身について覚えるということを学びましたので、ぜひ防災ダンス、これからご検討ということなので、品川区のオリジナルで、他区にも誇れるような内容になることを期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今の質問に関連して確認をさせていただきたいと思います。","respondent":"伊藤災害対策担当課長","answer":"この訓練評価につきましては、アンケートをこの５地区については取る予定ですが、その他の地区についても同様にアンケートをやる方向で考えてあります。","id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"新しく参入される方が増えるということとともに、先ほどからお話があります障害がある方々もこういう訓練に参加しやすいというような雰囲気づくり、子どもだったり、ご家族家庭、プラス障害の方に対するこういう新しいプログラムというところも研究していただきたいなと思いますが、いかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"防災パズルとなっていますけれども、防災関係のゲームですが、こちらも動きを中心ではなくて、座ったままというか、あまり動きのないゲーム的な訓練を入れることによって、様々な方が訓練に参加できるように工夫している次第です。","id":"exchange-016"},{"speaker":"吉田委員","kind":"提案","question":"図上訓練ですから、少々そのときに間違った答えを出したとしても、本当はここがよかったね、みたいに後で検証すればいいし、それを本当に災害が起きた現場で子どもたちにやらせるのは無理だと思いますけれども、責任もあることですし、でもそういう訓練というのを例えば提案されるというようなことはできなかったのかな、これはごめんなさい、私の好みで、そのゲームがすごく面白そうだなと。","respondent":"伊藤災害対策担当課長","answer":"訓練内容の、この訓練でよかったのかというようなところなのですが、今回いろいろな訓練の提案は実際に事業所から受けてございまして、可能なところということで選ばせていただいた次第ですが、まだ、先ほども委員のほうにご回答した内容ですが、アンケートもありますので。","id":"exchange-017"},{"speaker":"吉田委員","kind":"確認","question":"何かもう少し気軽にいろいろなサークルとか、そういうところでできたらいいなというご意見があるのですけれども、今のところ区の方向性としては、町会とかでこういうゲームをやりたいという企画があれば派遣してくださるという理解でよかったでしょうか。しながわ防災体験館のところで開かれる講座に参加してくださいというルールだと思ったのですけれども、それでいいか確認させてください。","respondent":"伊藤災害対策担当課長","answer":"ただ一方で、事前のスケジュール調整等があると思いますので、ちょっとその辺は個別にご連絡をいただければと考えています。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"そのかまどベンチもやっぱり町会単位ではないと使えないのでしょうか。ちなみに杉並区では、まさか個人では使えませんけれども、区民の活動として、そういうサークルを立ち上げて使いたいと、きちんと手続は必要だと思うのですけれども、そういうことをすれば使わせてくれたという情報があるのですけれども、だから品川区も頼んでみたらと言われたのですけれども、品川区の現状のルールを教えてください。","respondent":"溝口防災まちづくり部長","answer":"今までは町会単位で様々活動していることに対して、公園を利用していただくという形でのことはありましたので、また、いろいろ個別に地域の中で立ち上がっているという話を聞いてありますので、そこは防災課のほうとも連携しながら、事情を聞いて。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。部長には度々わがままを言わせていただいておりますが、別に私の気持ちとしては、勝手に使うという意味ではなくて、いろいろな人が防災訓練に参加しやすいようにということが、ここでもこういうふうに話し合われているわけですから、それは参加しやすいように進めていただきたいなと思います。それで最後に、先ほどのしながわ防災訓練ガイドというのは、令和２年ですよね。","respondent":"伊藤災害対策担当課長","answer":"しながわ防災訓練ガイドにつきましては、更新を計画しています。ただ一方で、全区民に配れるかどうかというのはまだ分かりませんが、皆さんの目に触れられるような形で準備できればと考えています。お待ちください。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"確認","question":"事前に教育研修を推進して、それを訓練によってまた確認検証するとか、そういう中身が出てくるわけなのですけれども、私は訓練の必要性、目的だったりとか、そういうところに、そういう視点というのが盛り込まれることが必要なのではないかなと思うのですけれども、その点をまず伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"その中で命を守ることというのは非常に大事なキーワードだと思いますけれども、ちょっとここでは書いていないですけれども、命を守ることに関しては、例えば公助である消防、警察等も被災してしまうので、自らが訓練を通じ動けるようにして、自助。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"提案","question":"そのために何をするかということが求められるわけで、訓練にそういう意味づけをするべきなのではないかということで、だから訓練というのは、では自助の意識の向上というのは何なのですかということを、ちょっと伺いたいなと思うのですけれども、「自分の命は自分で守るのですよ、守るのですよ、守るのですよ」と言うだけだと、守ることにはならないと思うのですよ。どうやったら守ることができるのか。","respondent":"平原防災課長、伊藤災害対策担当課長","answer":"あるいは訓練をやった結果、昨年度行いました私どもの地域防災計画の大規模修正のときにも、項目で挙げさせていただきましたけれども、訓練によって得られた成果あるいは課題、そういったものを次の計画に活かしていく。次回の訓練であるとか反省点を挙げつつ、よりよい訓練、また災害に対する準備を進めている状況です。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことで、どういう人がこの福祉避難所には避難してくるよということがあらかじめ分かるような状況になったときに、その人が直接その福祉避難所に避難をして、そこの福祉避難所の管理者だったり、職員も含めて、またそういう場合は、その地域の、何というのですか、福祉関係の職員とかなんかも関係してくるようになるのかなと思うのですけれども、そういうところも含めた形での具体的な要配慮者の。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"福祉避難所の実際というのは本当に様々な課題があって、それをクリアしていくというのは、本当に様々、何というのですか、工夫だったりとか、越えなければならないいろいろな課題があると思うのですけれども、障害者団体の方々からもすごく不安で、実際に訓練をして、その訓練を通してさらに何が足りないのかを浮き彫りにしていきたいというご要望もいただいていますので。","respondent":"平原防災課長","answer":"例えば家具の転倒防止、感震ブレーカー、委員にぜひ今度見ていただければと思いますが、行っております。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"高齢化のせいもあるのですが。本来、南海トラフは全然関係ないよという方が多いのかなと思ったのですけれども、あれだけスーパーに行って、お米が本当に棚から消えたというのはすごくショッキングで、また国民のことを考えると、防災意識が高まっているのかなと思うのですが、その辺ちょっと区の見解を、どう思われるか教えてください。","respondent":"平原防災課長","answer":"ですので、今は関心が高まっていると考えられるのですけれども、区といたしましては、関心が高まったものを実際の行動につながるように、しっかりとそこはつながるような行動に取り組んでまいりたいと考えています。","id":"exchange-025"},{"speaker":"須貝委員","kind":"意見","question":"そういうところに、ちょっとコマを入れさせていただいたらどうか。だから、まず各事業部の、単体の事業部での訓練ではなくて、ほかの事業部でやるそういうイベントに、枠にちょっと入れさせていただいて体験してもらう、また見てもらうということも私は実際、実地でやる、経験するということは大事だと思うのですが、それがいいのかどうか、ちょっと見解だけお聞かせください。お願いいたします。","respondent":"伊藤災害対策担当課長、平原防災課長","answer":"参加者の増加を見込んだポスティングというような内容のご質問でございました。確かに今地震に対する備え・意識が高まっている中でありますが、防災訓練の参加が若干減っているような状況もあります。わっくわくランドしながわのように、子ども対策でやっているところにも防災課は出しています。今後も幅広くそういった機会に連携しながら進めてまいりたいと考えています。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後ですが、先ほど、ＰＴＡをはじめ、学校、それから保育園、幼稚園等に個別に配布するということですが、お子さんの場合には、何かつられてこないと駄目なのですよね。それだけ区民の皆さんのことを考えて、様々なことをこうやって施策として進めているのですから、ぜひ多くの方が来られるように、今後も努力していただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問・要望","question":"しながわ防災訓練ガイドの中の防災区民組織の活動なんかで言うと、網羅的に様々入っておりますけれども、そのような中で、現状の品川区としてできること、やってもらいたいことというところでは、どういうことを１つの目標なり政策的な視点として持っているのかを最初に伺いたいと思います。","respondent":"平原防災課長","answer":"１月１日の能登半島地震でも、顔の見える関係というものがかなり大きな意味づけを持ったと聞いてありますので、今後ともその地域の中核である防災区民組織には、災害時の大きな力として私どもは期待しておりますので、そういったところの視点で活動が支援できるよう。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問・要望","question":"当時を私はちょっと知りませんけど。やっているところもあると思うのですけど。そういった意味でハードルがあるので、そういったハードルを少し下げていくということも、地域の中でより現実に即した訓練をするという中では、大事な視点かなと思うのですけれども、その点に関して支援ができるのであればしていただきたいと思うのですけれども、いかがでしょう。","respondent":"伊藤災害対策担当課長","answer":"一方で、消火訓練、ポンプですとかスタンドパイプを使う訓練におきましては、おおむね１か月ぐらい前から消防署への届出だとか、道路を使うようであれば警察だとか、いろいろそういった手続が発生してしまいます。","id":"exchange-029"},{"speaker":"塚本委員","kind":"意見","question":"なかなか一足飛びに、そういったハードルを取り払うということは難しいのでしょうけれども、そういった訓練、より具体的な初期消火訓練ということが地域で行えるように、ぜひ支援をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"改善をしていて、専用のウェブページを開設するということですが、このウェブページ、別建てのいわゆる品川区のホームページからそこへ飛んで、具体的に訓練の内容だとか、そうしたものをお知らせするというものなのでしょうか、もう少し具体的に、このウェブページを開設して周知を図るというのはどういうふうにするのか教えていただきたいと思います。","respondent":"伊藤災害対策担当課長","answer":"一旦そこのページに飛びますと、今年度実施する訓練の、各町会の、町会と申しますか、訓練のそれぞれの地区のページに飛びまして、どういった訓練をやるのかと、日程だとか場所だとかが分かるようになっているような内容です。","id":"exchange-031"},{"speaker":"こんの委員","kind":"質問","question":"いわゆる専用のウェブページですから、これは今回新たな訓練を委託されている事業者などがこういうのを作るのですか。区のホームページにちょっと画像を加えたぐらいのだと、なかなか行ってみよう、必要だなと思えるかどうかというのが大事かなと、このウェブ周知、せっかくそういったところにお金をかけてやるのですから、その辺をもう少し教えていただけますでしょうか。","respondent":"伊藤災害対策担当課長","answer":"今まだやり取りをしていますので、若干の修正は利くと思いますが、あまりご期待されているほどのレベルではないようなイメージは持っているのですが、近づけるように頑張ってまいります。","id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問で、一斉防災訓練の中で、２番の訓練内容、今回マニュアルの見直しをするということで、本訓練においてマニュアルの検証を行うということですが、私のまず理解が正しいかどうか。９月以降に、要するに見直すということは、ほとんどの会場は１０月、１１月にされるということですが、マニュアルが改定した後に、新しいもので訓練を行うという理解でよろしいのでしょうか。その辺を伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"一方で、この区内一斉防災訓練につきましては、地域防災訓練とはちょっと異なりまして、区内一斉防災訓練については、本年ですと１２月８日に行う予定をしていますので、そちらで検証を行う予定をしています。","id":"exchange-033"},{"speaker":"こんの委員","kind":"質問","question":"そうですね、１２月でしたね。失礼いたしました。分かりました。そういったものを聞いていたり、見たりしている人もいるかもしれないですが、改めてそこで説明したりとか、また体験の一部ができるとかというふうにしないと、避難所訓練の意味というのがもっと具体化していかないといけないのかなと思うのですが、その辺はいかがお考えでしょうか。","respondent":"伊藤災害対策担当課長","answer":"ですので、各避難所によってカラーといいますか、やり方がちょっと異なっている状況ですので、そういった段階的にお見せするというところはもしかしたらできないところもあるのかもしれませんが、そういったご要望があるということは周知をさせていただいて。","id":"exchange-034"},{"speaker":"こんの委員","kind":"質問・要望","question":"もっと混乱するし、もっとどうなるかというのを運営側がイメージを持って運営しなければいけないとなると、やっぱりそのフェーズを全てセットで、年に１回やるこの訓練の中で全てをやることはできないけれども、今回はフェーズ１から２までとか、３から４までとか、そこら辺のところも、運営側の方たちが要望したらやりますではなく。","respondent":"伊藤災害対策担当課長","answer":"一方で、先ほど申し上げましたとおり、やはり運営側、やるほうの対応というのもちょっとありますので、そちらのほうも踏まえまして、今地震が多くなってきているということもありますので、訓練の方法については、改めて情報提供させていただいて。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"最後のページの物的被害のほうで、道路の冠水がありますけれども、深さは何cmぐらいになったのか教えてください。そして、東品川海上公園エレベーターの故障とありますが、これはどのような故障だったのか、それだけ、もし分かれば教えてください。","respondent":"平原防災課長","answer":"エレベーターの故障ですが、エレベーターの構造上、水につかるような部分が出てきたときに運転が休止するということもございまして、今回いわゆるモーターが着水したということではなく、かごの部分が着水してしまいまして動かなくなったといったところで。","id":"exchange-036"},{"speaker":"まつざわ委員","kind":"意見","question":"あれは多分品川区でも起こり得るのかなというのが私の感覚で、マンホールの、要はどうしても、絶対全部が全部対応するというのは不可能で、やっぱり水があふれたときに、今のマンホールというのはどんな感じになっているのかだけ聞かせてください。","respondent":"溝口防災まちづくり部長","answer":"ただ、とはいえ、一方でマンホールが吹いたりとか、下水があふれて舗装を持ち上げたりとかというのが起きているのは事実ですので、引き続き対策は必要だと感じているところですので、当然私どもだけでできるものではありませんので、道路の改修に合わせたりとか。","id":"exchange-037"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"私も、最後の８月２１日の大雨についてなのですけれども、港区で１時間に１００mmの短時間での記録的な大雨ということで、気象庁の気象台の発表では、品川区全域で６０mm、一部では、品川地区とか大崎地区では９０mmを超える雨量があったと伺っています。","respondent":"平原防災課長","answer":"そこは考えるところでございまして、しっかりとした分析というのは今後また行っていくことが必要かなと思ってあります。","id":"exchange-038"},{"speaker":"ゆきた副委員長","kind":"質問","question":"なかなか認識をしていくというのは難しいところなのかもしれないと思うのですけれども、被害について全てを把握していくのは難しいと思うのですけれども、私が把握しているところで、東京都所管で緑道公園の今回の倒木と、八潮の東京都の緑道公園の倒木と、都営団地のエレベーターの停止というのもありました。この辺について、ぜひ何かあれば、お聞きできればと思います。","respondent":"平原防災課長","answer":"例えば、区民から、この道路が冠水していますよとか、ここに倒木がありますよと言って、その道路が都道あるいは国道だった場合、私どもは、そこは品川区の管理ではありませんと、そういうような対応は行いません。","id":"exchange-039"},{"speaker":"ゆきた副委員長","kind":"質問","question":"ぜひ、国、都、あと区で連携をしっかりして、今後とも引き続きお願いできればと思います。今回１９時２０分には、土砂災害警戒情報が出されて、警戒レベル４まで達して発表されていると思われます。こういった雨量を把握しての雨量ごとの対策、区民への警報の周知が必要になってくると思いますが、ここについての認識があれば、どういう認識を持っているか、お聞きできればと思います。","respondent":"平原防災課長","answer":"今後とも、それぞれ発表される気象状況の特性というものがありますので、そういったものを踏まえた形でしっかりと対応していければと考えているところです。","id":"exchange-040"},{"speaker":"ゆきた副委員長","kind":"意見","question":"何度もすみません。参考までなのですけれども、新宿区では、区として区内６か所に定点観測地を設けて、雨量ごとに対策を取られているので、ぜひ品川区においても、この定点観測地、こういったところで前向きに進めていただければと思います。最後に何かあれば、よろしくお願いします。","respondent":"平原防災課長","answer":"品川区におきましても、それぞれの区で、区の地理的な特性でありますとか、様々な状況に応じて対策を進めていると思いますが、品川区の場合３か所に降雨量を測るものを設置しています。荏原と品川区役所と、それからもう一つは西五反田、この３か所でやっております。","id":"exchange-041"},{"speaker":"こんの委員","kind":"質問","question":"参考までに伺いたいのですが、水害のほうで区内巡回をそれぞれしてくださっているといったところなのですけれども、この区内巡回は、いわゆる何台の車で、品川区内全部を一斉に見ることはできないと思うのですが、それでも１台で全部を回るというのはなかなか情報が早めに察知できるというものでもないかなと思うと、何台ぐらいで全域を、いわゆる１回やったら終わりなのか。","respondent":"溝口防災まちづくり部長","answer":"一番最低な基準としては、見ていくポイントにもよると思いますけれども、目黒川、立会川という２つの河川を品川区は抱えておりますので、そこはしっかり見られるようということで２班体制で、車の台数でいくと２台で回る。","id":"exchange-042"},{"speaker":"こんの委員","kind":"質問・要望","question":"川、いわゆる河川が一番気になるところですから見ていただくといったところで、あと、今言ってくださった南大井で被害が出た、過去にあったところだとか、その辺をもう少しお聞きしたいなと思ったところですが、今お答えをいただいたので、いわゆる冠水しやすいところ、その冠水の原因というのは、１つは雨水ますが掃除されていないとか。","respondent":"溝口防災まちづくり部長","answer":"ただ一方で、やっぱり危険な箇所というのを少しでも早く見つけて、未然に防ぐというのも大事な視点だと考えていますので、両方両立しながら、また区民の安心安全につながるような巡回パトロール、そういったものはしっかり行っていきたいと考えているところです。","id":"exchange-043"},{"speaker":"こんの委員","kind":"意見","question":"今どの辺までの雨量が来ているのかということによって、冠水の危険度の高いところの、よりポイントを置いて効率的に巡回ができるなと思うと、この雨量の視点というのは非常に大事かなと思いますので、定点観測が３か所今あるということですけれども、場合によってはそうしたものを効率的に把握していくためにはというのも１つ大事な視点かなと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"高橋（伸）委員","kind":"質問","question":"たまたま５０mm以上の雨が降ったときに、潮位があって、東京湾がたまたまそのときが上げ潮、満潮の場合だと、定点カメラも必要なのですけれども、当然目視もあるではないですか。事前に満潮で上げ潮がいっぱいだというのは、職員の方も分かるわけではないですか。そういうときの対応は違ってくるわけですよね。それだけ教えてください。","respondent":"溝口防災まちづくり部長","answer":"ただ、実際にあふれているときに職員に行けというのはなかなか言いにくいところもありますので、本当に現地でなければ分からない、水位についても水位計を持っておりますので、河川の水位がどうなっているかというのは把握しながらやっているところですが。","id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問","question":"８月１５日の台風７号の対応のところで、福祉避難所開設１か所、上大崎特別養護老人ホームで福祉避難所が開設されたということなのですけれども、福祉避難所が開設されたことというのは今まであったのでしょうか。どういうときに福祉避難所が開設されるのか、開いた理由を伺いたいと思います。どんな態勢が取られたのか、その点についても伺います。","respondent":"平原防災課長","answer":"それが１点でございまして、もう一点、態勢ですけれども、地震のときと違いまして、今回土砂災害ということもあって区域が特定されると、その区域内にいらっしゃる方の人数も特定できておりまして、連絡も全てついているということで。","id":"exchange-046"},{"speaker":"せお委員","kind":"質問・要望","question":"ちょっと報告なので聞いていいのかよく分からないのですけれども、明日以降来ると言われている台風１０号に向けては、大型と言われているので、何か８月２１日までの対応とは違ったところとかがあれば教えていただきたいと思っています。","respondent":"平原防災課長","answer":"台風１０号につきましては、皆様報道でご承知のとおり、全く動きが読みづらい台風ですので、現時点では何かこのような態勢を取るといったところは区としては定まったところではございませんけれども、先ほど申しましたとおり、日々ウオッチをさせていただいておりまして。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"風水害対応についてのＩの３番の(3)に「コールセンターによる区民等からの問合せ対応」とあります。問合せはあったのか、なかったのか。あったとしたらどのような問合せで、どういう対応をされたのか伺いたいと思います。","respondent":"平原防災課長","answer":"そういったところを受けて、実際の所管している部、例えば道路の話とかでございましたら、災害対策本部の土木部という編成があります。そういったところにつないで、具体的な対応をしていただくという態勢を取っております。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"それと、他区、神奈川の人だったかな、たまたまいらしたのだと思うのですけれども、これが２２日でしょう、何日だったかな、目黒川の第一三共の研究所の近くの何橋だったかな、あそこら辺で気泡がぽこぽこしているというのがあって、多分、他自治体の方だったのでコールセンターを把握できなくて、うちのほうに来たのですけれども、そういうような報告はほかからはなかったでしょうか。","respondent":"溝口防災まちづくり部長","answer":"今回２１日の大雨の際に、それが起因というか、そのときに初めて目黒川のほうから気泡が湧いたとかという話は私どもに入っていないのですけれども、実際いろいろな要因があって、要は、いろいろな化学反応等が起きて。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、後で教えていただけたら、それなりに何かお返事ができるかなと思います。これはいつもの私の質問になってしまって申し訳ないのですが、防災というのとは別に、この川があふれたらすごく嫌だなと私はいつも思っていて、あふれないようにすることが前提ですけれども、やっぱり合流改善というのも、今後も防災とともに努めていただきたいと思います。これは、要望でとどめております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/302312?Template=document&Id=6801#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":52105,"voices":119}},{"id":"r06-20240829-10","meetingId":"r06-cm08","date":"2024年8月29日","dateIso":"2024-08-29","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"令和７年度予算（議会費）","agenda":"令和７年度予算（議会費）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"討論の作成に具体的な支障が出ている現状があるわけですから、ぜひスピード感を持って改善、対応してほしいという思いがありまして、お伺いしたいのは、ここについては改善の必要性を感じていないということなのでしょうか、お伺いしたいと思います。もし、しかるべき会議体で検討すべきことだというお考えなのであれば、どういった会議体でこれが検討されることになるのか、伺いたいと思います。","respondent":"大澤区議会事務局長","answer":"行政視察の報告書については、皆様の中でホームページにアップということに決まれば、それに沿って事務局では手配をするという立場です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"局長のお考えはよく分かったのですが、今ご発言の中にもありましたけれども、私たちは、お金をかけてでも必要な改善なのではないかというふうに提案しているのですけれども、取りまとめいただいた議長とか、あるいは委員長とかのお考えなども、もしあればお聞かせいただきたいと思います。","respondent":"渡辺議長","answer":"ご指摘の共産党要望の１番、文字起こし、まず、基本的には局長の説明のとおりです。そして、予算のかけ方は、他のもの、他会派のご要望等も総合的に勘案するしかないので、今回はそこではなく、先ほどもご説明のあった主に３点を、重要視したということになります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"言い続けたいと思います。私たちはやはり必要な改善だと考えていますので、ぜひ、局長の説明もありましたが、必要な予算もつけていただいて、早期に改善していただくよう、議会全体の皆さんにも要望としてお伝えしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"令和６年第３回定例会","agenda":"令和６年第３回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"関連して伺いたいのですが、７月９日の議運で２定の一般質問について伺ったときに、一般質問を行う予定だった中塚区議が質問を辞退した件について、ハラスメント行為で議員辞職勧告を受けて、なおかつ一般質問を理由もなく辞退するということであれば、いよいよ議員の資格が厳しく問われることになると表明させていただいた上で、まず、最低限、議長から中塚区議に対して。","respondent":"渡辺議長","answer":"そのような形なので、あえてこちらから問うような形は現在取っておりません。その他会議体等で必要ということであれば、こういう議運等の場で、総意であればまた対応するとは思いますが、現在、私の考え方では、今述べたように、あえて聴取のような形は避けたいと考えています。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"私たちの認識としては先ほど述べたとおりなので、今、議長のお考えは示されましたけれども、できればこの場で議論をしていただいた上で、私は聴取していただく。聴取という言葉の定義が難しいのですが、やはり私は議員の資格に関わる問題になってきていると思いますので、ここは、議運の場でも協議していただければと思うのですが、委員長、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、安藤委員からこういうご質問がありましたが、何か理由はあるのだと思うのですが、最低限議長に、こういうわけで今回辞退しましたということぐらいは、私は、議員としてやはりしっかり説明をするべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-03","title":"広報会議からの報告事項","agenda":"広報会議からの報告事項","exchanges":[{"speaker":"せお委員","kind":"意見","question":"広報会議のリーダーとして報告します。令和６年度予算で計上されました、区議会定例会開催の周知をするポスターの作成について、広報会議で議論しながら進めていって、このたび資料No.３にありますとおり作成されました。こちらに関しては、第３回定例会からポスターを掲示していきます。ＰＤＦのデータも皆様にお送りすることができますので、それぞれ議員の皆様、ご周知をお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"せお委員","kind":"意見","question":"掲示場所ですが、やはりおっしゃるとおり限られた予算もありまして、１回の定例会で１００枚ということで、そういった限られた中で、先ほどお伝えしましたＰＤＦのデータもそうですし、あとは、区のデジタルサイネージとかを検討できないかということで、今、区のほうには投げて、検討していただいている最中ということで、できる限り予算内で広げられるよう今検討中ですので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"安藤委員","kind":"意見","question":"大したことではないですが、チラシの中に小学生の感想が掲載されているというのはとてもいいと思ったので、すごい親しみが出るといいますか、なので、できれば、スペースの限りもあるでしょうが、今後も継続していただけるといいかなという感想です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"私から、議会の運営、在り方に関する意見があります。意見を述べさせていただきたいのですが、よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"こしば委員","kind":"質問・要望","question":"口頭ですとお伝えしづらいところもあると思いますので、メモベースの書面をお配りさせていただきたいと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"こしば委員","kind":"提案","question":"最初に、冒頭に修正ですが、議会改革に関する「意見」は、「提案」という意味合いです。３つ目が、発言の内容はあくまでも討論の内容に限るということを明文化していただきたいということで、討論についての制約の提案をさせていただきたいと思います。ただし、肩書のみは表記を認める方向で扱っていただきたいということを、自民党・無所属の会派からは提案させていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"提案","question":"この提案自体は、私たちの会派としては、到底受け入れられない内容だなという、まず第一印象なのですが、議論するということなので、しっかり議論していきたいとは思いますけれども、まず討論の本来の趣旨というのが何を指しているのかというのを、提案者の方から聞きたいのと、あと、委員会審査への冒涜、軽視ということでしたけれども、委員会の審査を踏まえて本会議で議決になるわけですから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"こしば委員","kind":"提案","question":"具体的に名前までは出しませんけれども、そういったことが一つの事例としてあったかと思います。逆に無駄を、無駄と言っては語弊があるかもしれませんが、そういった本来の討論の趣旨に即したことにつながると思いまして、このような時間制限というのを提案させていただきました。議員も含めて全ての安全を図る、守るという意味合いで、書かせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"提案","question":"こしば委員のご提案ですが、昨今、今まではなかったと思うのですが、ほかの議員とか会派とか政党に対する批判というのは、あまり出なかったのではないかなと記憶しているのです。それからあと、カスタマーハラスメントの件もありましたが、これはやはり職員の方に関しては、同様に十分に配慮すべき。それぞれ職務に対して、皆さん発言しているわけですから、少し違うのかなと思います。質問ではありません。","respondent":"大澤区議会事務局長","answer":"今、須貝委員からご質問のあった討論の件ですけれども、今、事務局で状況を把握しておりますので、ご報告いたします。令和５年第２回定例会から令和６年第２回定例会までの討論ですけれども、５分未満が４件、５分から１０分が３０件、１０分以上が４件でございました。","id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"今、５分未満が４件、５分から１０分が３０件あるということは、長く見ても５分から１０分の半分ということで、７分ぐらいが妥当なのかなというふうに、現在の平均値というふうにも思いますが、ただ、これはあくまで……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"ただ、先ほど申し上げましたが、やはり自己主張があるのに、再質問の時間だと少し短いのかなと思うので、やはりある程度自分の意見の主張はしたいと思うので、そこは品川区議会としても考えられたほうがいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"結局これは、私たちは内容としては、何ら承服できない提案ではありますが、どういう進め方で、これの扱いをどうするのか、それだけ聞かせていただきたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"次回以降に議題に上げて議論していくということですけれども、議会改革という点では、私たちもすごくたくさん提案をしてきたにもかかわらず、１回も議運で、委員会として協議されたことはないと感じているのですけれども、併せてそういったことも含めて協議していただくのがフェアなのではないかなと私は思うのですけれども、これは要望ですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/116834?Template=document&Id=6803#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":13655,"voices":62}},{"id":"r06-20240918-10","meetingId":"r06-cm09","date":"2024年9月18日","dateIso":"2024-09-18","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時５０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"撮影の問題もあるのですけれども、今、かなりの方が傍聴に見えていまして、委員長の判断で部屋を少し大きな部屋に移動してもらえないかと思うのですけれども、いかがでしょうかということで、現在、どれぐらい傍聴待機といいますか、何人の方が傍聴をしに見えているかというのが分かれば、事務局からも教えていただきたいのですが。","respondent":"大澤区議会事務局長","answer":"すみません、今、確認できていないので、お待ちになっている方の人数は把握してございません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"会議室も移動してくださいということも要望しておりましたが、ぜひ、少なくとも諮ってもらいたいと思うのですけれども、このままここで続けるのか、それとも、時間のロスといいましても、住民の皆さんの傍聴の権利を保障するということに当たって、時間のロスとてんびんにかけたら、どう考えても私たちが会場を移動するほうが、私は議員としてやるべきことなのではないかと思うのです。いかがでしょうか。","respondent":"まつざわ委員長","answer":"それにのっとりますと、傍聴人数というのは、例えばこれの人数の変更であったり、そういったことをしなければいけませんので、現在の委員会傍聴規則では人数は１０名とする、その中で今、運営を行っていますので、引き続き今回もその姿勢は崩さずにやっていきたいと考えています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"その姿勢を崩していただきたいのです。そして、それは委員長独断の判断なのでしょうか。ぜひ正副委員長とも話し合っていただきたいですし、この委員会の意思も諮ってもらいたいですし、そして最低限、何人傍聴待機されているのかというのを今すぐ教えていただかないと、私も同意できないです。それらについてお願いしたいと思います。","respondent":"まつざわ委員長","answer":"私からお答えしますと、委員長の権限というよりも、規則であり、ルールで決まっていることでありますので、その規則、ルールにのっとってやっていくというのがお答えです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"それと、局長のほうは、これは重大な問題なので、先ほど４３人という声が飛びましたけれども、教えてもらえないでしょうか。これは事務局として重要な仕事なので、実際に今回の議会運営委員会に対して、どれだけの方が傍聴を申請したのにかなわなかったか、待機しているのかというのは、少なくとも名簿上では分かるわけですから、聞いてくださいということでお願いしたいと思います。","respondent":"大澤区議会事務局長","answer":"午前１０時半の時点では、こちらにいる職員もみんな委員会室に上がってきていて、受付人数は分かりませんので、委員長から指示があれば、今、職員に聞きに行かせますけれども、特になければ、把握はできていないというのが現状です。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、別に長くやるつもりはないのですけれども、今、委員長への投げかけもありましたので、ぜひ委員長から指示を出していただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"撮影についてはもちろん許可していただきたいし、本会議同様、質疑の邪魔にならないように、前に来るとかというのは難しいですが、自席であればもちろんオーケーだと思います。いつでも撮影は許可して構わないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"令和６年第３回定例会","agenda":"令和６年第３回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"（２）の4)ですけれども、少し確認してもよろしいでしょうか。そういった提案をしたいのですけれども、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"私も一応、総務委員会に在籍しているのですが、どうしても審査をするときに、どちらかというとインボイスは、一人一人の事業主に関係することなので、私も総務委員会ではなくて、地域産業振興課、民生費〔同日後刻に「区民委員会」と発言訂正あり〕のほうで議論するべきではないかと思います。意見だけです。","respondent":"大澤区議会事務局長","answer":"これまでの経緯から、インボイス制度は国の制度で、区に所管がないので、所管がない場合は総務委員会で引き取るというのがこれまでの例ですので、一応、参考までにご説明を申し上げました。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、付託先を変えてほしい、皆さんいかがでしょうかというのと、少なくとも、須貝委員の言うように、次回からはもちろん変えてほしいし、今回からも少なくとも総務委員会に、地域産業振興課長ですとか、創業・スタートアップ支援担当課長など、直接の所管の担当理事者を参加させていただきたいと思うのですけれども、それについては皆さん、どうお考えですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどから議論を聞いていても、慣行を変えるというのにすごく慎重な状況が見受けられるのですけれども、それはそれで今の状態だからしようがないのかもしれませんが、最後に言ったように、総務委員会の運営の範囲で、今回はぜひ充実した議論ができるようにしていただきたいと、この場をお借りして、総務委員長であるこしば委員にもお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-03","title":"決算特別委員会","agenda":"決算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点だけ。原稿ですけれども、毎回言わせていただいているのですが、決算特別委員会最終日の総括質疑の日に意見表明をして、その日のうちに原稿を提出というのが、かなりタイトというか、かなり無理なところがありまして、いろいろ区議会だよりの編集との関係でということで、課題があるということは今までもご説明があったと思うのですが、ここは今回難しくても、ぜひ何とか改善していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-04","title":"決算特別委員会の運営","agenda":"決算特別委員会の運営","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"だから、ここでルールをこのように変えてしまうと、実態がないからいいでしょうとはならないと思うのです。議会運営委員会がそういう場であってはならないと思います。少なくとも皆さんにも聞きたいし、委員長にも、議長にも聞きたいのですけれども、全議員に諮る場というのは少なくともつくらないと、これは改定できないのではないですかと思うのですけれども、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"松永委員","kind":"提案","question":"（６）のところについてですが、今までも関連質疑はできており、また、質問のない委員以外の方は全体時間を考慮するという方針が考えられるということで、質問のない委員からのみ関連質疑が行われるということが、現在の状況であると考えております。再度関連質疑をすることは難しいと考えます。６番と１１番については、すみません、削除ではなく、全部提案に賛成ということで、以上になります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"すみません、再度お聞きして恐縮なのですが、従来、今まで我々が長年やってきたことに対して、特に大幅な変更とか、ここが変わってしまったということがあるのですか。教えてください。","respondent":"大澤区議会事務局長","answer":"実態として、変更点はございません。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一つ、決を取ってはいけませんと私は言ったつもりなのですが、須貝委員が質問したこととか、私が質問したことに対してもお答えがないので、何の質疑もないままで決められるわけがないではないですかということで、先ほど私が質問した、少なくとも全議員に関わる話ですから、全議員に諮る場をつくるべきではないですかということに対しては、皆さんどう思っているのか、議長、委員長、皆さん。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"こしば委員","kind":"提案","question":"共産党から提案のあった全議員への説明の場をつくるべきではないかというのは、まず、本来、議会運営委員会の趣旨というのは、議会の進行・運営を委員で議論して決定・判断するものでありますので、その趣旨に沿ったものであるべきと思いますので、先ほど安藤委員からいただいた案については、反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"現状の実態に影響のない文言整理という形で我々としては受け止めておりますので、この改正内容でよろしいのではないかということで、賛成ということです。全議員への説明ということですけれども、こういう実態に合わせて、本来と合っていないような趣旨の変更みたいなことは、これまでも議会運営委員会でやってきたところがあると思うので、議会運営委員会の決定でよろしいのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"山本委員","kind":"意見","question":"未来としても、まずこの修正に関して賛成いたします。理由や検討経緯は、先ほど松永委員が説明したとおりです。全議員で議論するかどうかについては、先ほどこしば委員、塚本委員から説明がありましたことと同じ考えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"須貝委員","kind":"提案","question":"したがって、賛成で、そして、全議員への提案ということですが、これは決算特別委員会、予算特別委員会にそれぞれ理事会がありますので、そこで文言整理、またはきちんと明文化して、より分かりやすい運営方法を提示しているわけですから、それに対して反対するものはありません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"すみません、意見だけ言わせていただきます。今回、品川区長から依頼があって、議員選出監事という推薦依頼があったわけですが、本来は、できれば一般区民が入っていって、そこで議論する、いろいろ検討しながら進めていくというのが、私は形としていいのではないかと思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"こしば委員","kind":"提案","question":"先般の８月２９日に私どもが提案をいたしました議会改革に関する提案の件で、私から提案の修正をさせていただきたいと思います。といいますのも、この間、私どもが提案をしてきたものが、インターネット、特にＳＮＳを中心に大きな誤解をされてしまい、それが今なお拡散されている状況にあります。それ以外に、「批判」という言葉がございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"提案","question":"持ち帰って協議するにしても、提案の中身が分からないとというところがあって、幾つかこの場でもお伺いしたいのですが、こしば委員がおっしゃった、２分を一定のルールに修正というのは、ペーパーがないと何とも言えないのですけれども、具体的にどこのところを一定のルールと修正していくのかというのを伺いたいのと、現状の課題として、前回も伺わせていただいたのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"こしば委員","kind":"提案","question":"私が言いました一定のルールというのは、前回２９日に提案をさせていただいた時間制限のところで、例えばのところに２分という表現も入っているかと思います。このルールというのは、これから丁寧な説明を含めて、また、ご意見をこれから伺わなければならないのではないかという話も会派でもありましたので、細かなルールの具体的な提示については、ここでするのは難しいものです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"こしば委員","kind":"意見","question":"本来の趣旨は今言いました、これから時間をかけて、これは先ほど私も修正理由の中で、各会派、また議員の方々に説明を行う。そこではこれらの意見も出てくると思います。そういった中での説明をしていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"提案","question":"提案されている内容をこちらも一定理解しないと、何を協議しているのかが分からないということで、聞いているのですが、自民党からの具体的な提案が、私たちは現行で何の問題も持っていないしという認識なのです。でも、提案されたのは自民党です。ということで、聞いているのです。一旦取り下げていただくほうがよろしいのではないかと私は思いますが、どうでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"西村委員","kind":"質問・要望","question":"今おっしゃっていただいたような意見も踏まえて、これからルールをどうしていくのかということを、各会派、今日ここに参加できない議員の方がいることも理解していますから、そういった皆さんに丁寧に説明を重ねていきたい、次の議会運営委員会に向けて皆さんと会話をさせていただきたい、説明をさせていただきたいと申し上げております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"提案","question":"そうすると、今ここで提案の説明はできないということですか。なのに、それを変えていかなくてはいけないというのであれば、なぜなのですかという説明をいただきたいと思っているのですけれども、今日、この場では説明できないということでいいですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"西村委員","kind":"質問・要望","question":"今回、私どもから出させていただいた前回の案から、修正案を出させていただきました。今おっしゃった誹謗中傷というところも、修正をさせていただいています。ですので、改めて文言の修正をさせていただいたところから、改めて皆さん、各個人、会派の方々にご説明に上がらせていただきたいと考えていますので、そのようにご理解いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須貝委員","kind":"提案","question":"前回、議会運営委員会でそういう話合いがあったので、我が品川改革連合でも、この提案に対して会派で話合いをさせていただきました。そこで様々な変化が、討論に対しても起きてきた。それに対して何とかいい形を取ろうということで、こういうご意見を出されたと思いますので、せっかくそういうご意見が出たのですから、慎重に皆さんの意見を聴いて進めるべきではないかというのが我々の会派の意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"西村委員","kind":"提案","question":"ですので、改めてそういった討論、再質問に関しても、皆さんと議論をさせていただける機会にできないのだろうかというご提案です。もちろん、討論をめぐるルールに関しては、皆さんの意見をお伺いしたいですし、聞かないということも、強引に進めるということも、もちろん決してしたくありませんので、皆さんに案の説明をする機会をつくらせていただきたいということを申し上げております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"山本委員","kind":"提案","question":"しかし、区民の皆様に宣伝することを目的として行うべきではないと考えております。一方で、自民党・無所属の会の皆様が当初ご提案されていた１と２の部分、時間や対象者に関することについては、議員の発言に対する権利の制限に通じることになると考えており、今後、修正案をいただくということですので、改めてそれに沿って協議をしてまいりたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"安藤委員","kind":"提案","question":"何をもって誹謗、何をもって禁止するのか、大変難しい問題だと思います。なので、進め方については、そういったことをしたらいかがでしょうかということを提案したいし、皆さんの意見はどうなのかと思います。どうでしょうか。もしよければ、公明党に、協議の状況など、もしあれば伺いたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"塚本委員","kind":"提案","question":"前回、自民党からのご提案もあって、会派での協議ということですけれども、今回、今の議会運営委員会の中で、改めて文言修正等があり、また、持ち帰って協議をしましょうという委員長のご発言もあったので、それに沿ってしっかり考えて、提案としては真摯に受け止めてまいりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"安藤委員","kind":"提案","question":"進め方については、私も意見を言わせていただきました。具体的に確認したいのですけれども、自民党が前回委員長の許可をいただいた上で、文書を提案されましたけれども、それに今回、口頭で修正があったのですが、その修正を提案する文書を改めてこちらに配付されるということで、それに基づいてということでいいのか、そこを確認させてもらいたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"こしば委員","kind":"意見","question":"先ほど口頭でお伝えしたのは、今後、他会派の議員への説明もあります。しっかり会派のほうでもさらに議論を深めていって、形にもして、今はまだ口頭ですので、形に起こして、お出しできればと思います。今の段階ではまだ、あくまでも口頭ベースで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"西村委員","kind":"質問","question":"持ち帰って協議をというお話がありました。質問に対してはお受けして、委員長がおっしゃったように協議は次回でということでいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問","question":"発言ということであるので、伺ってもいいかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"西村委員","kind":"質問・要望","question":"そういう意味で申し上げたのではないのですが、先ほどのどのような形でというのは、今、この場では申し上げられませんがとお伝えしたのですけれども、ここに参加ができない議員の方もいらっしゃるのは理解しておりますので、皆様にご説明をさせていただきたいとお伝えさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/116834?Template=document&Id=6813#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":23266,"voices":128}},{"id":"r06-20240920-4","meetingId":"r06-c-settlement","date":"2024年9月20日","dateIso":"2024-09-20","committee":"決算特別委員会","time":"午後 ２時５５分～午後 ３時０２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松永副委員長","kind":"意見","question":"ただいまご推挙いただきました副委員長を務めします、しながわ未来の松永です。委員長を支え、今回２回目となるタイムキーパーですので、ミスのないよう、しっかりと頑張ってまいります。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/589922?Template=document&Id=6847#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":2161,"voices":17}},{"id":"r06-20240924-6","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"区民委員会","time":"午後 １時００分～午後 ０時３０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","topics":[{"id":"topic-01","title":"第７５号議案、令和６年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第７５号議案、令和６年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"昨年の同事業の実績について伺いたいのですが、昨年度に組んだ予算総額と、大体どのぐらい使われたのかお伺いしたいと思います。主にどのような設備に使われることが多かったのかなども、分かる範囲でお願いしたいと思います。","respondent":"小林地域産業振興課長","answer":"実際の対象設備といいますか、機器としましては、先ほど申し上げたように商店街の部分で、冷凍・冷蔵庫の厨房機器、調理機械などが１９６件ですとか、あるいは工場とかサービスの提供スペースでの空調設備更新などで１５３件というように、こういったやはり電気代。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"大分使われたということですね。新札対応機が助成対象になったというのはすごく歓迎するところなのですが、この対象経費の3)の「新機能追加や機能向上により業務改善が図れる設備への」というところですが、これに当たる設備というのは、ＰＯＳレジと新札対応券売機などというご説明がありましたが、何かほかに具体的な、こういうものがありますよというのがあれば教えていただければと思います。","respondent":"小林地域産業振興課長","answer":"ＰＯＳレジ、新札対応券売機以外のところで業務改善に資するという部分で、何か具体例はあるかですけれども、ここに書いている製造業の機器で言いますと、例えば検査機、ボイラー設備など、こういうものについても、５年前、１０年前と比べますと。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"昨年度の実績につきましては、ただいま安藤委員から聞いていただきましたので、そうした実績を踏まえて、今年度のこの１億６０２万３,０００円というところで、１５０件だと１件当たり６６万円という平均で見込んでいらっしゃるのか、そこの算定の根拠となったのは昨年度の実績なのかなと思いますが、その辺のご説明があればと思います。以上２点、お願いします。","respondent":"小林地域産業振興課長","answer":"２点目のご質問は、１５０件の今後の見込みとかということですか。今後の補正予算の見込みにつきましては、昨年度の実績を見込んで、大体月間５０件ぐらいのペースでとは考えておりますが、１１月下旬から１月３１日ということで約２か月間を考えておりまして、そうすると。","id":"exchange-003"},{"speaker":"おぎの委員","kind":"質問・要望","question":"区民の方の要望などを見て、柔軟に対応していただけたらと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"供給の不足がある場合とか、そういったおそれもあると思いますが、申請期間が１１月下旬で、交付決定後から令和７年３月１４日までに導入および支払いを完了することが助成の条件となっていますが、１１月下旬、１２月にもつれ込んで、１、２、３月に入り込んでしまうと、この契約期間から導入までが間に合わない場合が出てくるかと思われるのですけれども、そこに対しての考慮。","respondent":"小林地域産業振興課長","answer":"本当に申請が始まりましたら早めに受け付けたいと、当然ながらスピードを持って対応したいと考えていますし、そういう中で、事業者の方にもやはり計画性を持ってというのですか、あと、納品の先についてもいろいろご相談いただきながら。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"事業を開始して速やかにということの答弁をいただきまして、確認させていただきました。新札不可の券売機とかは、衣料店とか飲食店でも見ますが、こういう事業主からすれば大変ありがたいという声も出てくると思いますが、やはりその反面、反発の声を招くおそれもあると思われますので、より一層、区独自の配慮もお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"藤原委員","kind":"確認","question":"２点確認ですけれども、１点は、去年の制度を使った方でも今回この制度を使えますかということと、今、事業所の方には、議会の議決を得れば、この補正で配る、事業主に配布みたいな答弁があったのですけれども、それは郵送でやるのですか。そういう形でやるのですか。区は、区内中小企業という意味では把握しているかもしれないけれども、個人事業主まで全て把握しているのですか。","respondent":"小林地域産業振興課長","answer":"これについて、基本的に我々、産業ニュースをお配りできるところはお配りしているのですが、今回タイミング的に、産業ニュースを配るタイミングからすると、ちょうどはざまに当たるといいますか、１０月にもお配りするのですが、その時点ではまだ議決をいただいていないというか。","id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"２点お伺いします。１点目は、上限８０万円ということですが、これは４番目の、いわゆる単価１０万円以上の設備であればいいということなので、幾つか複数の機械をこの補助金として活用できるのかという点を教えてください。これが適切なのかどうか。要は２か月の期間で１５０件の申請業務に対して７００万円というのが、例えばほかの事業とかと比べて妥当なのかどうか、その辺を教えてください。","respondent":"小林地域産業振興課長","answer":"２点目の、業務委託の期間ですが、申請の受付期間につきましては確かに２か月間ですが、その前の準備段階、あるいは申請が１月末に終わってから、２月、３月の内容のチェックというのですか、支払いの手続も含めて、そういったところも含めての委託ということにしておりまして。","id":"exchange-008"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"何か私からこういうことを聞くのも少しあれなのですが、これは、事業に対する省エネとか業務の効率を上げるとかということなのでこの所管なのでしょうかというのを１個聞きたくて、会派の中でこの補正予算について議論したときに、これは大変いい、必要な補正だよねということだったのですが、例えば個人事業主というと、本当に限りなく個人の生活と業務が一体化しているような事業があると思うのです。","respondent":"小林地域産業振興課長","answer":"ご指摘の点を踏まえてということで、制度設計の中でまずしていますのが、ここに１品目当たり単価１０万円以上の設備であることという条件も入れておりますが、やはり我々は地域産業振興課ですので、あくまで事業用設備ということで一定の線引き。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"確認","question":"分かりました。一方で、やはり今のこういう気候危機のこととかを考えると、みんな省エネルギーには協力したいと思っているけれども、省エネルギーをしようと思うとお金がかかるというところで、個人に対するのはどうなのだろうねという議論になりまして、そもそもこの所管ではないかもねという話をしながら、そうすると、建設委員会の方になると思うのですが、そのことを確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"先ほど答弁で他自治体の事業も参考にというご答弁があったので、参考までに、同様のこういった助成事業をやっている自治体というのは結構ほかにあるのか、そこだけお伺いしたいと思います。","respondent":"小林地域産業振興課長","answer":"やはり品川区というか基礎自治体として、スピード感が大事だと考えていますので、金額は東京都よりも低く抑えてありますが、その分、申請スピードとか、例えば証明を物すごくたくさん、省エネ効果がどこまでという膨大な書類を求めてということはしなくて。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"例えば２３区とかで同様の事業をやっているところがあれば、最後に教えてください。何区ぐらいあるか、分かれば教えてください。","respondent":"小林地域産業振興課長","answer":"省エネのほうは、我々も、これは去年の例ということになりますので、恐らく３区ぐらいではないかなと思っているのと、あと、今回、自動券売機の対応ですけれども、こちらについては、墨田区と北区が直近で対応を進めていると我々は認識しています。","id":"exchange-012"},{"speaker":"せお委員","kind":"意見","question":"１点だけ、すみません。先ほど、東京都だと現場まで行ってみたいな話で、品川区はスピード感を持ってというお話だったのですが、例えば、ごめんなさい、私の知識がないので、窓口業務とか、あと交付を決定する方たちとか、そういうスタッフというか職員の方は、どういった知識とか資格とかがあるとできるのかなと思って。","respondent":"小林地域産業振興課長","answer":"今回、品川区が実施するものにつきましては、申請者側にとっても我々実際審査する側にとっても、ある程度のスピード感というところが大事ですので、今回で言うと、やはり消費電力なり、あるいは一定の性能について、何というのですかね、コピーをつける、写真をつけるという形で。","id":"exchange-013"},{"speaker":"安藤委員","kind":"提案","question":"共産党としても、昨年度末で切れるこの事業の継続をと質問していましたし、予算修正提案を行うことも求めてきました。しかも今回、対象経費とか設備の項目を広げたということで、さらなる支援の拡大につながるということで歓迎します。賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-02","title":"令和５年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和５年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、指定管理業務の概要のところで、何を指定管理業務の項目に挙げているかというところですが、２番目に「産業振興に係る事業の企画、運営等に関すること」というのが挙げられているのですが、品川区の担当課自体がどういった方向で事業を進めるか、行いたいかという考えを持って、こういった指定管理に行ってもらうということが重要だと思うのですが、品川区の産業支援。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"多目的室という部屋を使って様々なセミナーを開催しておりまして、こういったものは、いわゆる講師謝礼ですとか企画運営にかかる費用は発生するものの、利用者は原則無料ですので、こちらは収益というよりも。どうやって反映するのかですが、ただいま申し上げたようなことを、指定管理者のプロポーザルを５年に１回やっておるのですけれども、そういうところで区の方針というのを要求仕様で提示したり、それから。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。では次に、きゅりあんとスクエア荏原ですが、こちらも管理運営委託料の決め方について、それぞれ伺いたいと思います。この差引収支というものが下にあるのですが、基本的なことで申し訳ないのですが、こちら、差引収支の金額の行方というのですか、どこに行くのでしょうかということを伺いたいと思います。","respondent":"大森文化観光戦略課長","answer":"私が、こちらのホームページ等を見たところ、お借りになるのは、ホームページ等を見て、こういう施設があるのだなというところで皆さんご判断されるのかなと思ったところ、そのホームページの表に、展示室があるということがあまりよく見えないというところもあったので。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"自分も、展示室は、区民の方がいろいろ自分の成果を発表する上では、すごく求められている施設だと思いますので、多くの方に見ていただくとともに、使用していただけるように、工夫していただければと思います。管理運営委託料の決め方についても、こちら２つの施設について、共通だと思うのですけれども、伺えればと思います。","respondent":"大森文化観光戦略課長、三井スポーツ推進課長","answer":"２つの施設の委託料の決め方ですけれども、こちらは、指定管理者が両方とも公益財団法人品川文化振興事業団ということもありますので、年度の予算編成前に、こちらの品川文化振興事業団の予算要求額と、あと。ゼロ円については、最後、精算をしておりますので、利用料金によって指定管理料に増減があるというような形で、最後、決算でこちらはゼロ円となっております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"昨今、維持するにもいろいろな経費が上がっていたりしますので、この施設に限らないのですが、区民が使う区の施設を健全に運営するに当たっては、物価高騰ですとか、そういったところの影響もあろうかと思いますので、そこについては実態に応じて柔軟に対応していただければなと思います。意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"この全ての施設に品川区のＯＢが行かれていますよね、指定管理者ということですけれども。これはどういうふうに私は理解すればいいのでしょうか。そこに行くのがルールになっているのか教えてください。それと、もう一つは、これは確認ですけれども、収支とか財務をきちんと監査というか、監督していると思うのですけれども、使途不明金はありませんね。確認です。","respondent":"栗原創業・スタートアップ支援担当課長、大森文化観光戦略課長、三井スポーツ推進課長","answer":"収支、財務の監督についてですけれども、年に１回、内部監査というものをやっておりまして、そういった使途不明金などがないかということも。ＯＢの雇用というのですか、そちらの認識ですけれども、文化振興事業団につきましては定款の第６章等に、理事長の決定ですとか評議員の決定について。使途不明金については、特にこちらでは把握はしておりません。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"一番初めのところですが、３階はホールで収入があって、健全にというか、運営されていると。では、４階なのですね。先ほどいろいろご説明をいただいて、事業内容とかは理解したのですが、この数字だけを見ると、例えば令和５年だと収入が約９,０００万円ですね。この辺をどのように考えているのか教えていただきたいのが１点。この理由が何なのかというのを教えてください。","respondent":"栗原創業・スタートアップ支援担当課長、大森文化観光戦略課長、三井スポーツ推進課長","answer":"今ご指摘いただきました、４階部分の赤字についてどう思うのかですけれども、確かに貸し部屋にして何もサービスを行わないほうが。それで、その年の状況でもって次の年度にどれぐらいかかるかとか、利用料が落ち込む分だけ補填分が増えるというところで、そういったところの運営との。スポーツのほうは、令和３年度は指定管理事業費が少し下がってはいるところですが、どうしても維持管理費、人件費、保守管理費。","id":"exchange-020"},{"speaker":"石田（し）委員","kind":"提案","question":"そういうのを少し検討していただきたいなと思います。そうすると区にとってはメリットになるわけだから、そういった総合的に判断をしていただいて、今ある区民のみ利用というのは、少し今の時代に合ってこないとなってきているのではないかなと思うので、その辺はぜひご検討していただいて、改善できるところを改善していただきたいなと思うので、これは要望で終わりますが、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"いろいろご説明ありがとうございました。指定管理者を指定するときにはそれがあったようにご説明を受けたと思うのですが、こういう事業の結果としてのモニタリングの中に、今の時代、働く人を集めることとか人件費の問題もありますし、そういう意味では、ぜひ労務に関するモニタリングという視点を入れるべきだと思うのですが、その点についてのご見解を伺いたいと思います。","respondent":"大森文化観光戦略課長","answer":"労務に関するモニタリングについては、次年度の独自アンケート、それから、こちらも民間委託によるアンケート、特に独自のアンケートにつきましては、話合いの結果そういうことを入れやすいのかなと考えていますので、そういったところも検討しながら進めていきたいと思います。","id":"exchange-022"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それで、これは当然だと思いながらあえての確認ですが、区政運営会議においてはその辺のかなり詳細な報告が上がって、それを基に評価をしているという理解をしてよろしいですね。当然だと思うのですが、一応確認です。よろしくお願いします。","respondent":"大森文化観光戦略課長","answer":"はい、こちらだけではなく資料がございまして、そういった形でご報告させていただいておるところです。","id":"exchange-023"},{"speaker":"吉田副委員長","kind":"確認","question":"ほかの施設についても同様と考えてよろしいですよね。すみません、一応確認です。","respondent":"三井スポーツ推進課長、栗原創業・スタートアップ支援担当課長","answer":"指定管理については、全部同様に区政運営会議にかけている状況になります。前お二人の答弁にもあったように、こちらについても同様に、区政運営会議にかけているところです。","id":"exchange-024"},{"speaker":"おぎの委員","kind":"質問","question":"今の吉田副委員長の質問の続きですけれども、３年目に外部のモニタリング調査を入れるというのは決まっているということで、その外部のモニタリング調査の結果というのは、私たちは見ることができるのでしょうか。どこかホームページなどに載っていたりするのでしょうか。","respondent":"大森文化観光戦略課長","answer":"公表されているかというところは、担当部署に確認して、後日ご報告でもよろしいでしょうか。","id":"exchange-025"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"改めてですが、品川区が創業・スタートアップ支援に取り組む目的は何なのかというのを伺いたいと思います。こういった支援事業ですが、少し説明にもあったかもしれないですが、区としてはどういった規模の事業者というのをメインの対象にしているのかというのを伺いたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"３点目の、地域に特色のあるエコシステムということですけれども、既にいろいろな拠点都市でスタートアップ・エコシステムというのは構築されておりまして、例えば東北のほうですと、東北大と連携して大学発スタートアップを特色にしているところですとか、それから。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"軌道に乗るまでなかなか大変だということで、例えば商店街とかの空き店舗などを活用して、一定期間、軌道に乗るまで低廉に貸し出してもらえないかという要望を結構いただくのですが、これも立派な創業・スタートアップ支援だと思うのですが、そういう、個人事業主の方が自分のアイデアとか個性を生かした店舗等がどんどん増えていくというか、品川区だったらチャレンジできるなと。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"商店街で出店した方に対しての家賃の負担というところですけれども、今、東京都中小企業振興公社が、そういう個店を開業したときの家賃の支援をするという助成を実施しておりますので、区としてはそういう都の施策なんかを一緒にご案内するというところで、いろいろな。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"一旦窓口につながって、様々な面につなげていくというところだと思います。結構周りの方でそういう方もいらっしゃいますので、それはお願いしたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"おぎの委員","kind":"質問","question":"「五反田バレーって何」という形で。そうすると、一般的な民間企業にお勤めの方などでも、事案によっては、あ、自分の地元でこういうのがあったななんて思って、通常業務でも、品川区の事業に声かけの機会が生まれたりもすると思いますので、その辺をもう少しうまくアナウンスしていただけるといいなと思いますが、いかがでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今後についても、スタートアップの例えばプロダクトの実証実験で、民間のコワーキングスペースなどとも連携して、いろいろなところでスタートアップの製品を体験できるという活動はしていきたいと思っておりまして。","id":"exchange-029"},{"speaker":"おぎの委員","kind":"質問・要望","question":"せっかくいいことをやっていても、知っていただかないともったいないなと思いますので、今、情報発信ツール、ＳＮＳとかユーチューブとか、そんなにお金がかからなくて発信できるものもいろいろありますので、ぜひ強気に発信を続けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"ゆきた委員","kind":"質問","question":"アントレプレナーシップ教育プログラムについて、少し触れてお聞きしたいと思います。小中学生が自分で課題を抽出して、その課題を乗り越え、克服していくというのは、非常に重要なことだと感じています。ぜひ今後の展開、何年までに、将来的にはこういう展望だとか、そういうものがもしあれば、お聞きできればと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今年度やはり想像以上の反響があったことを踏まえますと、今後、もう少し拡充などを図っていくことも視野に入れてやってまいりたいと考えておるところです。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"意見","question":"今あったとおりで、着実に進めていただければと思います。応募総数が７０名以上ということもあるので、さらに需要を増やしていけるような取組を進めていただければと思います。その辺で何かあれば、もう少しお願いします。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今お話がありましたとおり、ここの中の創業支援施設のＳＨＩＰ、武蔵小山、西大井というところで、西大井が一応学生を推進しているというところで、特段小中学校ということは書いていないのですが、もちろん重点テーマに「教育・子育て」とありますので、小学校ですとか。","id":"exchange-032"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"このスタートアップとか五反田バレーとか、僕は五反田で活動しているからあれなのだけれども、少し浮いていますよ。でも、全然接点がないからな」みたいな感じで、どうしても距離感を感じてしまっているので、そこはぜひ行政として、行政だからこそ多分できる、つなげる役割というのがあると思うので、そこはぜひやっていただきたいなと思うのですが、そういった面を含めて何かあれば教えてください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"やはり交流会ばかりやってもというのはご指摘のとおりで、それ以外の支援ももちろん実施しているところではありますけれども、やはり年に２回ぐらいは地域の方と顔と顔が見える、そして、スタートアップって何かよく分からないけれども。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"本気で評価していました。そういう意味で、社会課題として、こういう分野にＩＴというのですか、いわゆるＩｏＴとかＩＣＴとか、そういう意味で介護に関してやっていっていただきたいという思いがすごく私はあったのです。だから、若い方が子育て・教育でなくてもいいではないですか。でも、その夢とかアイデアを実現させてあげるというのがスタートアップだと思っているので、その辺についてはいかがですか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ただ、今委員がおっしゃったように、介護もこれからの社会課題で、すごく重要なテーマだとは認識しておりまして、実際、先ほど項目３番のスタートアップ支援で五反田バレーアクセラレーションプログラムというのをやっているとご説明させていただきましたけれども。","id":"exchange-034"},{"speaker":"せお委員","kind":"質問","question":"福祉、あと、ここに教育・子育てはあるので、入っているのだろうなと分かるのですが、そういったところも何か分かりやすくしてほしいというところが１点と、あと、先ほどゆきた委員からもあったのですが、私、一般質問でも先週言わせていただいたのが、教育で産官学連携してほしいなというのがあったので、このアントレプレナーシップは子ども向けの教育だと思うので、そうではなくて。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"先ほど申し上げた五反田バレーアクセラレーションプログラムは区外のスタートアップも参加しているのですけれども、やはり区内の学研ですとか、そういう教育機関と連携をするということが特典の一つなのですが。","id":"exchange-035"},{"speaker":"吉田副委員長","kind":"質問","question":"法人格を取得するときの支援というか、こんな法人格がありますよとか、それだったらメリットはこうです、デメリットはこうです、そうおっしゃっているのであればこっちの法人格のほうがふさわしいのではないでしょうかとか、そういうアドバスもしていただけると考えてよろしいでしょうか、その点について伺いたいです。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"法人成りする方に対してのメリット・デメリット、これはもう今も寄せられているご相談でございまして、これにつきましては、区の経営相談窓口しかり、各創業支援施設のインキュベーションマネジャーが適宜ご相談を承っておりますので、そういった支援を継続してやってまいります。","id":"exchange-036"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ありがとうございました。それで、このたび、法律ができた。協同組合の労働者協同組合法。個別に伺っているので、ここで公式なご答弁は結構ですけれども、ぜひそういう法人格を取るときに、そういうところも視野に入れていただきたいなという要望です。要望ですが、もし何か少しでもコメントしていただけるようなことがあったら、伺いたいです。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"区としては、皆様のご質問にもあった、ソーシャルビジネスに該当するところかなとは思いますので、そういった方々もご支援はしてまいりたいと思います。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/965719?Template=document&Id=6821#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":45658,"voices":116}},{"id":"r06-20240924-7","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件抜き出しています。","topics":[{"id":"topic-01","title":"令和６年陳情第３９号、全庁的に区有地の活用を検討する、障害者施設整備計画を策定し、計画的に整備を進めるよう、区に求める陳情","agenda":"令和６年陳情第３９号、全庁的に区有地の活用を検討する、障害者施設整備計画を策定し、計画的に整備を進めるよう、区に求める陳情","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほど障害者計画、この福祉計画のお話あったと思うのですけれども、今おっしゃっていた施設整備のことについて、具体的に何ページに書いてあるのか分かれば教えていただきたいと思うことが１点と、今のお話だと、この中に具体的な整備の計画が組み込まれていますということだったと思うのですが、今事例で出ている大田区、世田谷区は。","respondent":"佐藤障害者施策推進課長","answer":"それから他区の状況ですが、世田谷区の基本計画につきましては、こちらが本区の障害福祉計画と同様に、サービスの必要量や見込み量を算出しまして、補助制度や人材確保といったソフト面を含めた支援の進め方を示していたりするもので、本区の障害福祉計画と。","id":"exchange-001"},{"speaker":"ひがし委員","kind":"確認","question":"品川区のところの１０７ページを見てみると、施設の名称と事業内容と、あと書いてあるものは開設時期（予定）というようなところなので、内容が少し違うところもあるのかなというような印象を受けていますが、その点、区としてはどのように認識されているのでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"既に事業者の公募等も行っている部分も含めて、それから住民説明会等も通じまして、詳細なスケジュールや施設の概要等もお示ししているところではありますので、こちらには載せてございませんが、施設の個別の計画としましては定めているというような状況です。","id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問","question":"ということは、ここに書いてあるものはあくまで概要で、ほかに個別具体的な施設の整備の計画を示すものがあるということだと思うのですけれども、それは一般的に公表されて、何か基本計画のような感じで出されているものなのでしょうか。もし分かれば、名称も教えていただければ後ほど見てみたいと思うのですが、教えていただけますと助かります。","respondent":"佐藤障害者施策推進課長","answer":"今申し上げましたように、個別の、例えば大原児童発達支援センターにおきましては、そちらの整備の予定ということでお示ししていますので、そちらについてのまとめた、このような形での施設整備基本計画という形の名称でお示ししているものではございません。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問","question":"大田区や世田谷区のような、この計画を立てるなどとなったときに、多分職員の人員の負担などもかかるのかなと思うのですけれども、現状福祉部、少し人が足りないのではないかというようなことを一般質問等でも言われていましたが、これつくるとなったときにどのぐらい負担がかかるのかとか、人員を確保できるのかというところ、もし分かれば教えていただければと思います。","respondent":"佐藤障害者施策推進課長","answer":"今お示ししている部分につきましては、新規の区の整備案件というようなところですので、先ほど、最初のご説明の際にも申し上げたようなところで、土地確保等の課題もありますので、現時点で整備予定が決まっているものを明らかにしておりますが。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"所要量。所要量というものは、見込み量に対して、では区がどれだけいつまでに、整備をどのような形でしていくのかという計画を出しているということなのです。見込み量。品川区。そのようなことなので、もう本当にグループホームの、何というのですか、要望というものはすごく出されているにもかかわらず、では品川区でその要望にどう応えていくのかという計画というものが出されていないということなのです。","respondent":"佐藤障害者施策推進課長","answer":"そういった部分につきまして、現時点では、区の整備案件というようなところにつきましては、戸越四丁目以降の部分については、現状お示しできていない部分はありますが、こちらも繰り返しになりますけれども、施設を整備できる場所等も含めて確保が必要になりますので。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"大田区のほうは大田区のほうで、区立の障害者福祉施設整備計画というものをつくって、５つの施設について、基本計画、基本設計、実施設計、建築工事について、１２年間にわたるスケジュールというものを明らかにしているのですけれども、品川区としても、先ほどの１０７ページの、もう決まったことに対してはそのようなものが明らかにされていますが、今回の心身障害者福祉会館についてというものは。","respondent":"佐藤障害者施策推進課長","answer":"現時点で、このタイミングでこのような形で整備が決まりましたというところについては、まだ申し上げられる状況にはございませんが、検討を進めているところですので、こうした対応も含めまして、なるべく早くお示しできるように今後も検討を進めてまいりたいと考えております。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"心身障害者福祉会館のほうは、何度も何度もここで陳情も出されて議論しているところですけれども、前回も、公共施設等総合計画の中では、建て替えのときは６０年というようなことでの全庁的なルールに基づいて記載しただけで、令和６年度から令和８年度の３年間で検討を進めたいということだったのですが、それの具体的にいつ頃までには示せるようにしたいというようなものというのは出ないものなのか。","respondent":"佐藤障害者施策推進課長、吉岡政策推進担当課長","answer":"この計画、３年の期間をもって計画として策定させていただいているものになりますので、この期間内には一定の方向性等については出するように、そのものについては進めてまいる予定です。こういったところがバックキャスティングの考え方で、どう土地を取得して、どう所管と一緒に連携して動いていくかというところが、ある種１つの計画になっておりますので、こういったところと所管等も連携しながら。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからもう一つ陳情の中で、旧料亭秀について、地域のにぎわいの維持のために区で土地・建物を利活用してほしいとの要望が出されて、区として当該物件の検討を開始したということで答弁したとあるのですけれども、ここでは障害者施設については検討の余地もなかったのでしょうかということで陳情の中に述べられているのですが、障害者施設というものは検討はされなかったのか、その点も伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"区といたしまして、民有地の検討というところになりますけれども、こういったところで、民間の方からこういった施設がある、こういった土地があるというところであれば、どういった形で活用してほしいかというお話を聞きながら、庁内で連携をさせていただいて。","id":"exchange-008"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"先ほど鈴木ひろ子委員からも、軽度のグループホームが、私の換算で多分２７か２８か、３０か所弱あるのだろうと思っています。そのようなものは、これなぜこのように増えてしまっているかというと、ジャブジャブ国からお金が出るのです。大変ご協力をいただいていろいろやったけれども、結果として１００坪の土地に６割で６０坪しか建たないわけです。だって６０坪取れないから。１００坪なんだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"要は計画と、区民への、また議会への、何というのでしょうか、ある意味での見せ方というところもあると思いますので、その計画や見せ方については、今の考え方を確認させていただきました。それが是か非かというところはまた別の問題になりますけれども、心身障害者福祉会館も含めて、今後の早急な、前に進める、そのような部門もできたと思いますので、引き続きご努力いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問","question":"本日結論を出すでお願いします。その点については、建て替えが決まったものについては個別で計画も立てているというようなお話があったので、そのようなものをまとめたり等工夫をしながら、具体性のある計画というところも作成していってもいいのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいと思います。区が責任を持って、所要量、区としてどれだけ必要なのかということを明確に示して、それをどう実現させていくかという計画というものは本当に大事なことだと思います。グループホームだけでなく、区としてどのような施設がどれだけ必要なのかということを明確に出して具体化することが必要だと思いますので、これは採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。計画については、区としても第７期障害者福祉計画で明示をしている。民間の土地活用についても、全体的にいろいろな検討をされているということで、この陳情者の意見とは違うのかなと考えております。一方、ぜひほかの区の動向や、区民の方に安心できる、安心を与えるような、具体的な見せ方というか、そうした取組、説明をもっとしていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論を出すでお願いします。趣旨採択ということでお願いいたします。この陳情を読んでいても、やはり品川区は介護の面で具体的にこのように進めていくのだというものが見えづらくて、不安になられている方がこのような陳情につながっているのではないかと思いますので、私としては前に進めていっていただきたいという意味で、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"第７７号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第７７号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そこのところは、改めて今後どのようになっていくのかということも含めて伺いたいと思うのですけれども、今課長の、本当に説明が簡単で、品川区の状況、もう本当に条文が変わりますよというだけなのですが、区民の中では、マイナ保険証になっていく１２月２日から新たな保険証は発行しないというようなことで、すごく今でも大きな混乱も起こっていますし、医療の現場ではすごい問題になっていますので。","respondent":"池田国保医療年金課長","answer":"マイナ保険証の利用率については、こちら７ページの資料が国民健康保険のほうでは最新のものとなっているところです。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"確認","question":"そのように言われていました。その辺のところは、区としては、ちょっと今後に起こる問題、課題に対して、どのようなことが懸念されて、どのような対応が必要なのか、その辺はどう考えられているのかもひとつ伺いたいと思います。これは周知することが必要なのではないかなと思うのですけれども、その点についても伺います。","respondent":"池田国保医療年金課長","answer":"後期高齢者医療制度につきましては、来年の７月３１日までの有効期限での保険証を今年発行させていただいておるところです。ということで、保険証がなくなるということでのＰＲについては、１１月以降順次する予定になっているところです。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"確認","question":"そうすると、では今の使っている保険証は、その期限が切れるまで、国保であれば９月３０日まで使えます、それからその後も、マイナ保険証に登録していなくても安心してください、資格確認書が自動で送られますという広報というものはされるのでしょうか。そのことが１点です。そのような方というものは、マイナ保険証の登録取消しというものが１０月からできますよね。","respondent":"池田国保医療年金課長","answer":"基本的にはマイナ保険証が今後の基本の、医療機関にかかる、受診する際に使うものでございまして、特例なものとして資格確認書が発行されるですので、特段資格確認書を発行しますというところはＰＲする予定はございません。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これだけ大きな変更なわけなのにもかかわらず、そのようなことなので、もう本当にその不安の、国民皆保険制度は守りますというような点からも、９月３０日までは使えます、それから、資格確認書は自動的に送られてきます、それで今までと同じようにかかれます、それからマイナ保険証を登録してしまった方も、登録して、だけれども使いたくない人は取消しができますということは。","respondent":"池田国保医療年金課長","answer":"登録のほうで、マイナカードのほうの登録をしていない方への周知などというところについては、これ国のほうでやることですので、国保としてどうなのかというところでは、前の保険証がまず１２月２日から発行ができないということでの周知をということにする予定になっております。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問","question":"これはもう、国のほうとしては対応を取ったのでトラブルはなくなりますというように言ってきた、その５月以降に。私はこれをご覧になっていただいて、このようなことが実際にこれからもっともっと増えていくのだなというところを、何というのか、踏まえた上で、様々な対応というものが必要なのではないかと思うのですけれども、その点も伺えたらと思います。","respondent":"池田国保医療年金課長","answer":"実際の部分については、国のほうでマイナカードの推進ということをされているところでございまして、こちらのほうは国のやっているところについて見守っていくというところ、注視するというところでいきたいと考えているところです。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問・要望","question":"マイナ保険証というものは、これだけ皆さんから求められていないということなのです、結局。便利だったらば、どんどん広がっていくと思うのです。そのようなところをどれだけ抑えていくかというようなことから考えたら、今でも資格確認書、または資格情報のお知らせというようなところで、保険証の代わりになるものが送らざるを得ないという状況になったわけですから、これは保険証と変わりないわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"確認","question":"頂いた資料の３ページ、マイナンバーカードと被保険者証の一体化に伴う区の対応というところで、令和７年９月３０日に資格情報のお知らせ、または未保有者には資格確認書を交付というようになっていると思います。何か新しくまた配るということで費用等もかさんでしまうのではないかなと思っているので、１点確認させてください。","respondent":"池田国保医療年金課長","answer":"こちらのほうは、保険証の更新事業というものはこれまでも２年に一度やっていたところでございまして、来年の９月３０日が、ちょうど保険証が切れる、有効期間が切れるときですので、保険証の更新事務ということで行うところです。","id":"exchange-021"},{"speaker":"ひがし委員","kind":"意見","question":"具体的な数字は出てこなかったですけれども、基本的には２年に一度もともと配っているから、そこから業務としては変わっていないというところで把握をいたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"確認","question":"マイナンバーカードがあった上でのマイナ保険証というわけです。ですから、マイナ保険証が今後切り替わるということで、今後資格確認書を使うということは例外、特例であるというようにおっしゃられて、資格確認書が使えますと、そういったような周知は特に考えていないということだったのですけれども、私は特例ではないと考えているのですが、もう一度その辺詳しくご答弁いただけないでしょうか。","respondent":"池田国保医療年金課長","answer":"実際に使用する際には、現在お使いになっている保険証と、それから資格確認書というものが同じような使い方を１２月以降するかとは思いますけれども、あくまでもマイナカードのところで保険証を。","id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"確認","question":"繰り返しになってしまうのですけれども、やはりマイナンバーカード自体がまず任意であるというような前提に立っていると私は考えておりますし、当然これ、国の決めていく制度に沿っての改正ということもあるので、当然勝手に品川区がどうとかするということはできないということは承知しているのですが、こういった制度の上でできることというと。","respondent":"池田国保医療年金課長","answer":"私どもとしては、１２月２日以降保険証は廃止になったということで周知をさせていただきまして、廃止以降の部分についての異動等があった場合には、資格確認書、もしくは資格情報のお知らせを発行するというようなことでは周知という形になるかと思います。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"形式的なものではなくて、やはりしっかりと分かりやすく周知をしていただきたい。私が高齢者の方とお話ししていると、やはりもう１２月２日以降は保険証が使えなくなるのだ、紙の保険証が使えなくなるのだというように勘違いされている方も結構いらっしゃいますので、その点は強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"意見","question":"反対です。登録した人は５割にも満たない、それで、さらに利用者はその５分の１、１割にも満たないという、そのような状況であるにもかかわらず強行すると。存続させるべきだと繰り返し繰り返し記者会見もされ、それから国会前の抗議行動もされ、もう本当に声を上げ続けています。裁判にも訴えています。マイナンバーカードと保険証をひもづけている国は、Ｇ７でもどこでもありません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"やなぎさわ委員","kind":"意見","question":"反対です。様々ありましたけれども、やはり紙の健康保険証も残しつつ、どちらも使えるというような、選べるという、国民が選べるという選択肢を設けるべきだと思いますので、反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"ひがし委員","kind":"質問","question":"一点だけ、インクルーシブひろばベル、私も視察させていただいたのですけれども、多分今回事業者、新しいところに変わることになると思うのですが、ここで勤務されていた方々、スタッフなどは総入替えで替わってしまうのか、引継ぎ等どのようにされるのかなというところが分かれば１点お尋ねしたいということと、あとはインクルーシブひろばベルでは。","respondent":"佐藤障害者施策推進課長","answer":"人員配置のところでは、今回選定しました事業者からも、医療的ケア児等コーディネーターの配置を職員配置の提案の中でいただいておりますので、その体制は引き続き維持される予定です。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回指定された学研ココファン・ナーサリーですけれども、放課後デイや保育所訪問、障害者の相談支援事業などの運営となっていますが、この学研というものは、これは全て実績というのですか、放課後デイサービス、保育所等訪問支援、そして障害児相談支援事業、特定相談支援事業、医療的ケア児地域生活支援促進事業、児童館の運営というものは、まず全て実績があるという感じなのでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"今回の選定に関しましては、公募の要項のところで応募資格を設定しておりまして、こちらに関しましては、その部分に関しましては、児童発達支援事業所の実績を有する法人ということで、児童発達支援センターになってしまいますと。","id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"質問","question":"医療的ケア児支援の実績というものはいかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"今いただいた医療的ケア児コーディネーターの部分につきましては、こちらの事業を行っていただく部分について、インクルーシブひろばベルの実施を継続のところで公募をしておりますので、そこの部分に対して、先ほど申し上げた形で。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"医療的ケア児支援の実績はあるのかという質問でした。学研ココファン・ナーサリー。","respondent":"佐藤障害者施策推進課長","answer":"医療的ケア児の支援の実績に関しては、こちらのほうでは確認はしておりません。","id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問","question":"今回３ページのところで、５事業者から応募があって、１事業者が欠格事由に該当、失格で、別事業者は応募を辞退したということなのですけれども、今回は５事業者の応募があるまで、何事業者にどのような形で働きかけたのかを伺います。それから、１事業者の辞退の理由も、どのような理由なのかも伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"応募の辞退につきましては、こちらで伺った部分につきましては、応募はしたけれども、区が実施する事業の内容について最終的に実施できる状況にないと、事業者のほうで判断されたというように伺っております。","id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほどのやなぎさわ委員の続きなのですけれども、医療的ケア児支援の実績は確認できていないということなのですが、障害児施設の指定管理の実績というものはあるのか、そのことも教えていただきたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"児童発達支援の部分につきましての運営実績というところで、現在のところこちらで承っている状況については、繰り返しになりますが、児童発達支援の事業所の運営ということで、こちらのほうで確認しています。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"確認","question":"今回インクルーシブひろばベルも、この指定管理の業務の１つとしてあると思うのですけれども、現在フローレンスがインクルーシブひろばベルを運営されていますが、そのスタッフというものは引き継がれていくのか、それとも学研ココファン・ナーサリーで新規に常勤の看護師を雇うのか、その辺のところも、どのような考え方なのかも伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"ベルの人員体制でありますが、先ほどのご質問でもありましたとおり、今後の職員体制等につきましては、事業者と調整の上進めてまいりますので、現時点で職員がそのまま引き継がれるか等につきましては、確定しているものではございません。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"提案","question":"ホームページのほうに公募要項も出ていましたし、それから、提案要求事項についてというものも出ていましたので見させていただいたのですけれども、この中で、両センターにおいて実施する事業の提案、自主事業の提案がある場合はその内容も含め提案してくださいということで書かれているのですが、これは実際どのような提案があったのかも伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"数字としましては以上になりますが、補足をしますと、医療・福祉業界全体の離職率が、令和５年の調査機関の概要で１６％というところですので、これで確認すると若干高くなっているところではありますけれども、これにつきまして事業者側の説明としましては、全体的な傾向として。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、結構指定管理料というものは、何というのですか、本来のサービスだけではないという部分があるので、かなり指定管理料というものは高額になってくるのかなという思いがしているのですけれども、その辺のところの指定管理料の、運営収支計画というものも出されていると思うのですが、その指定管理料というものはどれくらいになるのかということを伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"この辺りは、割合にしますと、指定管理料が６８％程度ということになりますが、この部分については、他区の児童発達支援センター等で決算状況等が出ているものにつきまして、金額では一概に比較できませんけれども。社会福祉法人につきましては、応募したほかの事業者につきましては、社会福祉法人はございました。です。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ちょっと確認させていただきたいことが、児童発達支援センターなので、１８歳まではずっとそこで見てもらえるのかというところ、その子どもの情報をセンターが管理して、１８歳まではいつ相談に行ってもきちんと対応してくれるのかということは伺いたいと思います。それから、保護者の支援をどのような形で継続して行うのかというところもお聞かせいただけたらと思います。","respondent":"佐藤障害者施策推進課長","answer":"保護者の対応ですけれども、先ほど申し上げたような保護者会、そういった部分で独自の提案等もあり、それから通常対応が予定されている発達支援、それから放課後等デイサービス等での決められた範囲での対応につきましては、保護者対応等を続けてしてまいりますので。","id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問・要望","question":"検査の点については、ぜひ児童学園と同程度の検査はできるようにしていただきたいと思います。取りあえず結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"若林委員","kind":"確認","question":"候補者選定委員会等２つの委員会が開かれて、区の審査の過程が、意見も出ていますので、その確認だけ。それからもう一つ、区との連携を重視している点があると見られるということですが、ここについてもご説明を伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"障害特性別支援の考え方が具体的に明示されているというところですけれども、こちら区の児童発達支援センターということで、中核的な役割を担うというところもありますので、特定の障害別に特化するということではなく。こちらにつきましては、事業内容をかなり手厚くご提案をいただいているところがありますけれども、ここのところの中で、選定委員会のほうでの委員の意見もありますが。","id":"exchange-039"},{"speaker":"若林委員","kind":"質問・要望","question":"それから２番目、３番目はそのようなことなのですね。その辺はぐるっぽ、児童学園、区との対比というか、こちらの学研ココファン・ナーサリーの持ち味も含めて、その辺どのように区は感じていらっしゃるのか、また期待するところ、お願いしたいところがあれば、お聞きしておきたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"障害特性別支援のところではありますが、障害の状況に応じて、例えば放課後等デイサービスの部分については、集団を必要に応じて小集団に分けて、対応プログラム等を実施したりするようなところや、発達支援の中でも、その障害の状況に応じて、先ほども質問でもいただきましたが。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問","question":"職員数、先ほど一部分で伺ったのですけれども、この施設全体で職員数が何人になるのか、ちょっと職種別に分かったら、それも教えていただけたらありがたいです。","respondent":"佐藤障害者施策推進課長","answer":"それで、児童発達支援センターのところについては、児童発達支援と放課後等デイサービスにつきましては、先ほど申し上げたとおりですが、先ほど申し上げていないところでは、保育所等訪問支援につきまして、訪問員と保育士が各１名、それから相談支援事業所におきまして。","id":"exchange-041"}]},{"id":"topic-03","title":"令和６年請願第１２号、「長寿お祝い事業」の予算削減を前提とした見直し、及びその削減予算分の減税に関する請願","agenda":"令和６年請願第１２号、「長寿お祝い事業」の予算削減を前提とした見直し、及びその削減予算分の減税に関する請願","exchanges":[{"speaker":"筒井委員","kind":"質問・要望","question":"事務事業評価で、これＣ評価になっているのですけれども、それでも引き続き、この長寿お祝い事業をやる、その理由というものをもう一度教えていただきたいと思います。","respondent":"東野福祉計画課長","answer":"この長寿お祝い事業につきましては、区としては、高齢者の方に喜ばれている事業、明日への活力につながる事業ということで、続けていく考えです。","id":"exchange-042"},{"speaker":"筒井委員","kind":"確認","question":"そして救急代理通報システムなど、ほかにも様々、見守りという点ではどんどん新しいテクノロジーの発展もありますが、そうした新しい見守りシステムがある中、それは、商品券を渡しに行くことが、それほど見守りということになるのかなと思うのですけれども、その辺りいかがかお考えでしょうか。","respondent":"東野福祉計画課長","answer":"民生委員がこの長寿の方に接する機会の１つとして行っていたという側面もありますので、見守り事業という中に位置づけてきたものです。近年、コロナなどの状況によりまして、郵送方式によることも行っておりますけれども、見守り自体は有効な、効果的な事業だと考えています。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"見守りもいいのですけれども、あと、そもそもこれ、８８歳米寿、卒寿９０歳、白寿９９歳、１００歳、その年齢をかなりの密度で設定していますが、では、例えば８９歳の人はどうするのだとか、白寿と卒寿の間の９９歳から９０歳の間の人はどうするのですかとか、いろいろそうした状況が起きてくると思うのですけれども、その辺り、見守りという点ではどうなのか。その点お聞きしたいと思います。","respondent":"東野福祉計画課長","answer":"このところの間の方につきましては、当然何もしないというわけではなく、高齢者の見守りとしましては、先ほどの救急代理通報システムや、それから町会、企業による見守りネットワーク、こういったものを活用しているものでございまして。","id":"exchange-044"},{"speaker":"筒井委員","kind":"質問","question":"ということであれば、逆にそのお祝い事業をやる必要もないのかなということもありますし、逆にこの対象に、白寿、卒寿、米寿の対象になっていない人、例えば９０歳、９９歳から９０歳の間の人、８９歳の人はこの商品をもらえないということになってしまい、高齢者間での不公平感のようなものが出てきてしまうのではないかなと思うのですけれども、その辺りいかがお考えでしょうか。","respondent":"東野福祉計画課長","answer":"そのような意味では、特に不公平ということではなく、その年に達しましたらお祝い品をお送りして敬うというようなことは、続けていく所存です。","id":"exchange-045"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうですね。引き続きやるにしても、先ほど８０歳はもう廃止をしたというご答弁があったのですけれども、少なくとも、では１００歳以上に限るなど、どんどん範囲を狭めていかないと、中長期的に余裕がなくなっていくのかなと思いますし、人生１００年時代と言われている状況ですから、どんどん支給するのだったらもう少し条件を厳しくいないと駄目かなと考えているのですが、その辺りいかがなのでしょうか。","respondent":"東野福祉計画課長","answer":"範囲を狭めてですが、当初お話ししたとおり、見直しするべきところは見直すというところで、長寿命化のところの範囲を超えてくれば、それは見直しの対象と考えているところです。","id":"exchange-046"},{"speaker":"筒井委員","kind":"質問・要望","question":"社会福祉協議会も同じような、同様のことをやっているのですけれども、逆にこちらのほうにもう任せてしまうなど、そういった考えもあると思うのですが、その辺りいかがお考えでしょうか。","respondent":"東野福祉計画課長","answer":"それぞれ考え方のすり合わせをすることはできるかと思いますが、それぞれの、区としての立場、社会福祉協議会としての立場、それぞれが尊重されるべきだと考えています。","id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"さらにもっと進んでいくと、減税ということもありますので、そうしたことは先ほど言ったように可処分所得を上げて、そのような少子化対策などにもつながっていきますので、ぜひそうした考え、こうした陳情者が出てくるという現状も、ぜひ品川区としては考えていっていただきたいのですけれども、その辺り、このような状況を見てどのようにお考えになるのでしょうか。","respondent":"東野福祉計画課長","answer":"私ども福祉部門といたしましては、高齢者の福祉につきまして、区民が望んでいるような福祉政策を最大限行っていく考えです。","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"長寿のお祝い。その辺も長寿を祝う、それから敬老の意を表する、そのようなものを区が行うというようなことは、当然というか、そうあっていただきたいし、続けていただきたいなと思うのですけれども、この長寿のお祝い、敬老の意を表するというところでは、筒井委員はどう思われるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで卒寿で７,０００円、白寿で１万円、１００歳で３万円、そして１００歳以上で１万円にまた下がってしまうのですけれども、それはそれほど莫大ですかという、本当にこれくらい品川区がささやかなお祝いとしておめでとうありますという、そのような気持ちを表すということは、それくらい私は、もう本当に、何というのですか、もらったほうも、「ああ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問","question":"いやいや、その辺のところはちょっと議論してもいいかなと思うのです。本当に。どうあるべきなのかという、そのようなことは。そのようなところに目を向けないで、本当に大変な状況になっている高齢者のところに目を向けて、ささやかな、米寿のお祝い、もう本当に１００歳になった、おめでとうありますと。いいではないですか、このようなものは本当に必要だと思います。このような社会というものは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"筒井委員","kind":"質問","question":"鈴木委員のおっしゃることは本当によく分かりますし、おまえもいつか高齢者になるだろうと。そうですね。ですから、高齢者福祉、高齢者福祉サービスの拡充ということはいいのですけれども、やはり直接的に、露骨に商品券というものを渡すという行為に、たまっていた不満が一気に、それによってより噴出してきたのかなとは考えております。ということで、ひとつ私としては今の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"意見","question":"今の現役世代が高齢者を支えるという、そのようなところなのですけれども、もう本当に何か、６５歳以上の人は全員若い人に支えられているという、そのようなことでよく言われているのですが、実際は高齢者がもう本当に今働いています。もう全体の高齢者の４人に１人は働いていますし、７０代以下の６９歳までの人だと、２人に１人は働いているのです。私たちも働いていますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"ひがし委員","kind":"質問・要望","question":"様々議論がされていると思うのですけれども、高齢者の方々から、この請願が出たときに意見を幾つかいただきまして、品川区が子育て施策、若い方々の支援を進めていることはとてもありがたいことだとおっしゃっていました。実際に見守りにつながった事例や、お祝いをした方々のお声というものが、どのようなものがあるのかなということは改めて聞かせていただきたいと思います。","respondent":"東野福祉計画課長","answer":"私も、やはりそれを見たときに、ああ、この事業というものはすばらしい事業なのだなというように、改めて認識をしたところです。そのほかにも区民の声などで、メールなどでもいただいているというところがあります。多くの方がお礼の連絡をいただいたです。","id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今のお話を聞くと、見守りという観点からも、また敬老の意を示すというところも、きちんと目的は達成できているのではないかなと思いました。そのような品川区の政策がきちんと高齢の方々にも伝わるということが本当に大切だと思っているので、この事業についても必要性というところをしっかりと区民の方々、若い世代にもお伝えできればいいかなと思いますので、こちらは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"筒井委員","kind":"確認","question":"そもそも請願が出た意味が、この行政評価シートの高齢者安否確認事業に含まれてこれに記載されているから、ちょっと高齢者安否確認ではないのではないかという疑問がこの請願者もあったのかなと思うので、その辺り、どちらを主として、メインとして捉えているのか、はっきりさせたほうがいいのかなと思います。","respondent":"東野福祉計画課長","answer":"先ほどの民生委員を通してのお渡しというところでの見守りという側面もございましたので、現在は高齢者安否確認事業の中に組み込まれているところですが、委員がおっしゃったようなところを踏まえて、実際の事業の体系的なところの見直しはしてもいいのかなと考えています。","id":"exchange-056"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"本日結論を出す、不採択でお願いをいたします。理由は、長寿のこのお祝い事業というものは、私どもが考えていることは、これまでの国を支えてくれてきた高齢者の方々に感謝の気持ちを表す御礼の意味もある事業であると思っているので、必要だと考えています。したがって、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"若林委員","kind":"意見","question":"本日結論を出してください。現役世代の子ども、それから孫もいらっしゃるかもしれません。会派の中でもありません。いわゆる、ただ減税を、いわゆる予算の削減ありき、また、減税のための何か１つの事業をこうやって、何でしょう、言葉が適切かどうか分かりませんけれども、やり玉に上げて云々ということは、いわゆるこの議会、委員会の中ではあまり適切ではないかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"ひがし委員","kind":"確認","question":"本日結論を出すでお願いします。ただ一方で、ご答弁でも確認できたように、今回の長寿お祝い事業というものは、見守りの観点のほかにも、長年社会に貢献してきた方々へ長寿を祝福するとともに、敬老の意を表すという目的をしっかりと果たしている大切な事業であり、誰も取り残さない社会を実現するためにも必要な事業であると考えますので、今回の請願には沿いがたいと結論します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すということで、不採択でお願いしたいと思います。この請願者が言われるように、現役世代の方の負担が重くて、可処分所得を増やす、そして少子化を解決していくということは本当に大事なことだと思いますけれども、それを高齢者に向けて分断をするような、そのようなやり方というものは違うと思いますし、もっと税の在り方など、大本のところにこそ目を向けていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"筒井委員","kind":"確認","question":"高齢者安否確認事業の中に長寿お祝い事業というものが含まれているという話が前提で、先ほど課長はその位置づけの見直しを検討していくかもしれないということをおっしゃられましたけれども、今のこの現状の高齢者安否確認事業として長寿お祝い事業を入れていくということは、ちょっと効果が不明確な点もあるのかなという点と、先ほど来述べましたとおり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ただ、やはり安否確認という名称の、行政評価シートなどでも小規模事業のところでなっているので、それはちょっと、やはり分かりにくいというか、誤解はされやすい、安否確認とは少し違うのかなというところはあるので、その辺は今課長のご答弁ありましたとおり、少しその辺見直しというか、考えられていることは、ぜひそれは進めていっていただきたいとは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-04","title":"第７５号議案、令和６年度品川区一般会計補正予算（歳出等 厚生委員会所管分）","agenda":"第７５号議案、令和６年度品川区一般会計補正予算（歳出等 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"災害時の自動安否確認システムなのですけれども、救急代理通報システムの導入世帯の９１９件のところで登録で同意を得ていくということなのですが、どれぐらいの方が想定される人数なのか、ちょっとその辺想定されている人数があったら教えていただきたいということと、これ来年の２月までシステム開発ということなのですけれども、システム開発というものはどこがやる、どこか事業所というか。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"３点ご質問いただいております。想定人数ですが、救急代理通報システムに登録ある９２０人のうち、土砂災害区域にいらっしゃる方が約１００名ほどいらっしゃいます。はそこの方々に照準を当てていきたいと思っているところです。区内のケアマネジャーの人数というところで、正確な数はちょっと足し上げていかないとというところはあるのですが、大体２５０人近くはいるのではないかなと見込んでおります。","id":"exchange-063"},{"speaker":"鈴木委員","kind":"確認","question":"加齢性難聴のサポート用イヤホンについてなのですけれども、これ今のところ、福祉部の各課と在宅介護支援センターと支え愛・ほっとステーションということなのですが、何かもう２台あって、結構効果が確認されて、これだけ拡大をするということだと思うのですけれども、難聴の方がこのような便利なものがあると、本当に、何というのですか、スムーズにコミュニケーションが取れて。","respondent":"菅野高齢者福祉課長、樫村高齢者地域支援課長","answer":"主任ケアマネジャーの人数ということで、こちら今回の補正予算を立てるに際しての想定人数としましては、８５名程度ということで試算しています。ほかへの展開ですけれども、この３５台、一応検証を含めてというところで、アンケートを利用していただいた方にも実施しながらやっていきまして、そちらの状況等を考慮しまして。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"意見","question":"本当に便利な、このようなものでコミュニケーションがスムーズに取れるということであれば、アンケートもしていただくということですので、今後拡大というようなところでしていっていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"第２回定例会で会派から要望させていただいて、城南信用金庫に続いて区でも独自に購入されるということで、大変に評価をしております。ちょっと先ほど書き切れなかったので、支え愛・ほっとステーションの荏原第一とか何とかと、そこをもう少し、もう１回確認をさせていただいて、全部のステーションではなさそうなので、ここ、どのような考え方で、そのような配置にしたのかの、そこだけ確認させてください。","respondent":"樫村高齢者地域支援課長","answer":"この考え方ですが、先ほど申し上げたとおり、今回効果検証も含めての配備ですので、まずは高齢者の方が多く訪れる支え愛・ほっとステーションということで、こちらの６か所に配備を予定しています。","id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"介護支援専門員の件なのですけれども、こちら、区内介護事業所が所属する介護支援専門員というようになっておりますが、現在のところ、どこかの事業所に勤めていないようなケアマネジャー、資格を持たれている方はどうなるかということをお聞きしたいということと、あと、次は自動安否確認システムの件ですけれども、こちら、今後そのようなＡＩと一斉発信の機能を組み合わせるということなのですが、現状は。","respondent":"菅野高齢者福祉課長、東野福祉計画課長、樫村高齢者地域支援課長","answer":"今回のこの事業の目的が、ケアマネジャーの人材確保、定着を促進することを目的としているため、補助対象を事業者というところで限定をしています。福祉部といたしましては、土砂災害警戒区域にいる方で、避難が必要な避難行動要支援者の方につきましては、直接連絡を取るなどしています。その一方で、こちらは少し重度の難聴の方だったということなのですが。","id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それぞれありがとうあります。イヤホンの件、そして安否確認の件は承知しました。ごめんなさい、介護支援専門員の件なのですけれども、ちょっと要望のような形になってしまいますが、やはりケアマネジャーの人材確保という、定着を狙っているというところで、そういった資格は持っているけれども使っていないという方も当然、そのような方の掘り起こしというものも大事になってくると思います。たしか募集が。","respondent":"菅野高齢者福祉課長","answer":"東京都のスキームと、今回は準拠をさせていただきまして、そこに４分の１を上乗せする形で補助を始めさせていただきましたが、委員ご指摘のようなお話も今後注視させていただきながら、事業の在り方は検証していきたいと思います。","id":"exchange-068"},{"speaker":"ひがし委員","kind":"確認","question":"１点、加齢性難聴のサポート用イヤホンについて、ちょっと確認させてください。","respondent":"樫村高齢者地域支援課長","answer":"そういった中で、この軟骨伝導補聴器の存在を、他区等で導入しているとか、城南信用金庫で導入しているという事例を聞きまして、検討を始めたといったところです。","id":"exchange-069"},{"speaker":"ひがし委員","kind":"質問","question":"今の質問、ほかにも骨伝導イヤホンといって、軟骨でなくて、もう１個別のパターンなのですけれども、というようなものもある中で、多分値段もそれほど変わらないと思うのですが、この軟骨の、しかもコードがつながっているもので、少し値段は上がるかもしれないのですけれども、コードなしで耳にかけるだけなどのほうが、衛生面的にも使用しやすいのかななどということも少し思ったりしたのですが。","respondent":"樫村高齢者地域支援課長","answer":"貼り付けるというか、軟骨のところに当てるだけで音が振動して聞こえやすいというところと、あと中にまで、耳の中にまでイヤホンを入れる必要がないので、衛生的だというように、これ一般的に言われているところで、軟骨伝導のほうを選択したといった経緯です。","id":"exchange-070"},{"speaker":"ひがし委員","kind":"質問・要望","question":"多分骨伝導のものも耳の中に入れないで、ここにかけるだけでいいというような感じなので、使用感的には一緒か、むしろいいところもあるのかなとは少し思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"１点だけ。質問するのやめようと思っていたのですけれども、ケアマネジャーのところなのですが、これ東京都がこのような形でやって、上乗せでいいのだけれども、せっかく品川区はケアマネジャーはいい組織ができていますよね、ある程度。そうするとこれ、ケアマネジャーが不足していたとしても、やることの内容によっては、非常にこれならいいよという人も復活してくれるかもしれないではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/132976?Template=document&Id=6819#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":58356,"voices":217}},{"id":"r06-20240924-8","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"建設委員会","time":"午前１０時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を93件抜き出しています。","topics":[{"id":"topic-01","title":"第７８号議案品川区空き家等の適正管理等に関する条例の一部を改正する条例","agenda":"第７８号議案品川区空き家等の適正管理等に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認をさせていただきたいと思うのですけれども、資料のところで用語の定義が、法にのっとって変えられるということで、特定非空家等というところの定義もされていますが、そこのところに、法の規定を準用という記載がありますが、空家法にはこの定義がないと思うのですが、この準用というのはどういうことなのか、伺いたいと思います。","respondent":"川原住宅課長","answer":"３点ご質問をいただきましたので、順にご説明をいたします。１点目の非空き家に関して、法の準用とはどういうことかというご質問です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"緊急安全措置というのが、今回新たに追加されると思うのですけれども、これは区独自で規定するというものなのかどうかということと、これが、先ほども危険が及ぶ場合というようなことでおっしゃっておりましたけれども、もし具体的な事例などありましたら伺いたいのと、それと併せてということになりますが、最小限の措置というものがどの程度のことなのかというところで伺いたいと思います。","respondent":"川原住宅課長","answer":"現状、命令措置を下しているところは現在１件家屋があるのですけれども、これは特定非空家等ではなくて、特定空家等として適用しているのですが、ただ特定非空家等、居住家屋に関しては、特に命令等を行う場合には非常に判断についても住宅課のみではなくて関係各課。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のところはそうすると、特定空家等については、分からない。すみません、もう一度、もし分かりやすく説明できたら伺えたらと思います。委員のところは、女性メンバーが少なかったということなので、それは女性の視点というのはいろいろなところで重要なことだと思いますので、ぜひそうしたところで女性の視点も入れていっていただきたいと思います。取りあえず、その前のところを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"後ほどご説明いただければと思います。実際、品川区内でどういう状況になっているのかというところをお聞きしたいのですけれども、この特定空家等というものと管理不全空家等というものを新たにつくられますが、これはまだ指定はないと思うので、今後の見込みですか。特定非空家等の現在の件数を伺いたいと思います。そこのところを伺いたいと思います。","respondent":"川原住宅課長","answer":"状況としましては、８月末現在の状況です。空き家として、こちらで区が把握している戸数は、全部で５４０戸弱あります。そのうち、いわゆる適正管理ではない、不適正な状況にある空き家というところでは、１３３戸。そして、居住家屋、いわゆる非空家等。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"今回の条例、決まればですけれども、改正に伴って計画も変更するのかというところでもお聞きしたので伺いたいのと、あと、今の数字でいきますと、不適正に管理されている１３３戸が特定空家等ということでよろしいですか。管理不全空家等のほうが、１３３戸ということですかね。というものが何件あるのかというところでも伺いたいと思います。","respondent":"川原住宅課長","answer":"もう一つ計画の策定についても、現在はこちらは令和６年３月に中間見直しを立てたような形で、もともと計画自体は平成３１年という形で少し古いものとなっていますので、今後この計画をどういったものにするかというところは、きちんと今、検討を図っているところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。それと、特定空家等の件数が答弁なかったので、もし後で答弁できたら、分かれば伺いたいと思います。ですけれども、代執行するということになってくると、個人の財産を処分するということにもなりますので、そうした所有者への働きかけもしっかりやりながら、慎重に判断をしていっていただきたいというふうに要望しておきたいと思います。","respondent":"川原住宅課長","answer":"残りの３件については、２件は現在命令の実施中です。同じ敷地内に２棟が建っているというところでは、住所上は番地が違うだけではあるのですけれども、２棟というふうにカウントしています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"空き家条例ということですけれども、先ほどの質疑の中でも５４０戸の空き家を把握していて、管理不全状態にある空き家が１３３戸。ようするに区が働きかけられるようにしたという、そこの趣旨を改めてご説明いただきたいと思います。改正後、いろいろ太文字で用語ありますけれども、住んでいる人と住んでない人と両方とそれぞれあるのですか。そこをもう一度整理してご説明いただけたらと思います。","respondent":"川原住宅課長","answer":"区としても、管理不全空家等として認定をすることで、特定空家等になるものを未然に防ぐ防止策というところでは、より対応を強化していくべきものであるというふうに考えてあります。こちらも積極的に実施をしていきたいというふうに考えてあります。そして２点目。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"相続の問題でどうアプローチできるのかとおっしゃる方がいるかもしれませんけれども、単純に法律的な手続や、また弁護士への相談の場所や窓口が分からなかったり、また住んでいる方も、体の調子が悪かったり、必要な医療が処方されていなかったり、そういう場合も見受けられますので、ぜひ法律的なアプローチ、福祉的なアプローチ、そういう専門部隊も組み立てながら対応していくということが。","respondent":"川原住宅課長","answer":"実際に住宅課の空き家の担当の職員だけでは太刀打ちできないケースも、人の支援というところが大きくございまして、実際に高齢者福祉課のワーカーであるとか、あとは在宅介護支援センターの職員、ケアマネジャー、もしくは、あとは場合によっては保健センターの保健師も同行して。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"現状でもケアマネジャーや保健師の方々が一緒に同行して対応するというお話がありましたけれども、この空き家条例の中に、そういうその支援の仕組みというのが位置づいているのか、伺いたいと思うのです。いずれにしてもこの分野をしっかり強化していくことが必要だと思うのですが、最後にいかがでしょうか。","respondent":"川原住宅課長","answer":"１軒１軒、特に空き家ではない居住家屋についての支援というところでは、この審議会でではなく、日々の日常のやり取りの中で行うというところが大きなところですが、今後、重層的支援会議等でも、共有できる部分は事例として挙げていきたいというふうにも考えます。","id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。私からは１点確認なのですけれども、別紙２の９ページ、第１２条の２のところなのですが、「特定非空家等の所有者等の負担において」とあるのですが、こちらは「等」とついているのですが、所有者以外にどういった方を想定されているのか教えてください。","respondent":"川原住宅課長","answer":"所有者においては、個人の所有者でなく、ケースは少ないのですけれども、法人の所有というところも考えられます。法人であったりとか、管理会社であったりとかというところも含めまして、条例に「等」というふうに記載をしています。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"だからこの辺りはどういうところで判断なのかなというのは、まさに同時につくっているところの部分なのでしょう。それが所有者等になく、事前になく、区でできるようにというのが今回のところなので、例えばそういったことがご相談ベースでも上がってきたときに、先ほどのフローとしては、どこでどう判断してというところもあるのですけれども、ここのところを教えてください。","respondent":"川原住宅課長","answer":"詳しいところはご説明があれなのですけれども、隣家がご自分の敷地外に枝が伸びてしまってきた場合、今までは民法改正前は本人の所有者の責務というところが重要視されていましたので、所有者に許可を得ないと切ることもできなかったのですが、ここは民法の改定というところでは。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"民法にのっとってやった場合です。だけれども、この緊急安全措置の場合は区ができるわけですよね。所有者に区が求めるわけだから、被害を被っているほうは、別に特段そこの手間というのは、そこは一旦流れとしてはないのかなとか思ったりするのですが、この辺は何に基づいてやるのかというところが気になりましたので、その辺の整理を教えていただければと思います。","respondent":"川原住宅課長","answer":"緊急安全措置についてのご質問です。今後この取扱いについては、改めて規則であるとか、ガイドライン判断基準を設けてから、全般を見て、また他区の状況であるとか、都や国の判断基準に応じて、区のほうも検討していきたいというふうに考えてあります。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"そこはそういう竹やぶのこととかも含めてなのですけれども、ぜひそういったことが解消されるような形で検討をいただきたいなと思います。単純に若い世代だから、１つ席を設けてそれで事足りるということではないわけですけれども、せっかく１６人以内ということで拡大をしたわけですから、そういった部分での検討もぜひお願いしたいなと思います。","respondent":"川原住宅課長","answer":"先ほど、のだて委員から質問をいただきまして、答弁ができなかった部分を改めてご説明をさせていただきたいと思います。なぜ特定非空家等にのみ行政手続法の規定を適用しないという規定があるのかというご質問をいただいていたかと思います。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"部屋の中だけではなく、部屋の前とか廊下とかよく洗濯機が置いてある場所の周りだとか、近隣住民や管理組合、管理会社もいろいろ相談をするけれども、なかなか解決できないというお話をたまに伺いますので、今回の条例は条例で戸建て住宅というのは分かりましたが、そういうマンションとかアパートについては、区はどんなふうに現状考えていらっしゃるのか。そこだけ一言お伺いしたいです。","respondent":"川原住宅課長","answer":"現在もそこについては、空き家の担当でも関与はしているのですけれども、福祉が関与してくるケースが非常に多いですので、福祉職等の職員と併せて現場対応というふうにも行っているところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"未然に防ぐ対応を強化していくということで、賛成したいと思います。ただ、現条例にはこの福祉の対応の部分については記載がないというところで、現状いろいろ対応はしているものの、ぜひ条例上根拠を持ったほうが問題の解決がさらに進んでいくのではないかなと思いますので、そこは意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"第７５号議案令和６年度品川区一般会計補正予算（歳出等 建設委員会所管分）","agenda":"第７５号議案令和６年度品川区一般会計補正予算（歳出等 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"南大井の旧水路についてなのですけれども、今回調査をして、いろいろ水路などがあるということが分かったということで、浸水した原因はここにあるのかどうかということと、あと、今後ほかの調査もしていくということなのですが、ほかの管もつながっているということになると、そこからも浸水などあるのかと思うのですが。","respondent":"森道路課長、大友公園課長、北原河川下水道課長","answer":"この間も大崎のほうでも浸水被害がございましたけれども、そういった中でそれぞれ下水道管の改修であったり、マンホール蓋の取替えであったりについて。その他の変更の内容と生じた理由等々につきましてなのですけれども、水道管について水道管理者との施工協議を実施した結果なのですが。今後増額変更する際には、もちろん我々としても積算をし直しますので、きちんと精査するとともに、恐らく５％を超えてくるというところもございまして。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、あと備蓄の物資購入のところで、今回５つの物資が新たに購入されるということで、今後の運用の仕方というのですか。実際この女性用下着などは１万５,０００着というところで、実際足りるのかどうかというところも分からないのですけれども、区のお考えを伺いたいと思います。このローリングストック、今回の備蓄でもできるのか分かりませんけれども、そこのお考えを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"こういう機械物ですけれども、こういったものに関しましては、特に有効期限が設定されているものではございませんが、機械物ということで、恐らく１０年ほどで使えなくなることも考えられますので、５年ぐらいを一つのめどとして、有効活用を図っていくなど、今検討しています。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、この女性の安全安心のところでは、ほかのこの間の被災地の中では、夜中に知らない男性が隣に寝ていて体を触られたというようなこともありますので、そういうことがずっと報告されているということで、こうした様々な手だても必要だと思いますけれども、やはり女性の専用スペースですとか、間仕切りなどの配置ができるようにしていただきたいと思いますが、最後に伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"そういった運用も含めて検討しています。そういったところを含めて、女性の方が安全に安心して避難生活が送れるような体制を整えていきたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ補正の説明ありがとうございました。その中で、南大井旧水路安全対策と、今議論のあった防災対策について、少し伺いたいと思います。南大井給水路安全対策ですけれども、令和５年６月２日に浸水被害が発生したとご説明がありましたが、改めてどういう被害が発生したのか、概要を伺いたいと思います。至極当然のことだと思いますけれども、そこについてもご答弁いただきたいと思います。","respondent":"森道路課長","answer":"引き続き浸水につきましては、下水道局と話をしながら、昨今増えておりますゲリラ豪雨にもどういうふうに対応していくかということも含めて、協議を進めてまいりたいと考えています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"改めて当時の浸水被害を伺いましたけれども、課長からも答弁あったとおり、浸水被害とかゲリラ豪雨対応、ますます強めていかなきゃいけないな。そのためには、雨が降ったときには水が上がっている。その情報をしっかり品川区は把握することが必要だと思います。そうした基本的な対応をまずしっかりしていくことが必要かなと思うのですけれども、いかがでしょうか。","respondent":"森道路課長","answer":"そういった部分を踏まえて、しっかりとその原因を調査していくということは、道路課といいますか、防災まちづくり部と下水道局のほうで情報を密にしながらやっていければなと考えているところです。これからも引き続き進めていきたいと思います。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのですけれども、台風や風水害、大きな台風が東京に向かっていると、品川に向かっているというときに、自主避難施設が開設されたり、また、被害が規模の予測によっては、避難場所が開設されて、お年寄りなどの避難の呼びかけがされたりするわけですが、こうした避難施設避難場所は、区の職員が開設するということになっておりますが、例えば今回の内容の備蓄について、また様々この間追加の備蓄や。","respondent":"羽鳥防災体制整備担当課長","answer":"そのような動きの延長ですけれども、このような配慮が必要な方の物資につきましても、各避難所の倉庫に一定数を備蓄しておいて、職員が対応する際にもすぐ用意できるような体制を取っていきたいと考えております。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"それだけに、今後は開設をした後の運営を整えていくことが必要だと思うのですけれども、例えば、避難された方々に何を提供するかというだけではなくて、自主避難施設の中での避難者同士の交流というのですか。コミュニケーションというのですか。などなど、今後のマニュアルの見直しについて、どういうスケジュール感や問題意識を持っているのかを改めて伺いたいと思います。","respondent":"平原防災課長","answer":"それを踏まえまして、地域でその内容の検証と、１２月の区内防災訓練などで確認などをしていただいて、その後に３月までに標準版としてのマニュアルという形で整備して、改めてまた地域にお示しできればというスケジュール感覚で現在進めさせていただいているところです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひそのスケジュールで進めていただいて、また上がってきた意見も反映していただきたいと思います。要するに、区が設置する避難所。備蓄といい、運営といい、それが１つのお手本になるような形になると、住民の皆さんも非常に力になるかと思うのですけれども、最後に一言お願いしたいと思います。","respondent":"平原防災課長","answer":"自主避難施設と避難場所、風水害時の開設についてですけれども、自主避難施設につきましては、計画的に開いていくこともありますので、様々なやり方があるかなと思うのですが、避難場所については、実際に危険な事象が接近しているということもございまして。","id":"exchange-023"},{"speaker":"横山委員","kind":"確認","question":"ご説明ありがとうございました。１点１点確認させていただければと思います。防犯ブザーのお話も先ほどありましたけれども、ブザー自体は、５年くらいがめどということでお話ありましたが、電池の点検ですとかそういったところは、ローリングストックの考え方の中で、どのように行っていくのかというのを確認させてください。","respondent":"羽鳥防災体制整備担当課長","answer":"女性の下着につきましては、まだ購入する商品が確定している段階ではございませんが、見積り段階で検討しているものは、不織布のようなものになります。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"女性用の下着様々のサイズですとかあるかと思います。下水道の部分。第二戸越幹線整備工事の部分なのですけれども、こちらも都の建設局との協議で、川の流れを阻害しない方法、手法に変えていくということになったという話なのですが、こちらの都の建設局との協議の時期について確認させていただければと思います。","respondent":"大友公園課長、北原河川下水道課長","answer":"こちら、追加で必要となったというところにおきましては、インフラスライドにつきましては請求時点という形で、第１回の変更後に請求がありましたので、こちら４月の時点で判明したものです。都の建設局との協議時期ですけれども、まず、この工事を出す前の段階で、そこに吐口を設置するという協議を行っておりまして、その後工事を行うまでに、どうやって施工していくかという協議を順次進めてきているところでして。","id":"exchange-025"},{"speaker":"横山委員","kind":"確認","question":"ありがとうございました。次なのですけれども、南大井旧水路安全対策についての部分なのですが、確認なのですが、こちらの旧水路が、令和５年６月２日の時点では管理されていない旧水路があったということが、この後に調査の結果分かったということなのでしょうか。この潮通し管については、管理されている部分ということなのでしょうか。こちら分からなかったので、教えてください。","respondent":"森道路課長","answer":"こちらについては、昭和２３年から昭和３７年にかけて、当該地区で戦災復興土地区画整理事業というものが行われておりまして、恐らくそのときまでに使用されていた水路なのではないかというふうに考えています。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"現在どういった状況であるのか、鉄筋が露出している状態で、現在は安全が確認されていて、今後そういった可能性が起きることを低くしていくためにそのような工事を行われるのかなというふうに、先ほどの説明をお聞きしていて思ったのですけれども、その辺り確認させていただきたいというところと、あとそのモルタルがどのくらいの耐用年数であるとか、あとメンテナンスを今後都のほうで行うのか。","respondent":"森道路課長","answer":"国土交通省のほうでも、一部空洞調査とかもされたりして、対応は順次していくというところはこちらとしても認識しているのですけれども、実際に令和８年度から行うモルタルの充填につきましても、順次情報を共有しながら進めていければと思っています。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"現状のほう、説明をいただきまして、ありがとうございました。それぞれ関係する国土交通省であったりですとか学校であったりですとかその他関係機関と、ぜひ協議のほうを進めていただいて、安全、そして安心に、なるべく迅速に進めていただきたいというふうに思いますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"澤田委員","kind":"質問","question":"私からは、子どもや女性視点による避難所の生活環境改善について、少し質問させていただければと考えています。この防災課の女性職員で構成されたプロジェクトチームというのができたということは大変うれしいなと思っておりまして、この職員の構成というのは、年齢なのですけれども、若い方の意見が今回は多いと思うのですが、どのような感じになっているのかなというのをまず教えていただけますでしょうか。","respondent":"平原防災課長","answer":"防災課の女性職員のプロジェクトチームですが、こちら令和４年度からですけれども、係長１名の以外は全て係員ですので、比較的若い年齢層によって構成されております。","id":"exchange-029"},{"speaker":"澤田委員","kind":"質問","question":"もう既にあったら申し訳ないのですけれども、例えば尿漏れパッドというのが結構中高年の女性で必要だというお話をよく伺っていて、その辺も検討していただければと思います。いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"ただいま委員からご提案いただきました尿漏れパッドなども含めて、様々な年代層の方のご意見を参考にしながら、引き続き備蓄物資の充実に努めてまいりたいというふうに考えてあります。","id":"exchange-030"},{"speaker":"澤田委員","kind":"質問","question":"続きましては、先ほど下着についてなのですけれども、不織布のようなものを、今のところはまだ決定ではないが検討しているということでお伺いしたと思うのですが、例えば肌の弱い方もいらっしゃって、コットンでないとかぶれてしまってという方もいらっしゃると思うので、不織布だけということではなくて、洗濯の面でいろいろ課題はあるかとは思いますが。","respondent":"羽鳥防災体制整備担当課長","answer":"先ほど横山委員からもあったとおり、様々なサイズに対応できるようなものを検討しています。今後、メーカーのほうでもよりよい商品が出てくると思いますので、そういったものは、順次情報をキャッチしながら対策を進めてまいりたいというふうに考えてあります。","id":"exchange-031"},{"speaker":"澤田委員","kind":"質問・要望","question":"細かくなってしまって大変申し訳ないのですけれども、女性の防災リーダーみたいなものの育成にもぜひ力を入れていただきたいなと思うことと、あとは、避難所では赤ちゃんを抱えているお母さんなど、赤ちゃんの泣き声がすごいストレスになってしまうといいますか、周りに迷惑をかけているのではないかとか気になって苦しんでしまったりですとか。","respondent":"平原防災課長","answer":"ホテルにつきましては、コロナ禍のときに、ホテルとの提携を再度見直しまして、もう一度その実効性を確認しています。そういったところも活用しながら、より安心できる避難所生活を送ることができるような環境を整えてまいりたいと考えています。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"備蓄のほうですけれども、これはローリングストックということでお話がありましたが、今回はそれぞれ大きくは５項目をまとめて契約していくという形だと思うのですが、物品によってそれぞれローリングするタイミングが、先ほどのご説明も含めてもあろうかと思うのですが、当然今後ほかの備蓄物資と合わせてというところで、頭とお尻を合わせてとかあると思うのですが。","respondent":"羽鳥防災体制整備担当課長","answer":"そのほか、おむつ処理袋、授乳服、授乳ケープ、あと防犯ブザーにつきましては、特に期限は設定がありませんので、今回必要数を一括で購入するという形になりますけれども、また今後新しい商品などが出てきたときの見直しなども含めて。","id":"exchange-033"},{"speaker":"つる委員","kind":"確認","question":"質問させていただいた趣旨と答弁が全然違ったので、後でまた個別に伺います。南大井の旧水路のほうなのですが、先ほど横山委員が質疑されて非常に大事かなと思ったのと、過去のいろいろな質疑を確認する中では、品川区として把握しているこの旧水路。あれは別の理由かと思うのですが、そうしたことも含めて、その辺りについても併せて教えてください。","respondent":"森道路課長","answer":"その結果、空洞らしきものが見つかれば、その情報を全て下水道局にまずは提供して、下水道局のほうでいろいろ管を見て、管が割れているとか割れていないとかという話を調査していただいて、その結果、対応が必要だというものについては対策を進めていくということになっています。","id":"exchange-034"},{"speaker":"つる委員","kind":"確認","question":"品川用水とかかつてのそういう時代の上水道も当然あると思うのですけれども、この戦災復興の区画とかでやるときについては、下水となってくると、今で言えば東京都の下水道局が本来は調査とか確認とかやっていくべきものなのかとか、区がやるのかとか、先ほど国土交通省と話とかありましたが、その責任の所在というものはどうなのかなと、今後今回の案件をきっかけに。","respondent":"森道路課長","answer":"戦災復興のときに水路が造られたというのではなくて、その前からあっただろうという認識です。","id":"exchange-035"},{"speaker":"つる委員","kind":"確認","question":"ありがとうございました。だから当然区で管理していく、生活に密着しているので、何かあったときには全て初動があると思うのですけれども、お金の問題で、そういうものは造ったのがそもそも所在を確認していくという作業の立ち上がりも、先ほど質疑で例えば国土交通省とか土木関係を所管する国とか広域とか品川区となってきたときに、そこのお金のかけ方とか、まず調査しようよ。お願いします。","respondent":"森道路課長、高梨都市計画課長","answer":"あるいはそれぞれ分断して、それぞれの管理者が管理していくのかという話は、国とも確認をしながら進めていきたいというふうに思っております。区内で確認されている戦災復興の土地区画整理事業は、全４か所でございまして、今話題となっています南大井のほかに大井町の周辺、それと大井地区、それと五反田駅の周辺の４か所で実施されていたというものです。","id":"exchange-036"}]},{"id":"topic-03","title":"令和６年陳情第３７号南品川５丁目のマンション建設に関する陳情","agenda":"令和６年陳情第３７号南品川５丁目のマンション建設に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"それと、今のご説明の中でも建築確認済証が既に８月２８日に出ているということで、これはどういった変更なのかというところを伺いたいと思います。それと、今回擁壁があるということで、陳情の中でも戦前からあったというようなことも書かれておりますけれども、区のほうでは、確認申請とかがあると思うので、いつ作られたのかというのが分かれば、伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"戸数については、計画上、分譲予定のマンションで５４戸、共同住宅という形になっております。平面図によりますと、主に単身者を想定した造りになっているというふうに考えられます。既存の擁壁がいつ頃造られたかというところです。かなり古い擁壁ですので、建築課には資料がない状態です。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"この陳情の中に、区のほうで擁壁の調査を行ったということが書かれておりますけれども、実際行ったかどうかということも含めて、その結果がどうだったのか、安全性、耐久性というのはしっかり保たれているのか、そこを伺いたいと思います。","respondent":"森建築課長","answer":"区で実施した調査についてですけれども、過去建築課のほうで崖・擁壁の実態基礎調査ということで、平成２７年度、２８年度の２か年を要しまして、調査箇所数は約２,２００か所、区内全域の崖・擁壁を調査しております。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで今回擁壁を撤去するということで、住民の方から資料なども頂いておりまして、擁壁部分、約１１ｍ撤去するということで、なぜ撤去しなければならないのかという理由を伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"その後、令和６年６月、あと８月に２回、９月も１０日に１回来ておられまして、その都度ご説明をさせていただきながら、また、陳情者の皆様からの声というのは速やかに建築主等に伝えているという状況です。それから類推いたしますと、どうやら新しく計画される共同住宅の避難経路として使うために、擁壁を切り取って、北側からも避難が可能な計画にしているのだろうということは考えられます。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"この陳情の中にも、私道を使わないでほしいということで、管理組合のほうでも決定されたと書かれております。そうした中で強引に計画を進めていくということは、すべきではないというふうに思うのですけれども、区としてはどのように考えているのか伺いたいと思います。実際そこのところは、区としてはどのように認識されているのか伺いたいと思います。","respondent":"森建築課長","answer":"通る権利があるかどうかについては、同意がないと通ることは不可能なのですけれども、避難等の緊急事態については話が別になってまいりまして、建築基準法上の道路という扱いになっておりますので、避難で使えないということはないだろうというふうには考えてあります。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"実際擁壁を壊していくとなると、工事の面でも足場とかを私道側のほうに造らなければいけないというふうに思うのですけれども、私道を使わずに工事をするということが可能なのかどうかも伺いたいと思います。","respondent":"森建築課長","answer":"私道を使わないで工事が可能かどうかというところは、詳しい資料はないのであれですけれども、どうやら予定では敷地の内側、上のほうから掘って造っていくような計画を立てている最中だということで、今、少し工事が止まっている状態で、いろいろ金額をはじき出したり。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"併せて、本来これぐらいのマンションを建てるということになれば、駐車場の附置義務があると思うのですけれども、図面を見ますと、駐車場の計画がないということで、業者のほうは造らない計画のようなのですけれども、区としてはどういった指導、助言などをしてきて、認識を持っているのかというところを伺いたいと思います。","respondent":"川原住宅課長、森建築課長","answer":"文書を用いての説明というところでは、この第３回の時点ではあったというふうに認識をしてございまして、この説明についても。〔９月２５日に「用途地域が商業地域、近接商業地域ではない第一種住居地域の共同住宅でしたので、東京都駐車場条例の適用がない」と答弁訂正あり〕そうなりますと、駐車場があった場合は、車椅子対応にする等があるのですけれども。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"擁壁の安全性については文書を出されているということですけれども、そうした中でも今回こうした陳情が出てきているということですので、具体的な説明がないということなども、科学的に説明していただきたいということで今回陳情が出ておりますけれども、そうしたことが十分行われていないということだと思いますので、しっかりと話合いをして解決していけるように。","respondent":"川原住宅課長","answer":"次回６回目以降の説明会があるかどうかというところでは、９月１８日時点においては、工事の手法についてまだ検討中ですので、区民の皆様に説明できる資料ができた折には、きちんと説明をするようにというところは、区としても引き続き訴えていきたいというふうに考えてあります。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"３点目、紛争等予防条例のことに関してですけれども、先ほど区から、引き続き丁寧に説明するようにと業者に働きかけているという趣旨の説明があったかと思いますけれども、少なからずこれだけの方々が論理的に科学的に何も説明されていないと訴えているわけですから、良好な近隣関係をつくることに努めなさいと建築主に求めているこの条例の趣旨には反する状態が生まれている。","respondent":"森建築課長、川原住宅課長","answer":"私から最初の２点についてお答えいたします。確認審査を行ったところは区か、民間かというところで、民間の確認検査機関で行っております。近隣住民の皆様、陳情者の皆様への説明というところでは、先ほど区条例第５条の説明にもありましたように、周辺の生活環境に及ぼす影響に十分配慮するということ。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"建築確認審査は民間の確認審査だということです。擁壁についても、敷地内については審査の対象だということで、民間の確認審査機関は審査の上、安全だと述べているということですけれども、さっき伺ったのは、何を根拠に確認審査では安全だと主張しているのか、そこをご説明いただきたいと思います。民間の確認審査が安全だというのであれば、何を根拠に安全だというふうに品川区に説明をしているのか。","respondent":"森建築課長、川原住宅課長","answer":"擁壁の安全性の根拠等について、区で把握しているかですけれども、確認済証が民間検査機関から交付されたときに、区の建築課に送られてくるのが概要書というものですので、詳しい内容までは把握していない状況です。建築の紛争予防条例に基づいて区ができる対応というところでは、現時点においては建築主へ区民の皆様の要望を伝えるというところにとどまる部分ですので、今後お話の部分では。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"今品川区に、建築確認審査において、安全がどう担保されているのかという質問をしたら、詳しくは把握していないという説明でした。少なからず民間の確認審査が安全だと太鼓判を押しているのだから、その根拠を示しなさいと。それだけに、業者が安全だと言うのであれば、その根拠、データを住民の皆さんにしっかり示しなさいと品川区が業者に働きかけていただきたいと思うのですが、いかがでしょうか。","respondent":"川原住宅課長","answer":"第３回時に配布した説明の資料についても、分かりづらい部分があったということであれば、再度それを分かりやすく解釈したような説明があるとか、区民の皆様が必要とされるものについては、しっかりと建築主の皆様が認識していただきたいということは。","id":"exchange-046"},{"speaker":"中塚委員","kind":"確認","question":"品川区も、業者から建築確認審査が取れましたと連絡が来ているから、取れたということは安全だろうという理屈は１００歩譲ってあったとしても、業者の皆さんが安全だという根拠を区も知らないわけですよね。それだけに、改めて伺いますが、区は条例に基づいて業者に対して、安全だという根拠、具体的には科学的、論理的な根拠を住民に示して説明すべきだとなぜ業者に迫ることができないのか伺います。","respondent":"川原住宅課長","answer":"その上での建築確認済証ということの説明があったようです。そういったことも、区民の皆様に分かりやすい説明というところは引き続き対応するようにしっかりと申し上げていきたいと思います。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"事故があったらどうするのですか。確認審査を民間に任している時点で私は違うと思っているから、その話まで戻すと、今日は終わらないですからやめておきますが、たとえ確認審査が民間に移ったとはいえ、建築行政の責任はやはり品川区にあるわけですから、本来だったら住民の皆さんにも、区にも根拠を示して安全性を説明せよというのが本来のあるべき姿だと思います。ちょっとご検討いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる委員","kind":"確認","question":"いろいろ細かいところはほかの委員の質疑で確認させていただきました。それで陳情項目の「そのための」以降なのですけれども、ここに陳情項目としては、指導、援助をということであるわけですが、現状の品川区が持っている条例等の中において、ここで言うところの指導、援助というのは、陳情のことに限らず、現状でそれはできるのでしょうか、できないでしょうか。","respondent":"川原住宅課長","answer":"区が指導できる状況としては、適法ではない建築物、違法性があるものに対しては指導という形でしっかりと対応することが可能ですが、現時点の私どもの書類の確認の内容においては、適法な建築物というふうに把握していますので、引き続き区民の皆様。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問","question":"これは一般論ですけれども、伝えても聞く耳を持たないという方だったり、業者だったりというのはあったりすると思うのですが、その上で指導と伝えるという意味の違いというのを教えてください。","respondent":"川原住宅課長","answer":"説明に関しても、工事の手法についてまだ現状検討中ですので、計画の工事が決まった段階では、住民の皆様に全体への説明が必要なものは全体説明で、個別での説明が必要なものは個別の協議をする場合も中にはあるそうなのですけれども、全体での説明を希望している際には。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"これが先ほど質疑でちらっとあったようなところで、きっかけは別にして、具体的に何か行為の悪意とか、そういったことは別にしても、擁壁が崩れて何かがあった、損害を被ったという場合、今回の場合は品川区になるのですけれども、所在、責任的なことというのは何か発生するのかあるのか、対応が必要なのかどうか、これを教えてください。","respondent":"森建築課長","answer":"当該の擁壁なのですけれども、２項道路、建築基準法の道路に面しているところもありますので、そちらは区の助成等、アドバイザー派遣であったりすることが可能です。","id":"exchange-051"},{"speaker":"澤田委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。理由としましては、説明会は５回ほど行われており、丁寧に進められていること、またマンション建設は民間同士で進められていると認識しておりますが、その中でも区条例に従い、区としても様々働きかけていることなどです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問","question":"そこはしっかり、現行の中で、そういった区民の声があった場合には、区としてはできる範囲の中で事業者に対してそうした意向を伝えるということは引き続き強くやっていただいて、業者は安全性が分かるような、先ほど５回の説明の中の３回目にされたということがあるわけですけれども、聞いている側からすると、それはなかなか分からないということがあるわけですから、ここについては、区としても引き続き。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。擁壁の安全性について具体的に科学的に説明することが、住民との良好な関係をつくることにもつながりますし、区としても業者に対して助言、指導すべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"中塚委員","kind":"確認","question":"今日結論を出すか継続とすべきかということですけれども、先ほども建設委員会として現地を確認すべきだ、視察をすべきだという意見を述べさせていただきました。その結論ですけれどもちろん採択すべきだと思います。区はぜひ自らの条例にのっとって、根拠を示して説明するよう、業者に働きかけるべきだと思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"横山委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。引き続き一般の方々に分かりにくい擁壁の専門的な説明などに関するお問合せに関しましては、区民に寄り添って丁寧で分かりやすい説明を行っていただいたり、建築主への対応を求めるお声が届いている旨を迅速に建築主などに情報提供を行うなど、区として現状の把握をしながら、区民の方々のお気持ちに寄り添ったご対応をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問","question":"再開発が区内各地で様々行われておりますけれども、そうした中でどこでも聞くのが、住民が知らないうちに進められているということで、突然説明会などあって、自分の生活が壊されるということを知ることになるという状況があります。住民が知らないうちに、地権者も知らないうちに再開発が進められていくということについて、区はどのように考えているのか伺います。","respondent":"中道都市開発課長","answer":"まちづくりを考えていく中で、まず勉強会等々が開かれているです。区としましては、地区内で考えている区域内の権利者の方々には周知するよう、勉強会や準備組合の方々には伝えているところです。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"そうした状況があるからこそ、再開発をやめてほしいという陳情が品川区にも区議会にも数々挙がってくるということだというふうに思います。そこを改善していくということが１つ必要だと思いますけれども、いかがでしょうか。そうした中で都市計画審議会でも反対する方が本当に多く意見を出されたということで、住民が知らないうちにどんどん進めていくということは改善をしていくことが必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"そういった中で区がしっかりつかんでいくということが必要なのではないかと思います。準備組合が思い込んで、９割が賛同だという中で、区がそれをうのみにして都市計画手続を進めていくということになると、都市計画としては決定してしまうことになってしまいますので、そこは区としてもしっかりつかんでいくことが必要ではないかと思うのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"まちづくり、都市計画に進む前段階、まちづくりを検討する段階においても、より多くの方の参加というところは、準備組合には伝えているところで、そういった中で皆様がいかに多く、どういったまちづくりをしていきたいかというところをビラ等、またお時間の調整ができれば。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"区はつかんでいるというご説明でしたけれども、実際に今、小山３丁目は多くの方が反対の意見を挙げて、なかなか進んでいないというような状況にあると思います。準備組合の情報で、区が進めていくということになると、誤った判断にもなりかねないというふうに思うのですけれども、いかがでしょうか。それがやはり区民の生活を壊さない、あるいは守っていくということになると思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"そこにつきましては、準備組合等からの報告を基に、区としてはしっかり確認していくです。実際に都市計画の事業を進めるかどうかという判断につきましては、区としては、準備組合を設立するとき、事業認可を取得するときに、法的な根拠を基に把握をしていくです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"確認","question":"事業を進めていくかどうかというところでは、法的な確認をしていると言いますが、その確認というのは準備組合設立の事業認可ということだと思います。そうしたことをやらずに、住民の暮らし、生活を壊していくという事態が生まれているというところでは、区としても反省すべき部分があるのではないかなというふうに思うのですけれども、行政の責任としてはどのように考えているのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"一方で、準備組合が設立するときというのは、権利者の方々の同意が非常に重要になってくるところですので、そこにつきましても、また法の下にしっかりと対応しています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"都市計画決定時にも住民の同意を把握しているということですが、区独自で把握されていることがあるのか、準備組合の情報に基づいて把握していると言っているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"第一種市街地再開発事業につきましては、権利者の方々が事業者となりますので、まずは事業者の方々からの報告ということで都市計画決定のときの同意というのは確認をしております。準備組合の設立のときには、同意書などの資料を基に行政として把握しています。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としてもそうしたところをしっかりつかんでいかなければ、区民の生活は守れないというふうに思いますので、これは強く要望しておきたいと思います。住民の皆さんは、このまま住み続けたいということも強い願いでありますし、そうした中で再開発に巻き込まれていくという状況ですので、こうした再開発はやめていくべきだというふうに思いますけれども、伺います。","respondent":"中道都市開発課長","answer":"ビジョンという形でもまちづくりの方向性というものをより具体的に示しています。そうしたところも踏まえまして、地域の方々が検討して進めているこういった再開発を含めたまちづくりというものは、区としては応援、支援をしていきたいというふうに考えております。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に確認させていただきたいと思うのですけれども、住民の意向を把握しないというところでは、一定把握しているという話もありますけれども、国のほうで、過度に把握をするのは慎重に行うべきだということが、何度も通知が出されているそうなのですけれども、そうしたことによって区としても把握をある程度しかしないというところがあるのかどうか伺います。","respondent":"中道都市開発課長","answer":"区といたしましては、そういった同意書、いわゆる都市再開法第２０条に基づく同意書といったものを、都市計画決定時には求めてはおりませんが、地域の方々で進めていくまちづくりというところでは、都市計画決定においても。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"質疑したいと思います。品川区が現在計画を検討している全ての再開発の中止を求める陳情ということで、これ以上の再開発は必要ないと思います。もう一つ、再開発事業は民意の下に実行されているのか、区の調査を求めますという陳情ですけれども、合意形成の経過が不透明だというのは全くそのとおりだと思います。もう少し具体的に、機運とは何か、高まりとは何か、丁寧にご説明いただきたいと思います。","respondent":"中道都市開発課長","answer":"地域の方々が勉強会等を設立した際には、区のほうに、この地域でまちづくりを研究していきたい、また検討していきたいという声をいただきます。区のほうに来られるそういった勉強会の団体もいらっしゃいます。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"肩書というのか、どういう立場の方なのか伺いたいと思います。高まりというのであれば、１０人中１人ぐらいでは高まりとは感じないですよね。せめて半分か、それ以上か大多数でないと、高まっているという、理屈の世界でもそうなるかと思うのですけれども、機運とは何か、高まりとは何かをもうちょっと、あと先ほどの地域代表者というのはどういう方なのか、ご説明いただきたいと思います。","respondent":"中道都市開発課長","answer":"一方で、一定程度の人数と、明確な基準というのはないですけれども、一定程度の資料を提出していただいたり、会合があったといった形で、何かしら報告があったときに参加人数等で、地域自らまちづくりといったものを考えていただいているというところを。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問","question":"よく分かりました。結局区の機運の高まりとは、何にも根拠がないのですよね。１人、２人は高まりとは言わない。さすがにそこは、３人以上は高まりになってしまうのですかね。何人か集まっております。では例えば、超高層のタワーマンションではないまちづくりを進めたいという会が、品川区にこういう勉強会、協議会を開きたいと相談に来たら、どうぞ、どうぞと言うのか伺いたい。そこも伺いたいと思います。","respondent":"高梨都市計画課長","answer":"最初にご質問にありました超高層でない、再開発でないまちづくりがしたいという相談があった場合に、相談に乗るのか、また、まちづくりの補助金が出るのかといったところについては、当然相談に乗らせていただきますし。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問","question":"再開発推進派も出すけれども、再開発中止派にも出すと、要綱上は、賛成とか反対とかではなくて、自主的なまちづくりについての支援という位置づけですから、今の説明になるのかなと思います。質問ですけれども、都市計画法に基づいて、何分の１以上の地権者の合意があれば、地権者全員の土地、建物の権利を準備組合、本組合に帰属することができるのか伺います。","respondent":"中道都市開発課長","answer":"都市再開発法の第１４条の中に同意について記載があります。土地所有者または借地権者の３分の２以上、または宅地の総面積の、同意の部分で言えば、宅地の面積または借地の面積の３分の以上の同意があれば、組合が設立できるです。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"課長の答弁は、法律の趣旨を要約した中身だと思いますけれども、３分の２以上があれば組合が設立できるというその意味は、３分の２以上の同意があれば、３分の１の方々の土地、建物の権利を奪うことができるということなのです。でも本人からすれば奪われるということなのです。ぜひ訂正していただきたいと思いますが、いかがでしょうか。これは法律の事実ですから、そういう表現に変えるべきではないですか。","respondent":"中道都市開発課長","answer":"都市再開発法の第２０条に組合員といった記載があります。施行地区内の宅地については、所有権または借地権を有する者は、全てその組合の組合員とするというような法の決まりがありますので、それに倣って記載したです。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"そろそろ終わりにしますけれども、第２０条の全て組合員とするというのも、別に組合になりたくなくてもされてしまうという意味なのです。再開発のことであまり細かく、何か分かりづらいなという方もいるかもしれないのだけれども、組合員とするというのはそういう意味なのです。だから再開発はやめてほしいという方々は、奪われた、立ち退きさせられたというふうにおっしゃるのです。最後に伺います。","respondent":"中道都市開発課長","answer":"今、第１４条の中の同意書で、再開発に同意しない方につきましても、第２０条の中で組合が設立できれば組合員になります。","id":"exchange-070"},{"speaker":"中塚委員","kind":"意見","question":"強制的なのです。だから追い出されるという声が挙がるのです。こんな再開発はこれ以上進めるべきではないと、陳情者さんがおっしゃるのはそのとおりだと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"つる委員","kind":"質問・要望","question":"本日結論を出すで、不採択です。これまで再開発について様々な質疑がありましたけれども、法令に基づいて粛々と対応していただきたい。こうした様々なお声については、引き続きしっかりと寄り添いながらの対応を求めたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。再開発準備組合から情報が出されずに、デベロッパーが事務局として主導権を握ってきました。こうした再開発はやめるべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問・要望","question":"区も認めたとおり、区は皆さんかどうかの基準も持っていないのです。１人か２人は違うという発言はありました。でも、皆さんがそう思っているかどうかの基準はないとおっしゃっているのです。では誰が求めているのだというところですけれども、デベロッパーや大手ゼネコンが求めているのです。いかに住民発意でないかということは、そこにも１つ現れているかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。先ほども言いましたけれども、準備組合任せで、住民の生活を壊しているということについて、区としてそういったことがないように調査し、改善すべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"}]},{"id":"topic-04","title":"令和６年陳情第４３号、品川区東大井５丁目Ｃ地区再開発に反対する陳情","agenda":"令和６年陳情第４３号、品川区東大井５丁目Ｃ地区再開発に反対する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この陳情にあるとおり、陳情者の方は９０年以上住んでいらっしゃる。その半分以上が再開発に翻弄されてきたということで、こうした方が再開発によって追い出されようとしている。こうした方の気持ちを区はどのように受け止めているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"この地域の中では、様々な形で意見交換が行われているというところは聞いておりますが、現在そういった動きがないです。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"現在動きがないということで、そうすると今は再開発はなくなっているということでよいのか、伺います。","respondent":"中道都市開発課長","answer":"将来どういった形でまた話合いが行われるのかというところは、もちろん区は把握しておりませんけれども、なくなったとか、そういうことではなくて、現在は地域の方々は、今のＪＲの開発の来街者の動向などを見据えながら、今後のまちづくりを考えていきたいと。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"勉強会が開催されていないということですから、機運が高まっていない、下がっているということでよいのでしょうか。伺いたいと思います。これはどういうことなのか伺いたいのと、先ほど９０年以上住んできた方の気持ちをどう受け止めているのかということも伺ったので、ご答弁いただければと思います。","respondent":"中道都市開発課長","answer":"９０歳以上の高齢者の方の考えですけれども、まちづくりをする中では様々な意見があるというのはもちろん区は認識していますが、やはり皆様できちんと話し合っていただいて、まちをどういうふうにしていきたいかといった形で。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"雰囲気づくりについては、ノスタルジックな雰囲気と、多様な方が来られる雰囲気というのは両立ができるのではないかなと思いますので、そこは対立させないようにしていただきたいと思いますけれども、実際この間、住民の方、特に陳情者の方は人生の半分以上が再開発で翻弄されてきたということを言われているわけですので。","respondent":"中道都市開発課長","answer":"東小路を含むＣ地区ですけれども、様々な声があるということは認識しています。一方で、駅前で、多くの方が来られるというところで、防災上の不安という声も多く挙がっているということも、区は認識しております。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の方で考えていただきたいということなのですが、本当にこれが住民の方の土地を使って、再開発事業者が、主にデベロッパーだと思いますけれども、利益を上げていくという事業になりますので、その下で住民が生活を壊されていくということで、こうしたＣ地区での再開発はやめるべきだというふうに、これは強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"Ｃ地区の再開発に反対する陳情ということで、今もやり取りがありました。何でみんなの税金を補助金として投入する事業として、Ｃ地区は、先ほどお話があったように、今は勉強会等の活動をしていないというお話があったので、そこはそことして、ご説明があったことは私も聞きましたけれども、大企業がもうかる再開発を何で税金を使って補助して、応援するのかが疑問なのですけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"具体的に申しますと、老朽化した建物、またはインフラ整備、都市の魅力の向上を図るといった形で、区としては補助金という形で支援をしています。","id":"exchange-081"},{"speaker":"中塚委員","kind":"質問・要望","question":"まちには更新が必要なのだ、そこに区は補助金を出しているのだというご説明だったと思うのです。私が聞いたのは、大企業がもうける再開発になぜ補助金を使うのか、税を使うかということを伺いました。そのことにご答弁いただきたいと思います。","respondent":"中道都市開発課長","answer":"今委員がおっしゃいます大企業がもうけるですが、それは保留床の部分をその後、民間企業が売却しての利益ですが、民間の会社の運営の中の取組になりますので、区としては、その詳細につきまして把握していないです。","id":"exchange-082"},{"speaker":"中塚委員","kind":"質問","question":"私は医療とか、介護とか、福祉に税金は使うべきだと思っています。でも、大企業がもうけることが前提になっている事業を知っていながら、何で税金を、もうけることを知っていながら、何でそんな再開発に補助金を税金として投入するのか、この点で伺いたいと思います。同時に伺いますけれども、木密地域で行われているこれらの事業は、なぜ売ることが前提だと補助金がないのか、伺いたいと思います。","respondent":"小川木密整備推進課長、中道都市開発課長","answer":"これはあくまでも営利を目的としたものは援助しないという形でやっているものです。そうした中で民間活力を使いながら、公共の福祉に資する、駅前でオープンスペースをつくっていくかといった中で進める事業です。","id":"exchange-083"},{"speaker":"中塚委員","kind":"質問","question":"今のそれぞれ説明で明らかになったと思うのですけれども、木密整備推進課でやられている事業では、そもそも会社が申請すると対象にはならないのですけれども、住民が申請しても、売ることが目的の場合は補助にならないのです。こうした地区計画やまちづくり、自主的なまちづくりへの支援、何かそういうノウハウというものは持っていないのか、伺いたいと思います。","respondent":"高梨都市計画課長","answer":"そのために、例えば、活動に関する資金でお困りというようなことであったり、いろいろと検討するために専門家の知恵を借りたい、法律的にはどうなのか、建築士の方の意見を聞きたい等々がありましたら、微力ではありますけれども。","id":"exchange-084"},{"speaker":"中塚委員","kind":"質問・要望","question":"Ｃ地区については、まずは話合いの段階だというふうにご説明がありました。話合いの段階だと言うのであれば、何でＣ地区を大井町まちづくりビジョンという上位計画の名前でしたでしょうか、Ｃ地区を拠点としてわざわざ明記するのか。今活動していない。私は削除すべきだと思いますけれども、いかがでしょうか。ぜひやめていただきたいと思いますが、いかがでしょうかということです。いかがでしょうか。","respondent":"高梨都市計画課長","answer":"ビジョンの中での位置づけにつきましては、都市開発課長からの説明でもありましたとおり、まちづくりに関して過去、地域でいろいろと検討されてきた経緯があるということで、この先どうなるかというようなところは。","id":"exchange-085"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言主張して終わります。大井町のまちづくりといい、広町のまちづくりといい、結局Ｃ地区、Ｅ地区を動かすために区が牽引しているというふうにしか私は思いません。全国各地には、ああ、全国各地は言い過ぎかな。東京２３区でも横丁を活かした長屋か、長屋を活かしたまちづくりというのも実践されているのです。ぜひＣ地区の再開発はやめていただきたいと重ねて主張して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"澤田委員","kind":"意見","question":"本日結論を出す、不採択でお願いいたします。今回の陳情にもありましたように、様々な思いも課題もあると思いますので、そのようなお気持ちに寄り添いながら、安心・安全なよりよいまちづくりを進めていくために、区は引き続き話し合いなどのサポートをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"つる委員","kind":"意見","question":"本日結論を出すで、不採択です。資料もいただきました。地権者中心に話し合っていただく段階というところで、そうした様々な意見を、まさに地域の地権者の方々を中心にしっかりと話し合っていただいて、合意形成していくことが重要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択を主張します。住民を追い出し、生活を壊す東大井５丁目Ｃ地区再開発はやめるべきと考えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということと、採択でお願いいたします。特にＣ地区については、長い時間地権者の暮らしを脅かしております。こんなゼネコンの言いなりに、従ってはいけないと思います。住民主体のまちづくりと言いますけれども、実態は異なる点も先ほど指摘させていただきました。いずれもＣ地区の再開発は進めるべきではない、やめるべきだと思いますので、採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"横山委員","kind":"意見","question":"本日結論を出すでお願いいたします。現在まちづくりのことについて、地域の方々で話し合っていく段階であるというご説明がありました。先ほどの議論を踏まえまして、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"}]},{"id":"topic-05","title":"専決処分の報告、(1)専決処分の報告","agenda":"専決処分の報告、(1)専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"清掃事務所職員による今回の事故ということで、今回は清掃車ではないのですかね。そこを伺います。","respondent":"篠田品川区清掃事務所長","answer":"清掃車ではなくて、一般の乗用車です。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"今回は乗用車ということですけれども、この間、清掃事務所の方の事故が続いているような気がします。清掃車ではないので、人員体制の強化とか、そういうことにはならないのかもしれませんが、ぜひ注意がしっかりできるように、業務が多いのであれば、人員配置していくということも含めてやっていくということが必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"篠田品川区清掃事務所長","answer":"人員数等の問題というのは特段、そういったことが原因で起きているという認識はございません。","id":"exchange-093"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/250442?Template=document&Id=6817#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":74541,"voices":247}},{"id":"r06-20240924-9","meetingId":"r06-cm09","date":"2024年9月24日","dateIso":"2024-09-24","committee":"文教委員会","time":"午前１０時００分～午後 １時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"すみません、録画もですか。録画も審議に入る前にということですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"前例どおり、審議に入る前でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"せらく委員","kind":"質問・要望","question":"これまで前例どおりとしていたのですけれども、自席からであれば、いつでも構いませんということにさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"第７９号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第７９号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"確認をさせていただきたいのですが、学校医の方々というのは、今のご説明では区の非常勤職員ということであります。令和５年２月に補償内容が改定されておりますが、そこで非常勤である学校医の方々も、前年の令和５年２月の改定に応じて国も都も改正したということなのですが、今回は同水準の改定につながったのかということの確認をさせていただきたいと思います。","respondent":"柏木学務課長","answer":"令和５年２月の改正です。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"すみません、私も確認不足だったのですが、学校医の方々だけではなく、教職員の方々も同様の公務災害の水準になっているという理解でいいのでしょうか。今回、飛び抜けてという言い方は変ですが、手厚く学校医の方々の補償を国や都の条例によって変えたということなのか、教職員の方々も今回の改正と同じぐらいの程度のものなのか。","respondent":"柏木学務課長","answer":"当然、教職員の給与等も改正されてありますので、教職員の公務災害に関わる条例のも、東京都で改正しているものと思います。金額的には引上げされているものと考えています。","id":"exchange-005"},{"speaker":"田中委員","kind":"確認","question":"現状の確認をしたいのですが、現在、介護補償を受けていらっしゃる学校医の方々というのはどれぐらいいらっしゃるのかということと、今回の改正に伴って、どれぐらい支給が増えていくのかということについて確認をしたいのですが、いかがでしょうか。","respondent":"柏木学務課長","answer":"事務が変更されたのは平成１４年度ですけれども、それ以降、本区において、こちらの補償の適用となる方は発生してございません。予算額ですが、引き上げられた分だけを想定するという形になってあります。詳細な金額までは承知してございません。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"確認","question":"意見を述べます。国の政令、そして都の条例の改正に合わせて、品川区の条例を改正し、介護補償の限度額を下げるのではなく、上げるということ、それも事前に確認しましたけれども、今、対象となっている方はいらっしゃらないと。学校医、学校歯科医、学校薬剤師という非常に大切な皆様の身分、待遇を守るという意味で、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"第８３号議案、指定管理者の指定","agenda":"第８３号議案、指定管理者の指定","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"前にもご説明あったかもしれないのですが、１つ目に伺いたいのは、大原児童センターが、何階建てであって、何階部分が児童センターになるのか、そのほかの部分が児童発達支援センターになるのかというところをご説明いただきたい。そこからまず伺いたいと思います。","respondent":"藤村子ども育成課長","answer":"こちらの建物は３階建てで、３階が児童センターで、１・２階が児童発達支援センターとなっております。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"今回、詳細な選定結果の報告書を頂いているので、その中で幾つか伺います。３ページのところで、公募の結果、５事業者から応募があり、そのうち１事業者は欠格事由に該当し失格、別の１事業者は応募を辞退したことによるということで、３事業者になったということになっているのですけれども、その辺り、事業者の都合もあると思うのですが、どういう経緯だったのかを教えてください。","respondent":"藤村子ども育成課長","answer":"もう１者の応募を辞退したというところは、社内調整等の結果、区の要求に応えるのが難しいというところでご辞退されたと聞いておりますが、細かい部分というのはお伺いしていません。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"４ページのところで、学研ココファン・ナーサリーの提案では、唯一、統括責任者の配置が提案されていたということが書かれていますけれども、ここは逆に、なぜほかが統括責任者の配置というのを提案されていないのかというところについて。なぜ対応しないのに、提案理由に書いてきたのかということが不可解なのですけれども、その辺りのご説明をお願いします。","respondent":"藤村子ども育成課長","answer":"続きまして、予備委員会ではなくて、選定委員会のほうになりますけれども、学研ココファン・ナーサリーの上から３つ目のところ、事業規模や経費についても柔軟に協議に応じるとの姿勢も評価できるというところなので、ここで柔軟に対応していただくところで。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"選ばれるべくして学研ココファン・ナーサリーが選ばれたのかなと。そもそも一体的な施設の運営を求めている、相乗効果を求めているという話の中で、そもそも統括責任者の配置を、ほかのところは提案しなかったというのが謎です。だから、当然ここが選ばれるのだろうなと思いました。分かりやすい資料とご説明をいただいてありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"田中委員","kind":"提案","question":"今回選ばれたココファン・ナーサリーに関するの意見の中に、１法人でセンターを運営するとの提案は効率的な運営が期待できるとありました。ここにプラスの評価として、効率的な運営となっていますが、子ども未来部として児童センターの運営において効率性を求めることの率直な評価というのでしょうか、それはどういうところから、なぜ効率性を求めたのかというところをお聞かせいただきたいと思います。","respondent":"藤村子ども育成課長","answer":"学研ココファン・ナーサリーにつきましては、予備委員会の中で記載がありますけれども、こども意見箱の設置ですとか、こども基本法ですとか、こども大綱になぞらえたようなかたちで子どもの意見を聴いて管理運営していただくというご発言もございましたので。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"運営において、効率性を追求することによって、子どもに対する手厚いケアに影響がないような形で、効率性を、ぜひ求めていただきたいと思います。確認ですけれども、書きぶりとして、統括責任者を置く際の比重のつけ方というのでしょうか、そこで、どちらかを優先することは絶対あってはいけない。","respondent":"藤村子ども育成課長","answer":"児童発達支援センターと児童センター両方が入る施設ということなので、もちろんそれぞれの役割と目的というのは果たした上でですけれども、統括責任者を置くことによって、例えば今、児童センターで実施している乳幼児親子を対象としたプログラムなど。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"区内でいうと２例目の児童発達支援センターだと思いますが、児童センターとの合築は初めてですので、子ども未来部側からの視点で、児童発達支援センターの運営に対しての相乗効果を出していただくような視点での取組を、ぜひお願いしたいと思いますが、その辺はいかがでしょうか。","respondent":"藤村子ども育成課長","answer":"なかなか交流して遊ぶというところもないということもありますので、今回、児童発達支援センターと同じ建物になりますので、この大原児童センターをきっかけに、交流というか、新しいものが進んでいくような形になればいいかなと思っています。","id":"exchange-014"},{"speaker":"西村委員","kind":"質問・要望","question":"選定理由に、子どもに関連する施設の運営実績が豊富とあります。区内のすまいるスクールで一部、学研ココファン・ナーサリーに委託をしている実績があると思いますので、改めて現在の実績と、学研ココファン・ナーサリーが運営してくださっているすまいるの特徴でしたり、評判でしたり、何か魅力があれば、改めてお聞かせいただきたいと思います。","respondent":"藤村子ども育成課長","answer":"配慮を要する児童が多いところをご担当いただいているような形になっております。いずれにおきましても、しっかりご対応いただいているということで、学校側からも、担当指導員からもお話を伺っているところです。","id":"exchange-015"},{"speaker":"西村委員","kind":"質問","question":"先ほど田中委員からもあったのですけれども、課は変わってしまいますが、もともとこの場所でインクルーシブひろばベルを展開してきたという経緯がある中で、今回新しくなる中でも、インクルーシブな場になるというコンセプトでやっていっていただけると思うので、まさに１法人でセンターを運営していただくことで、建物の動線も含めて。","respondent":"藤村子ども育成課長","answer":"直接行き来できるかというところはあるのですけれども、児童発達支援センターのほうの場所をお借りして、何か事業をするとか、もしくは児童センターのほうの場所を使って事業をするとか、そういった形で、場所で区切らずに交流できるようにはしていきたいと考えています。","id":"exchange-016"},{"speaker":"山本副委員長","kind":"質問","question":"私からも何点か伺います。２ページの選定理由のところで、先ほどほかの委員からも申し上げましたけれども、両センターを一体的に効率よく運営することが期待できるというところなのですが、コストや効果などについて定量的に示されているようなものがあったのでしょうかというところ。","respondent":"藤村子ども育成課長","answer":"定量的にお示しできるコストというところですが、今回、１施設分になるということで、ここで具体的な金額をお示しはできないのですけれども、コストというのは抑えられるようにしていきたいと思っています。","id":"exchange-017"},{"speaker":"山本副委員長","kind":"質問・要望","question":"一体運営の効率化もできるということで、ぜひサービスを落とさずに効率的に運営することも進めていってもらえればと思います。それから、要望となりますけれども、一体運営ということで、事業者が替わるということになります。新しくなるということで、ぜひとも継続的な関係が持続されるように、事業者の方々によく引継ぎが行われるよう、区としても支援、対応をお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-04","title":"第７５号議案、令和６年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７５号議案、令和６年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"そのテーマだけを伺うと、恐らく今までもやっていることなのかなと思うのですが、主体的・協働的な探究活動というところで、今までの取組とどう違うのか、どういう目新しいことを考えられているのか、また、今回は教育委員会については２園ということですけれども、これを今後どのように展開されていくのか、ほかの園等を含めて教えていただきたいと思います。すみません、まとめて質問します。お願いします。","respondent":"芝野保育入園調整課長、荒木学校施設担当課長、柏木学務課長、中谷指導課長、中島保育施設運営課長","answer":"今回の要件としては、令和６年３月１日が工期内にありまして、残工事が２か月以上あることです。したがいまして、労務不足というのは、仮設リース事業者の技術者や技術者の下で働く作業員の方々の労務不足というところを示しております。私からは、補助教材費のご質問にお答えいたします。最初に対象者数ですが、２４５人と想定をしています。２つの園で実施をしていくのは、１５０万円という大変大きな額を扱うものになりますので、いかに教育効果を上げていくかという観点から。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。おおむね子育て、子どもたちの教育の部分については、前向きな補正予算だと思いますので、反対するものではないということと、あとは、特に特別支援学校の補助教材費については、私どもの会派としては要望しておりましたので、なかなか金額も分からないとか、いろいろな事情もあると思うのですけれども、これは速やかにぜひ進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"私も順番に、まとめてお伺いしていきたいと思います。インフレスライドはじめ、議決を経て契約された工事のうち、５％以上の契約金額の変更があったときは議決が必要ということですが、今回それぞれ５％を超えていると思っていて、逆に言うと、５％未満の議決にはかからない、専決で行われるような案件があるのかどうか、これは確認だけさせていただきたいと思います。","respondent":"芝野保育入園調整課長、荒木学校施設担当課長、柏木学務課長、中島保育施設運営課長、中谷指導課長","answer":"大井保育園、中原保育園については今回５％未満のパターンで、議決が必要となる変更はございません。一方で、各事業者からは、他自治体の発注が年度当初に集中したこと、あとは民間の工事も非常に発注が多かったということで。それと、３の（１）支給額のただし書の件ですが、こちらは、特別支援学校には都が実施しています就学奨励費というのがあります。事業の開始年度ということであり、検討期間が必要ということで、全部の園が参加できなかったというところはありますが。","id":"exchange-021"},{"speaker":"西村委員","kind":"質問・要望","question":"１点、気になっておりますのが、他区から通う児童との差が出てくるのだろうと思いますので、その点に関しましては東京都と連携をしていただいて、引き続き意見交換などをお願いしたいと考えています。もう１点。要望ではあるのですけれども、幼稚園だからこそできることと、ハード面の課題があって保育園ではできないこともあろうかと考えています。これは要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"せらく委員","kind":"質問・要望","question":"補助教材費についてなのですけれども、実際の保護者の徴収の仕方が分からないのですが、教材費を区で補助するとなったときに、控えみたいなものが手元にないといった場合は、今年度４月から遡って支給できるということなので、都の就学奨励費について、何か使ったものの一覧というのが出るのか、精算できなかったら大変だなと思ったので、そこの確認をさせていただきたいと思います。","respondent":"柏木学務課長、中島保育施設運営課長","answer":"もしその通知をなくしてしまったとか、手元にないという場合は、学校から再発行してもらうということで対応いただきたいと考えています。テーマにつきましても、複数テーマを一定程度、複数月継続すれば、複数テーマも可能ですし、先ほど申し上げた来年度以降も実施する場合は、テーマを変えるなどすることができますので、そういう形で幅広く。","id":"exchange-023"},{"speaker":"せらく委員","kind":"質問","question":"補助教材費の件も了解いたしました。それで、すみません、もう１点なのですけれども、東京都が実施する研修会等に参加というのは、実施する園の各１名などを対象にされるような形を想定されているのでしょうか。誰が参加するかというところを教えていただけたらと思います。","respondent":"中島保育施設運営課長","answer":"その中の専門家から、プログラムの活用方法でありますとか、乳幼児の教育の基調講演なども含まれておりますので、幅広く、参加する先生方がご覧いただいて、アンケートに答える形で研修参加という形となっています。","id":"exchange-024"}]},{"id":"topic-05","title":"令和６年請願第１３号、品川区立小中学校の社会科見学・授業等で防衛省見学・自衛隊見学・自衛隊体験などを行わないことを求める請願","agenda":"令和６年請願第１３号、品川区立小中学校の社会科見学・授業等で防衛省見学・自衛隊見学・自衛隊体験などを行わないことを求める請願","exchanges":[{"speaker":"西村委員","kind":"意見","question":"国の機能を学んでいる小学６年生のタイミングで、社会意識の高まりとともに、学んでいただく必要のある内容ではないかと私も思うのですが、小学６年生が国会議事堂に行く際に、ほかに、防衛省・自衛隊以外にどのような行き先を各学校が選んでいるのか、ほかの行き先もお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"ほかの事例といたしましては、６年生で三権分立を学習しますので、その中で、最高裁判所を選んでいる学校もあります。近隣の施設として、科学技術館等といったところに立ち寄って、社会科と理科と合わせてという形の学習も行っている学校が多くあります。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"今、西村委員からも他の施設をということがありましたが、ここにあるように、防衛省の見学を実際に行っている学校というのは、どれぐらいあるのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"小学校・義務教育学校前期課程６年生、３７校分ありますけれども、順次、校外学習で国会議事堂、これはほぼ全校が行っています。その中で防衛省を選んだ学校は、１学期の間では１校のみでございました。","id":"exchange-026"},{"speaker":"西村委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いしたいと考えています。理由を述べします。ほかの社会学習と公平に扱う観点からは、小中学校に特定の国の機関の見学・体験を行わないように求めることは、子どもたちの学習機会そのものを奪うことになり、望ましくないのではないかと考えますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"本日結論を出すで、不採択です。それを逆に考えれば、国会議事堂を見学すれば、皆さん国会議員に勧誘しているのですかという話になりますから、ほかの省庁はほかの省庁で勧誘しているのですかという話になるのです。しかも、この３番目については、先ほど教育委員会が、一切そんなことは官公庁においても民間においても、教育委員会として勧めているものではないという発言もありましたし、私もそう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"山本副委員長","kind":"質問","question":"本日結論を出すでお願いします。理由を述べします。西村委員からもご説明ありましたけれども、理事者の方がご説明いただきました見学の内容において、社会学習として適切に行われていると考えております。本件は会派として不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由は、これまで３名の委員が述べていらっしゃった内容に同意いたしまして、さらに、自分の思いで付け加えますと、子どもの学びや成長、経験といったところを制限するものではないと思いまして、不採択としました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"本日結論を出すで、請願項目の３つに関して、今ご説明ありましたけれども、不採択でお願いします。２番目、３番目の項目に関しては、教育委員会主催のいろいろな行事などでは、２番目、３番目のことは行っていないということですので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。今回の請願をきっかけに知りましたが、品川の公立学校で防衛省へ社会科見学に行かれているということは、大変すばらしいことだと思いますし、１校にとどまらず、他校へのこういう流れが続くことを期待しております。以上から、今回の請願に対しては不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-06","title":"令和６年陳情第４７号、ＭＲデバイスを教育利用する設備を設置する陳情","agenda":"令和６年陳情第４７号、ＭＲデバイスを教育利用する設備を設置する陳情","exchanges":[{"speaker":"西村委員","kind":"質問","question":"ただ、品川区にはＩＣＴ推進校がありますので、改めて伺いたいのですが、現在何校ありまして、どのような特化した取組があるのか、また、今後、推進校の取組を全校にどのように広げていくのかを改めてお聞かせいただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"２年間の研究の最後には研究発表会を行っておりまして、それぞれ各校から代表者が集まって、授業公開を見たり、研究発表を聞いて自校に持ち帰るということを毎年行っておりますので、そういったいい取組が区内に広がるように、これからもサポートしていきたいと考えております。","id":"exchange-033"},{"speaker":"西村委員","kind":"質問・要望","question":"例えば、千葉県の印西市でしたらＡｍａｚｏｎですとか、埼玉県戸田市ではインテルですとか、そういった先端技術を学校教育に取り込んで、ＳＴＥＡＭ教育に取り組んでいるような官民連携の取組は、今後検討してみていただきたいとは個人的に思っております。もう１点だけ、パソコンルームがあると思うのですが、現在どのように活用しているのかと、今後どのように活用していくのか伺えればと思います。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"各校のパソコンルーム、ＰＣルームについてですけれども、現在、１人１台端末が配備されたことで、日常的に教室、体育館、校庭等を含めて、あらゆる場所で１人１台端末が、活用されています。これはｉＰａｄになります。私からは、パソコン教室の今後の考え方ですけれども、教育委員会として、継続する、なくす等を含めて、何か決定しているものではございませんが、他区の状況ではパソコン教室をなくしているという話も聞いてありますので、他区の状況。","id":"exchange-034"},{"speaker":"西村委員","kind":"意見","question":"パソコンルームがお教室のように完全に仕切られているスペースではないような学校も多いと思いますが、今、生徒・児童が増えているような学校もあったりと、これから検討していかれるということなので、どのように活用されるかいいかは、これからぜひしっかりとご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"本筋とは少し違う話で、先ほど朗読を聞いていて、また読ませていただいて、教えていただければと思うのですが、教育現場で昨今問題になっているカエルの解剖、例示としてこれを載せていると思うのですけれども、例えば、ふだん使っている理科室に解剖用の魚が現れるというお話があるのですが、現状は区立の学校で、ここは区立で別に限定するわけではないのですけれども、教育現場で。","respondent":"丸谷教育総合支援センター長","answer":"その中で実習をしながら、イカの器官について学習していくわけですけれども、イカの本体をそろえたりすることが難しい場合には、写真で見たり、動画で見たりということを、それこそ補助的に行っている場合もありますが、実物に触れるというのがベストなことです。","id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"これはこれで、本物を見て手に取って触ってということも必要だと思いますが、一方で、なかなか実物を手にすることもできない、そういうものに対しても、興味や関心を持っていただいたり、そこから学びを広げていただくという意味では、こういうＩＣＴ技術を、さらに有効に活用しなければいけないと思っているのですが、先ほどのご説明を伺うと、実物のほうを重視していらっしゃるようなお話ではありますが。","respondent":"丸谷教育総合支援センター長","answer":"今後こういったＶＲであるとか、今言われているＭＲであるとか、こういう技術が日常的になってくれば、それがまさに子どもたちが３６０度見回すとか、そういったことでの体験につながっていくものだと思いますので、否定するものではなくて。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問・要望","question":"このＭＲデバイスは最新技術で、専門的な知識が必要なのかなと思って読んでいました。品川区には五反田など、特色がある地域がある中で、例えばコミュニティ・スクールとかで、そういったところからの講師をいただいたりとか、そういった事例があれば教えていただきたいのと、今後そういったところから、コミュニティ・スクールにご協力いただくことは可能かどうか、お話をお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"事例としては、今把握しているものはないのですけれども、今後そういった形での連携ができると、より効果的だと考えます。","id":"exchange-038"},{"speaker":"西村委員","kind":"意見","question":"高額で短期間でバージョンアップを繰り返したり、流行性がある可能性のある最先端のデジタル機材は、ご指摘のとおり、区が数台購入し、体験スペースで子どもたちに体験させるというのは、一つのアイデアだと思いましたが、現時点ではあまりに高額であることや、体験ゾーンの設置場所、運用期間、運用時間帯、インストラクターの手配なども含めて、予算編成や区の教育方針における位置づけなど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"意見","question":"本日結論を出すで、不採択としたいと思います。理由といたしましては、先ほど自民党からもありましたけれども、私もＭＲというものについて不勉強で、今回の審査に当たって、ネット等で見させていただいて、どういうものかというのを自分でもそれなりに勉強して、非常にすばらしい技術であるということを実感いたしました。ただ、先ほどもありましたように、技術としては日進月歩であるということ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"山本副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。一方で、現在のＭＲは１台当たりが高価であり、数台であったとしても高額となるという価格の面と、仮に数台導入したとしても、２万人を超える区立小中学生の多くの皆さんに触れてもらおうとすると、機会の平等性という点で課題があると考えます。そのような検討や、検討の支援を要望いたします。今後の技術進歩を確認しながら、研究を進めてほしいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。それで、区で購入してはどうかという部分で、どうしても判断が難しかったのですけれども、この陳情自体はまちの価値を高めるようなものだったと感じておりまして、そういう部分では、私自身は、ご相談もいただく不登校だったり、いじめだったり、就学の壁などの支援のほうに振り向けたいと思いまして、この判断をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。は現状で、１人１台の端末とか電子黒板など、様々なシステムを教育委員会で導入しているので、現状の課題を解決し、そして、現状の仕組みをまず最大限活用することを進めていらっしゃると思うのですけれども、さらに進めていただければと思います。これは陳情とは別で、要望になりますけれどもお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すでお願いしたいと思います。先ほど述べましたが、陳情者の方の文章の中にある、ＶＲやＡＲは既に過去のものとなっている、という内容すら私自身は追いついていない。私はもう１０周遅れぐらいの者ですが、今回いただいた陳情の、極めて先進的な知識を持っていらして、その技術を教育に活かすべきだというご提言は、大変すばらしいものでありますし、しっかり受け止めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-07","title":"専決処分の報告について（報告第２５号）","agenda":"専決処分の報告について（報告第２５号）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"今後の訴訟の中で、和解であるとか、強制執行まで行くのかとかいう流れを教えていただきたいのが１点です。それと、訴額は今回、No.１の方については３９万円ということなのですけれども、これは簡易裁判所で、少額訴訟の方式でやられているのか、それとも普通の訴訟の方式でやられているのか教えてください。","respondent":"飛田子育て応援課長","answer":"この後の手続ですけれども、まず判決をいただきまして、一括または分割で納付させるようになります。ただ、その後、また納付等手続を行いまして、執行されない、返還されない場合は、強制執行または債権放棄という流れとなります。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"普通の訴訟ということなのですか。たしか６０万円以下の少額の場合は、簡易裁判所で、１日で結論が出る少額訴訟という制度があると思うのですけれども、そういうのは使わないで、普通に訴訟されるということで、No.１の方についてもそれでよろしいのでしょうか。","respondent":"飛田子育て応援課長","answer":"１番の方については、住所がまだ不明というところもありますので、まず裁判所で、そこのところをどのようにしていくかというところが決められると聞いております。","id":"exchange-046"},{"speaker":"田中委員","kind":"質問・要望","question":"要は、ここで早くお納めいただければ、この訴額で済むけれども、これまでの傾向として借手側は負ける可能性が高く、裁判になるといろいろともろもろ、しかも訴額以上のものの負担を強いられますよと、求める際にそういう先のことまでお伝えして、そういうことを言っていいのかどうかというのもあるのですけれども、過去の事例としてそういう可能性もありますよという。","respondent":"飛田子育て応援課長","answer":"大体、訴えを起こしまして、全ての判決が和解や分納合意ということで、継続的に支払いをしていただくというふうになっております。先ほどの滞納のほうですが、今回提起した２件は違約金が発生するということで、１０％の違約金が発生いたします。","id":"exchange-047"},{"speaker":"田中委員","kind":"確認","question":"もう一度確認ですが、先方が借りた金額プラス、最終的に支払わなければいけない日から換算して、その分の利子が違約金として加わってという、そこまでは伝わっていて、早くお納めくださいと、そういう流れということでしょうか。","respondent":"飛田子育て応援課長","answer":"そのようになります。","id":"exchange-048"},{"speaker":"せらく委員","kind":"質問","question":"すみません、少し聞き取れなかった部分がありまして、No.１もNo.２も平成のときに支払いをしていて、返還されなくなってから１０年ぐらいたってしまうようなことになっているということでしょうか。","respondent":"飛田子育て応援課長","answer":"２番の方です。こちらの方は、令和元年５月が最終支払いで、その後、何も連絡がないということで、令和４年１１月より弁護士にお願いをしているという流れになっております。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"これは同じく２９号も、ガラスがこの金額なのですけれども、こんなにするのかなというのは素朴な疑問として感じるのですが、部活動において、フェンスを越えて、こういう事故は起こりがちなところがあると思いますが、いわゆる保険というのは入っているのか入っていないのか、また今回、どういうものが対象になっているのかというところを、まず確認させていただきたいと思います。","respondent":"舩木庶務課長","answer":"学校の保険に関しましては、こちらは特別区の自治体総合賠償責任保険による賠償手続をするということで、まず事実確認をして、それから被害の状況も確認した上で、その後、事実確認に基づいて、それぞれディーラーといいますか。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"特に大崎中はタイミングの問題で、誰が打ったか分からないというところがあるのかもしれませんが、特に子どもに対するフォローというのでしょうか、それは決して萎縮させないような方向で、ぜひ対応を取っていただきたいと思いますが、どんな対応をされたのかお聞かせいただきたいと思います。","respondent":"舩木庶務課長","answer":"部活動の事故におきましては、４月から６月に新入生が入ってくるわけですが、そういった時期にまれに入部間もない不慣れな新入部員が、起こしてしまいがちだというケースもあることをしっかりと共有した上で、お子さん自体には萎縮するようなことがないように。","id":"exchange-051"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"名のり出た方は、通報された１名だけだということです。閲覧したかどうかの調査とありましたが、それはダウンロードができるようなファイル形式だったのか、その辺りも教えてください。","respondent":"丸谷教育総合支援センター長","answer":"当然、資料箱ということで、学習に活用する資料をそこに保存するべきところですので、データはダウンロード可能なものでございました。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"確認","question":"漏えいの事実は認められないということですけれども、もう１点だけお聞きします。ダウンロードされたかどうかというのは、いわゆるアップロード元というか、学校では確認ができるのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そのフォルダからダウンロードしたかどうかのログを確認することは、極めて困難だということです。ただ、学校は児童一人一人に対して、資料箱を見た人はいるかどうかという確認をしたところ、誰もいなかったということですので、そういったところで今回は収まっているです。","id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問","question":"児童も閲覧可能なところに入れてしまったということは、どなたか、教員が入れてしまったわけですが、その方は、後からあのときにミスして入れてしまったということは、分かったのですか。","respondent":"丸谷教育総合支援センター長","answer":"保護者から指摘をいただきまして、確認したところ、ファイルが置きっ放しになっていたということで、そこに保存した教員については、誤ってそこに保存してしまったという認識は、言われて初めて気づいたです。","id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、ご自分でいつそこに入れてしまったかは、記憶がないという認識でよろしいですか。","respondent":"丸谷教育総合支援センター長","answer":"９月３日の夕方、午後４時３０分頃に、ダウンロードして保存したということは覚えていらっしゃるのですけれども、それが、全児童が見られる保存先だったというところについては、自身の認識の甘さというか、誤ってそこに入れてしまったという自覚はあります。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/799105?Template=document&Id=6815#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":43691,"voices":201}}]);
